import site


def _asegurar_entorno_y_dependencias_inicio() -> None:
    """
    Verifica al iniciar desde VS Code o terminal que el intérprete de Python actual
    tenga instaladas las librerías esenciales (`matplotlib`, `numpy`, `pandas`, `PIL`,
    `requests`, `certifi`, `openpyxl`, `yfinance`, `bcchapi`).
    - Si todas están presentes, retorna en < 1 ms sin hacer nada.
    - Si falta alguna librería (por ejemplo `ModuleNotFoundError: No module named 'matplotlib'`
      al cambiar de entorno en VS Code), intenta instalarla automáticamente con `pip` en el
      intérprete actual; y si el intérprete actual no soporta `pip` o wheels binarios,
      delega automáticamente la ejecución al intérprete Python completo instalado en el PC.
    """
    if getattr(sys, "frozen", False):
        return

    paquetes_esenciales = [
        ("matplotlib", "matplotlib"),
        ("numpy", "numpy"),
        ("pandas", "pandas"),
        ("scipy", "scipy"),
        ("pillow", "PIL"),
        ("requests", "requests"),
        ("certifi", "certifi"),
        ("openpyxl", "openpyxl"),
    ]
    paquetes_opcionales = [
        ("yfinance", "yfinance"),
        ("bcchapi", "bcchapi"),
    ]
    esenciales_faltantes = [
        pip_pkg
        for pip_pkg, mod_name in paquetes_esenciales
        if importlib.util.find_spec(mod_name) is None
    ]
    if not esenciales_faltantes:
        return
    faltantes = esenciales_faltantes + [
        pip_pkg
        for pip_pkg, mod_name in paquetes_opcionales
        if importlib.util.find_spec(mod_name) is None
    ]

    # 1. Resolver ejecutable python.exe de consola del entorno actual
    py_actual = Path(sys.executable).resolve()
    if platform.system() == "Windows" and py_actual.name.lower() == "pythonw.exe":
        cand_con = py_actual.with_name("python.exe")
        if cand_con.is_file():
            py_actual = cand_con

    print(
        f"[EcoPulse Analytics] Detectadas librerías faltantes en '{py_actual}': {', '.join(faltantes)}. "
        "Instalando automáticamente..."
    )

    # Asegurar que pip esté disponible en este intérprete
    try:
        subprocess.run(
            [str(py_actual), "-m", "ensurepip", "--upgrade"],
            check=False,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except Exception:
        pass

    # Instalar paquetes faltantes en el intérprete actual
    for pkg in faltantes:
        try:
            res = subprocess.run(
                [
                    str(py_actual),
                    "-m",
                    "pip",
                    "install",
                    "--prefer-binary",
                    "--disable-pip-version-check",
                    pkg,
                ],
                check=False,
            )
            if res.returncode != 0:
                subprocess.run(
                    [
                        str(py_actual),
                        "-m",
                        "pip",
                        "install",
                        "--user",
                        "--prefer-binary",
                        "--disable-pip-version-check",
                        pkg,
                    ],
                    check=False,
                )
        except Exception:
            pass

    # Refrescar rutas de site-packages en el proceso en curso
    try:
        importlib.invalidate_caches()
        rutas_site: List[str] = []
        if hasattr(site, "getsitepackages"):
            rutas_site.extend(site.getsitepackages())
        if hasattr(site, "getusersitepackages"):
            u_site = site.getusersitepackages()
            if isinstance(u_site, str):
                rutas_site.append(u_site)
        for r_s in rutas_site:
            if r_s and os.path.isdir(r_s) and r_s not in sys.path:
                sys.path.insert(0, r_s)
        importlib.invalidate_caches()
    except Exception:
        pass

    # 2. Si después de pip install aún falta matplotlib/numpy/pandas (p. ej. entorno sin compilador o sin pip)
    #    buscar otro intérprete Python instalado en el PC que ya tenga las librerías y re-ejecutar con él
    criticos_faltantes = [
        mod_c for mod_c in ("matplotlib", "numpy", "pandas")
        if importlib.util.find_spec(mod_c) is None
    ]
    if criticos_faltantes and os.environ.get("ECOPULSE_REEXEC_GUARD") != "1":
        candidatos_py: List[Path] = []
        stamp_file = Path.home() / "EcoPulse_Analytics" / ".entorno_verificado_v55.ok"
        if stamp_file.is_file():
            try:
                ruta_st = Path(stamp_file.read_text(encoding="utf-8").strip())
                if ruta_st.is_file():
                    candidatos_py.append(ruta_st.with_name("python.exe") if ruta_st.name.lower() == "pythonw.exe" else ruta_st)
            except Exception:
                pass

        if platform.system() == "Windows":
            raices_win = [
                Path(os.environ.get("LOCALAPPDATA", "")) / "Programs" / "Python",
                Path("C:/Program Files"),
                Path("C:/"),
            ]
            for r_base in raices_win:
                if r_base.is_dir():
                    for sub in sorted(r_base.glob("Python3*"), reverse=True):
                        cand_p = sub / "python.exe"
                        if cand_p.is_file():
                            candidatos_py.append(cand_p)

        for cand_py in candidatos_py:
            try:
                if cand_py.resolve() == py_actual.resolve():
                    continue
                chk = subprocess.run(
                    [str(cand_py), "-c", "import matplotlib, numpy, pandas, PIL; print('OK')"],
                    capture_output=True,
                    text=True,
                    timeout=10,
                )
                if chk.returncode == 0 and "OK" in (chk.stdout or ""):
                    print(f"[EcoPulse Analytics] Redirigiendo ejecución al intérprete completo: {cand_py}")
                    env_nuevo = os.environ.copy()
                    env_nuevo["ECOPULSE_REEXEC_GUARD"] = "1"
                    codigo_salida = subprocess.call(
                        [str(cand_py), str(Path(__file__).resolve()), *sys.argv[1:]],
                        env=env_nuevo,
                    )
                    sys.exit(codigo_salida)
            except Exception:
                pass


_asegurar_entorno_y_dependencias_inicio()

