_contador_por_cat_extra: Dict[str, int] = {}
for _item_cp in _VISTAS_COTIZACIONES_Y_PROYECCIONES_RAW:
    _d_cp = dict(_item_cp)
    _cat_k = str(_item_cp.get("categoria", "cotizaciones"))
    _idx_c_loc = _contador_por_cat_extra.get(_cat_k, 0) + 1
    _contador_por_cat_extra[_cat_k] = _idx_c_loc
    _pref_c = PREFIJOS_CODIGO_CATEGORIA.get(_cat_k, _cat_k[:3].upper())
    _d_cp["numero"] = str(_contador_num_vista)
    _d_cp["orden_subcategoria"] = str(_idx_c_loc)
    _d_cp["codigo"] = f"{_pref_c}-{_idx_c_loc:02d}"
    _d_cp["codigo_global"] = f"V-{_contador_num_vista:02d}"
    _d_cp["titulo"] = f"{_item_cp['titulo_base']}"
    _d_cp["corto"] = f"{_item_cp['icono']} {_item_cp['corto_base']}"
    CATALOGO_VISTAS_MACRO.append(_d_cp)
    _contador_num_vista += 1

