def obtener_config_botones_vista_macro(clave_vista: str) -> Dict[str, object]:
    """
    Devuelve la configuración exacta de botones interactivos (tipo Cotizaciones de Precio)
    que corresponden específicamente a cada gráfico macroeconómico (`clave_vista`):
      - `frecuencias`: Lista de códigos de frecuencia aplicables al gráfico (vacía si es anual fijo o corte transversal).
      - `mostrar_modo`: True sólo si el gráfico admite alternar entre Variación (% a/a) y Nivel/Índice.
      - `etiquetas_modo`: Par `(etiqueta_yoy, etiqueta_nivel)` adaptado al gráfico.
      - `mostrar_ventana`: True si es una serie de tiempo con eje X temporal; False si es ranking o tabla de 1 solo corte.
      - `baci`: True si corresponde mostrar el botón `📦 BACI`.
      - `ptf`: True si corresponde mostrar el botón `📂 PTF`.
    """
    meta = MAPA_VISTAS_MACRO.get(clave_vista, {})
    clave_base = str(meta.get("clave_base", clave_vista.rsplit("_", 1)[0] if "_" in clave_vista else clave_vista))
    panel_idx = int(meta.get("panel_idx", "1")) if str(meta.get("panel_idx", "1")).isdigit() else 1

    # Valores por defecto según bloque base
    frecuencias: List[str] = ["original", "mensual", "trimestral", "anual"]
    mostrar_modo: bool = False
    etiquetas_modo: Tuple[str, str] = ("% a/a", "Nivel")
    mostrar_ventana: bool = True
    baci: bool = False
    ptf: bool = False

    if clave_base == "imacec":
        if panel_idx in (1, 2, 3):
            frecuencias = ["mensual", "trimestral", "anual"]
            mostrar_modo = True
            etiquetas_modo = ("Var. % a/a", "Índice 2018=100")
            mostrar_ventana = True
        else:
            # Panel 4: Ranking transversal del último período
            frecuencias = ["mensual", "trimestral", "anual"]
            mostrar_modo = True
            etiquetas_modo = ("Var. % a/a", "Índice 2018=100")
            mostrar_ventana = False
    elif clave_base == "ccnn":
        if panel_idx in (1, 2):
            frecuencias = ["trimestral", "anual"]
        else:
            frecuencias = ["mensual", "trimestral", "anual"]
        mostrar_modo = False
        mostrar_ventana = True
    elif clave_base == "pib_potencial":
        frecuencias = ["trimestral", "anual"]
        mostrar_modo = True
        etiquetas_modo = ("MM$ + Brechas", "Brecha % PIB")
        mostrar_ventana = True
    elif clave_base == "consumo_bcch":
        if panel_idx == 5:
            frecuencias = ["mensual", "trimestral", "anual"]
            mostrar_modo = True
            etiquetas_modo = ("Var. % a/a", "Unidades Vend.")
            mostrar_ventana = True
        elif panel_idx == 6:
            frecuencias = ["trimestral", "anual"]
            mostrar_modo = True
            etiquetas_modo = ("Var. % a/a", "Nivel USD / Hab.")
            mostrar_ventana = True
        elif panel_idx == 4:
            frecuencias = ["trimestral", "anual"]
            mostrar_modo = True
            etiquetas_modo = ("Incidencias pp.", "% del PIB")
            mostrar_ventana = True
        else:
            frecuencias = ["trimestral", "anual"]
            mostrar_modo = True
            etiquetas_modo = ("Var. % a/a", "Nivel MM$")
            mostrar_ventana = True
    elif clave_base == "tcr":
        if panel_idx == 4:
            frecuencias = ["diaria", "mensual", "trimestral", "anual"]
        else:
            frecuencias = ["mensual", "trimestral", "anual"]
        mostrar_modo = (panel_idx == 3)
        etiquetas_modo = ("Var. % a/a", "Nivel 1986=100")
        mostrar_ventana = True
    elif clave_base == "ipc":
        if panel_idx in (1, 2):
            frecuencias = ["mensual", "trimestral", "anual"]
            mostrar_ventana = True
        else:
            frecuencias = ["mensual", "trimestral", "anual"]
            mostrar_ventana = False
        mostrar_modo = False
    elif clave_base == "empleo":
        frecuencias = ["mensual", "trimestral", "anual"]
        mostrar_modo = False
        mostrar_ventana = (panel_idx in (1, 2, 3))
    elif clave_base == "empleo_dash":
        frecuencias = ["mensual", "trimestral", "anual"]
        mostrar_modo = True
        etiquetas_modo = ("Tasas (%)", "Miles Personas")
        mostrar_ventana = True
    elif clave_base == "empleo_ene":
        frecuencias = ["mensual", "trimestral", "anual"]
        mostrar_modo = True
        mostrar_ventana = True
        if panel_idx == 1:
            etiquetas_modo = ("% del Empleo", "Miles Ocupados")
        elif panel_idx == 2:
            etiquetas_modo = ("Tasa Desemp. (%)", "Var. 12M (pp)")
        elif panel_idx == 3:
            etiquetas_modo = ("Tasa Desemp. (%)", "% Empleo Extranj.")
        elif panel_idx == 4:
            etiquetas_modo = ("% del Empleo", "Miles en Apps")
        elif panel_idx == 5:
            etiquetas_modo = ("Tasa Desemp. (%)", "Brecha M−H (pp)")
        elif panel_idx == 6:
            etiquetas_modo = ("Tasa Desemp. (%)", "Var. 12M (pp)")
        else:
            etiquetas_modo = ("Serie Histórica (%)", "Ranking 16 Regiones")
    elif clave_base == "finanzas":
        frecuencias = ["trimestral", "anual"]
        mostrar_modo = False
        mostrar_ventana = True
    elif clave_base == "capital":
        if panel_idx in (1, 2):
            frecuencias = []
            mostrar_modo = False
            mostrar_ventana = True
        elif panel_idx == 3:
            frecuencias = []
            mostrar_modo = True
            etiquetas_modo = ("Var. % a/a", "Nivel MM$")
            mostrar_ventana = True
        else:
            frecuencias = ["trimestral", "anual"]
            mostrar_modo = True
            etiquetas_modo = ("Var. % a/a", "Nivel MM$")
            mostrar_ventana = True
    elif clave_base == "ahorro_deuda":
        frecuencias = ["trimestral", "anual"]
        mostrar_modo = True
        etiquetas_modo = ("% del PIB", "Nivel MM$")
        mostrar_ventana = True
    elif clave_base == "monetaria":
        if panel_idx in (1, 2):
            frecuencias = ["diaria", "mensual", "trimestral", "anual"]
        else:
            frecuencias = ["mensual", "trimestral", "anual"]
        mostrar_modo = (panel_idx in (2, 4))
        etiquetas_modo = ("Var. / Cambio", "Nivel / Tasa")
        mostrar_ventana = True
    elif clave_base == "externo":
        if panel_idx == 3:
            frecuencias = ["mensual", "trimestral", "anual"]
        else:
            frecuencias = ["trimestral", "anual"]
        mostrar_modo = (panel_idx in (1, 2, 3, 5, 6))
        etiquetas_modo = ("Var. % a/a", "Volumen / Índice") if panel_idx in (5, 6) else ("Var. % a/a", "Nivel MM USD")
        mostrar_ventana = True
    elif clave_base == "deuda":
        frecuencias = ["trimestral", "anual"]
        mostrar_modo = (panel_idx == 4)
        etiquetas_modo = ("Var. % a/a", "Nivel MM$")
        mostrar_ventana = True
    elif clave_base == "exportaciones_ipi":
        baci = (panel_idx in (1, 2, 4))
        if panel_idx in (1, 2):
            frecuencias = []
            mostrar_modo = True
            etiquetas_modo = ("Var. pp a/a", "% Participación")
            mostrar_ventana = True
        elif panel_idx == 3:
            frecuencias = ["mensual", "trimestral", "anual"]
            mostrar_modo = True
            etiquetas_modo = ("Var. % a/a", "Índice 2018=100")
            mostrar_ventana = True
        else:
            frecuencias = []
            mostrar_modo = False
            mostrar_ventana = True
    elif clave_base == "ptf_clapes":
        ptf = True
        frecuencias = ["trimestral", "anual"]
        mostrar_modo = (panel_idx == 1)
        etiquetas_modo = ("Var. % a/a", "Índice 2018=100")
        mostrar_ventana = (panel_idx in (1, 2, 3))
    elif clave_base == "ptf_cnep":
        ptf = True
        frecuencias = []
        mostrar_modo = (panel_idx == 4)
        etiquetas_modo = ("Var. % a/a", "Índice 2018=100")
        mostrar_ventana = True

    return {
        "frecuencias": frecuencias,
        "mostrar_modo": mostrar_modo,
        "etiquetas_modo": etiquetas_modo,
        "mostrar_ventana": mostrar_ventana,
        "baci": baci,
        "ptf": ptf,
    }

