ORDEN_CLAVES_VISTAS: List[str] = [v["clave"] for v in CATALOGO_VISTAS_MACRO]
CATALOGO_VINETAS_MACRO = CATALOGO_VISTAS_MACRO
ORDEN_CLAVES_VINETAS = ORDEN_CLAVES_VISTAS
MAPA_CATEGORIAS_PRINCIPALES: Dict[str, Dict[str, object]] = {}
MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA: Dict[str, str] = {}
CATALOGO_BUSQUEDA_VISTAS: List[Dict[str, str]] = []


def _normalizar_texto_busqueda(texto: str) -> str:
    """Normaliza texto en minúsculas y sin tildes para búsquedas instantáneas."""
    tabla_tildes = str.maketrans("áéíóúäëïöüñÁÉÍÓÚÄËÏÖÜÑ", "aeiouaeiounAEIOUAEIOUN")
    return str(texto or "").translate(tabla_tildes).lower().strip()


_CACHE_HUELLA_CATALOGO_VISTAS: Dict[str, object] = {"huella": None, "resumen": None}


def sincronizar_catalogo_y_contadores_vistas(forzar: bool = False) -> Dict[str, int]:
    """
    Reorganiza automáticamente el orden y número correlativo de todas las categorías,
    subcategorías y vistas de EcoPulse Analytics, genera el código único por vista
    (`codigo`, `codigo_global`, `codigo_jerarquico`) y actualiza dinámicamente todos los
    contadores y etiquetas de cantidad cuando cambia el número de categorías, subcategorías o vistas.
    Utiliza caché instantáneo en memoria (0.001 ms) si la estructura no ha variado.
    """
    import re

    huella_actual = (
        len(CATEGORIAS_PRINCIPALES_VISTAS),
        len(SUBCATEGORIAS_MACROECONOMICAS),
        len(CATALOGO_VISTAS_MACRO),
        tuple(str(s.get("titulo", "")) for s in SUBCATEGORIAS_MACROECONOMICAS),
        tuple(str(v.get("clave", "")) for v in CATALOGO_VISTAS_MACRO),
    )
    if (
        not forzar
        and _CACHE_HUELLA_CATALOGO_VISTAS.get("huella") == huella_actual
        and isinstance(_CACHE_HUELLA_CATALOGO_VISTAS.get("resumen"), dict)
        and CATALOGO_BUSQUEDA_VISTAS
    ):
        return _CACHE_HUELLA_CATALOGO_VISTAS["resumen"]  # type: ignore[return-value]
    # 1. Numerar automáticamente las Subcategorías Macroeconómicas en orden (1..N_sub)
    MAPA_SUBCATEGORIAS_MACRO.clear()
    orden_sub_claves: List[str] = []
    for idx_s, sub in enumerate(SUBCATEGORIAS_MACROECONOMICAS, 1):
        clave_s = str(sub["clave_sub"])
        orden_sub_claves.append(clave_s)
        nom_limpio_s = str(sub.get("nombre_limpio") or str(sub.get("titulo", "")).split(". ", 1)[-1]).strip()
        sub["nombre_limpio"] = nom_limpio_s
        sub["numero"] = str(idx_s)
        sub["titulo"] = f"{idx_s}. {nom_limpio_s}"
        pref_s = str(sub.get("prefijo_codigo") or PREFIJOS_CODIGO_SUBCATEGORIA_MACRO.get(clave_s, nom_limpio_s[:3].upper()))
        sub["prefijo_codigo"] = pref_s
        sub["codigo_sub"] = f"2.{idx_s}"
        MAPA_SUBCATEGORIAS_MACRO[clave_s] = sub

    # 2. Numerar automáticamente las Categorías Principales (1..N_cat)
    MAPA_CATEGORIAS_PRINCIPALES.clear()
    orden_cat_claves: List[str] = []
    for idx_c, cat in enumerate(CATEGORIAS_PRINCIPALES_VISTAS, 1):
        clave_c = str(cat["clave_categoria"])
        orden_cat_claves.append(clave_c)
        nom_limpio_c = str(cat.get("nombre_limpio") or str(cat.get("titulo", "")).split(". ", 1)[-1]).strip()
        cat["nombre_limpio"] = nom_limpio_c
        cat["numero_cat"] = str(idx_c)
        cat["titulo"] = f"{idx_c}. {nom_limpio_c}"
        pref_c = str(cat.get("prefijo_codigo") or PREFIJOS_CODIGO_CATEGORIA.get(clave_c, nom_limpio_c[:3].upper()))
        cat["prefijo_codigo"] = pref_c
        MAPA_CATEGORIAS_PRINCIPALES[clave_c] = cat

    # 3. Reorganizar CATALOGO_VISTAS_MACRO siguiendo estrictamente el orden de Categorías -> Subcategorías -> Paneles
    def _clave_orden_vista(item_v: Dict[str, str]) -> Tuple[int, int, int]:
        cat_v = str(item_v.get("categoria", "macroeconomicas"))
        idx_cat_v = orden_cat_claves.index(cat_v) if cat_v in orden_cat_claves else 999
        if cat_v == "macroeconomicas":
            sub_v = str(item_v.get("subcategoria_clave", ""))
            idx_sub_v = orden_sub_claves.index(sub_v) if sub_v in orden_sub_claves else 999
        else:
            idx_sub_v = 0
        return (idx_cat_v, idx_sub_v, 0)

    vistas_ordenadas = sorted(list(CATALOGO_VISTAS_MACRO), key=_clave_orden_vista)
    CATALOGO_VISTAS_MACRO.clear()
    CATALOGO_VISTAS_MACRO.extend(vistas_ordenadas)

    # 4. Asignar número correlativo global (1..Total), orden local y Código Único por Vista
    contadores_grupo: Dict[str, int] = {}
    totales_grupo: Dict[str, int] = {}
    for v in CATALOGO_VISTAS_MACRO:
        cat_v = str(v.get("categoria", "macroeconomicas"))
        clave_grp = str(v.get("subcategoria_clave", "")) if cat_v == "macroeconomicas" else cat_v
        totales_grupo[clave_grp] = totales_grupo.get(clave_grp, 0) + 1

    total_vistas_global = len(CATALOGO_VISTAS_MACRO)
    MAPA_VISTAS_MACRO.clear()
    MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA.clear()

    for idx_global, v in enumerate(CATALOGO_VISTAS_MACRO, 1):
        cat_v = str(v.get("categoria", "macroeconomicas"))
        info_cat = MAPA_CATEGORIAS_PRINCIPALES.get(cat_v, {})
        num_cat_str = str(info_cat.get("numero_cat", "2"))
        nom_cat_limpio = str(info_cat.get("nombre_limpio", v.get("categoria_nombre", "Vistas Macroeconómicas")))
        v["categoria_numero"] = num_cat_str
        v["categoria_nombre"] = nom_cat_limpio

        if cat_v == "macroeconomicas":
            sub_k = str(v.get("subcategoria_clave", "sub_actividad"))
            info_sub = MAPA_SUBCATEGORIAS_MACRO.get(sub_k, {})
            num_sub_str = str(info_sub.get("numero", "1"))
            nom_sub_limpio = str(info_sub.get("nombre_limpio", v.get("subcategoria_nombre", "Actividad Económica")))
            pref_grp = str(info_sub.get("prefijo_codigo", "MAC"))
            clave_grp = sub_k
            v["subcategoria_numero"] = num_sub_str
            v["subcategoria_nombre"] = nom_sub_limpio
            idx_loc = contadores_grupo.get(clave_grp, 0) + 1
            contadores_grupo[clave_grp] = idx_loc
            tot_loc = totales_grupo.get(clave_grp, idx_loc)
            cod_jer = f"{num_cat_str}.{num_sub_str}.{idx_loc}"
            etq_grp = f"{num_sub_str}. {nom_sub_limpio}"
        else:
            pref_grp = str(info_cat.get("prefijo_codigo", PREFIJOS_CODIGO_CATEGORIA.get(cat_v, "VIS")))
            clave_grp = cat_v
            idx_loc = contadores_grupo.get(clave_grp, 0) + 1
            contadores_grupo[clave_grp] = idx_loc
            tot_loc = totales_grupo.get(clave_grp, idx_loc)
            cod_jer = f"{num_cat_str}.{idx_loc}"
            etq_grp = f"{num_cat_str}. {nom_cat_limpio}"

        cod_unico = f"{pref_grp}-{idx_loc:02d}"
        cod_global = f"V-{idx_global:02d}"
        tit_base = str(v.get("titulo_base") or v.get("titulo", "")).strip()
        # Limpiar prefijo numérico antiguo si existía (ej. "64. Cotización...")
        tit_base = re.sub(r"^\d+\.\s*", "", tit_base)
        corto_base = str(v.get("corto_base") or v.get("corto", "")).strip()
        if corto_base and ord(corto_base[0]) > 8000 and " " in corto_base:
            corto_base = corto_base.split(" ", 1)[1].strip()
        corto_base = re.sub(r"^\d+\.\s*", "", corto_base)

        v["titulo_base"] = tit_base
        v["corto_base"] = corto_base
        v["numero"] = str(idx_global)
        v["orden_subcategoria"] = str(idx_loc)
        v["total_en_grupo"] = str(tot_loc)
        v["codigo"] = cod_unico
        v["codigo_global"] = cod_global
        v["codigo_jerarquico"] = cod_jer
        v["titulo"] = tit_base
        v["titulo_numerado"] = f"Vista {idx_global} [{cod_unico}] — {tit_base}"
        v["corto"] = f"{v['icono']} {corto_base}"
        v["corto_con_codigo"] = f"{v['icono']} [{cod_unico}] {corto_base}"
        v["etiqueta_badge_card"] = f"CÓD: {cod_unico}  •  VISTA {idx_global}/{total_vistas_global} ({cod_jer})"
        v["etiqueta_grupo_card"] = f"{etq_grp.upper()}  •  VISTA {idx_loc} DE {tot_loc}"

        clave_v = str(v["clave"])
        MAPA_VISTAS_MACRO[clave_v] = v

        # Registrar códigos y números para acceso directo y buscador
        for alias_k in (
            clave_v.lower(),
            cod_unico.lower(),
            cod_unico.lower().replace("-", ""),
            cod_global.lower(),
            cod_global.lower().replace("-", ""),
            f"v{idx_global}",
            cod_jer.lower(),
            str(idx_global),
            f"vista {idx_global}",
            f"vista_{idx_global}",
        ):
            MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA[alias_k] = clave_v

    MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA["presentacion"] = "presentacion"
    MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA["pres-01"] = "presentacion"
    MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA["pres01"] = "presentacion"
    MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA["1.1"] = "presentacion"
    MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA["0"] = "presentacion"

    # 5. Actualizar listas globales por categoría en el mismo objeto de lista
    CLAVES_VISTAS_MACRO_INDIVIDUALES[:] = [
        v["clave"] for v in CATALOGO_VISTAS_MACRO if v.get("categoria") == "macroeconomicas"
    ]
    CLAVES_VISTAS_COTIZACIONES[:] = [
        v["clave"] for v in CATALOGO_VISTAS_MACRO if v.get("categoria") == "cotizaciones"
    ]
    CLAVES_VISTAS_PROYECCIONES[:] = [
        v["clave"] for v in CATALOGO_VISTAS_MACRO if v.get("categoria") == "proyecciones"
    ]
    CLAVES_VISTAS_MODELACION[:] = [
        v["clave"] for v in CATALOGO_VISTAS_MACRO if v.get("categoria") == "modelacion"
    ]
    ORDEN_CLAVES_VISTAS[:] = [v["clave"] for v in CATALOGO_VISTAS_MACRO]

    # 6. Actualizar contadores automáticos en cada Subcategoría Macroeconómica
    for sub in SUBCATEGORIAS_MACROECONOMICAS:
        clave_s = str(sub["clave_sub"])
        vistas_s = [v for v in CATALOGO_VISTAS_MACRO if v.get("subcategoria_clave") == clave_s]
        n_s = len(vistas_s)
        sub["cantidad_vistas"] = n_s
        if n_s > 0:
            v_ini, v_fin = vistas_s[0]["numero"], vistas_s[-1]["numero"]
            c_ini, c_fin = vistas_s[0]["codigo"], vistas_s[-1]["codigo"]
            rango_v = f"Vista {v_ini}" if n_s == 1 else f"Vistas {v_ini} a {v_fin}"
            rango_c = f"{c_ini}" if n_s == 1 else f"{c_ini}–{c_fin}"
            sub["vista_inicio"] = v_ini
            sub["vista_fin"] = v_fin
            sub["rango_vistas"] = rango_v
            sub["rango_codigos"] = rango_c
            sub["etiqueta_cantidad"] = f"{n_s} {'Vista' if n_s == 1 else 'Vistas'} ({rango_v} • {rango_c})"
        else:
            sub["vista_inicio"] = "0"
            sub["vista_fin"] = "0"
            sub["rango_vistas"] = "0 Vistas"
            sub["rango_codigos"] = "—"
            sub["etiqueta_cantidad"] = "0 Vistas"

    # 7. Actualizar contadores automáticos en cada Categoría Principal
    total_cats = len(CATEGORIAS_PRINCIPALES_VISTAS)
    total_subs_macro = len(SUBCATEGORIAS_MACROECONOMICAS)
    for idx_c, cat in enumerate(CATEGORIAS_PRINCIPALES_VISTAS, 1):
        clave_c = str(cat["clave_categoria"])
        cat["numero_badge"] = f"CATEGORÍA {idx_c} DE {total_cats}"
        if clave_c == "presentacion":
            cat["cantidad_vistas"] = 1
            cat["cantidad_subcategorias"] = 0
            cat["rango_vistas"] = "Portada"
            cat["rango_codigos"] = "PRES-01"
            cat["etiqueta_cantidad"] = "1 Vista (PRES-01)"
            cat["claves_vistas"] = ["presentacion"]
        elif clave_c == "calculadoras":
            cat["cantidad_vistas"] = len(CATALOGO_INSTRUMENTOS_CALCULADORAS)
            cat["cantidad_subcategorias"] = 0
            cat["rango_vistas"] = "3 Calculadoras"
            cat["rango_codigos"] = "CALC-01..CALC-03"
            cat["etiqueta_cantidad"] = "3 Calculadoras (IPC • UF • TC)"
            cat["claves_vistas"] = list(CLAVES_VISTAS_CALCULADORAS)
            cat["subtitulo"] = "Instrumentos interactivos de cálculo: Calculadora de IPC (INE), Calculadora de UF (SII) y Calculadora de Tipo de Cambio."
        else:
            vistas_c = [v for v in CATALOGO_VISTAS_MACRO if v.get("categoria") == clave_c]
            n_c = len(vistas_c)
            cat["cantidad_vistas"] = n_c
            cat["claves_vistas"] = [v["clave"] for v in vistas_c]
            if n_c > 0:
                v_i, v_f = vistas_c[0]["numero"], vistas_c[-1]["numero"]
                c_i, c_f = vistas_c[0]["codigo"], vistas_c[-1]["codigo"]
                rango_vc = f"Vista {v_i}" if n_c == 1 else f"Vistas {v_i}–{v_f}"
                rango_cc = f"{c_i}" if n_c == 1 else f"{c_i}..{c_f}"
            else:
                rango_vc, rango_cc = "0 Vistas", "—"
            cat["rango_vistas"] = rango_vc
            cat["rango_codigos"] = rango_cc
            if clave_c == "macroeconomicas":
                cat["cantidad_subcategorias"] = total_subs_macro
                cat["etiqueta_cantidad"] = f"{total_subs_macro} Subcat. • {n_c} Vistas ({rango_vc})"
                nombres_subs = ", ".join(str(s["nombre_limpio"]) for s in SUBCATEGORIAS_MACROECONOMICAS)
                cat["subtitulo"] = (
                    f"{total_subs_macro} Subcategorías Macroeconómicas ({n_c} vistas individuales — {rango_vc}): "
                    f"{nombres_subs}."
                )
            else:
                cat["cantidad_subcategorias"] = 0
                cat["etiqueta_cantidad"] = f"{n_c} {'Vista' if n_c == 1 else 'Vistas'} ({rango_vc} • {rango_cc})"
                nombres_vc = ", ".join(str(v["corto_base"]) for v in vistas_c)
                cat["subtitulo"] = (
                    f"{n_c} {'Vista' if n_c == 1 else 'Vistas'} ({rango_vc} • Códigos {rango_cc}): {nombres_vc}."
                )

    # 8. Construir catálogo unificado para el Buscador del Menú Principal
    CATALOGO_BUSQUEDA_VISTAS.clear()
    for v in CATALOGO_VISTAS_MACRO:
        sub_nom = str(v.get("subcategoria_nombre", ""))
        cat_nom = str(v.get("categoria_nombre", ""))
        cat_num = str(v.get("categoria_numero", "2"))
        sub_num = str(v.get("subcategoria_numero", ""))
        ruta_txt = (
            f"{cat_num}. {cat_nom} ▸ {sub_num}. {sub_nom}"
            if sub_nom
            else f"{cat_num}. {cat_nom}"
        )
        texto_indexado = _normalizar_texto_busqueda(
            " ".join(
                [
                    str(v.get("codigo", "")),
                    str(v.get("codigo", "")).replace("-", ""),
                    str(v.get("codigo_global", "")),
                    str(v.get("codigo_global", "")).replace("-", ""),
                    f"v{v.get('numero', '')}",
                    f"vista {v.get('numero', '')}",
                    str(v.get("codigo_jerarquico", "")),
                    str(v.get("numero", "")),
                    str(v.get("titulo_base", "")),
                    str(v.get("corto_base", "")),
                    str(v.get("subtitulo", "")),
                    cat_nom,
                    sub_nom,
                    str(v.get("bloque_nombre", "")),
                    str(v.get("clave", "")),
                ]
            )
        )
        item_b = dict(v)
        item_b["ruta_categoria_sub"] = ruta_txt
        item_b["_texto_busqueda"] = texto_indexado
        CATALOGO_BUSQUEDA_VISTAS.append(item_b)

    # Incluir los 3 Instrumentos de Cálculo de la Categoría 6 (CALC-01, CALC-02, CALC-03) en el buscador y mapa de códigos
    for inst_c in CATALOGO_INSTRUMENTOS_CALCULADORAS:
        cod_ic = inst_c["codigo"].lower()
        clv_ic = inst_c["clave"]
        MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA[cod_ic] = clv_ic
        MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA[cod_ic.replace("-", "")] = clv_ic
        MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA[clv_ic] = clv_ic
        CATALOGO_BUSQUEDA_VISTAS.append(
            {
                "clave": clv_ic,
                "numero": inst_c["numero"],
                "codigo": inst_c["codigo"],
                "codigo_global": inst_c["codigo"],
                "codigo_jerarquico": f"6.{inst_c['numero']}",
                "icono": inst_c["icono"],
                "titulo_base": inst_c["titulo"],
                "corto_base": inst_c["corto_base"],
                "titulo": inst_c["titulo"],
                "corto": f"{inst_c['icono']} {inst_c['corto_base']}",
                "subtitulo": inst_c["subtitulo"],
                "color_acento": inst_c["color_acento"],
                "categoria": "calculadoras",
                "categoria_numero": "6",
                "categoria_nombre": "Calculadoras",
                "subcategoria_clave": "",
                "subcategoria_nombre": "",
                "etiqueta_badge_card": f"INSTRUMENTO {inst_c['codigo']}  •  6. CALCULADORAS",
                "etiqueta_grupo_card": "6. CALCULADORAS  •  INSTRUMENTO INTERACTIVO",
                "ruta_categoria_sub": "6. Calculadoras",
                "_texto_busqueda": _normalizar_texto_busqueda(
                    f"{inst_c['codigo']} {inst_c['codigo'].replace('-', '')} {clv_ic} calculadora {inst_c['titulo']} {inst_c['subtitulo']} ine sii uf ipc dolar tipo de cambio"
                ),
            }
        )

    # Incluir también la vista de Presentación Profesional (Categoría 1, código PRES-01)
    CATALOGO_BUSQUEDA_VISTAS.append(
        {
            "clave": "presentacion",
            "numero": "0",
            "codigo": "PRES-01",
            "codigo_global": "V-00",
            "codigo_jerarquico": "1.1",
            "icono": "👤",
            "titulo_base": "Presentación Profesional, Sello Analítico y Trayectoria Académica (Matías Rioseco Oróstica)",
            "corto_base": "Presentación Profesional",
            "titulo": "Presentación Profesional, Sello Analítico y Trayectoria Académica",
            "corto": "👤 Presentación Profesional",
            "subtitulo": "Perfil profesional, experiencia laboral en economía y finanzas, formación académica (FEN U. de Chile) y datos de contacto directo.",
            "color_acento": "#D97706",
            "categoria": "presentacion",
            "categoria_numero": "1",
            "categoria_nombre": "Presentación",
            "subcategoria_clave": "",
            "subcategoria_nombre": "",
            "etiqueta_badge_card": "CÓD: PRES-01  •  CATEGORÍA 1 (PORTADA)",
            "etiqueta_grupo_card": "1. PRESENTACIÓN  •  VISTA EJECUTIVA",
            "ruta_categoria_sub": "1. Presentación",
            "_texto_busqueda": _normalizar_texto_busqueda(
                "pres-01 pres01 v00 1.1 presentacion portada perfil profesional trayectoria academica matias rioseco"
            ),
        }
    )

    resumen_out = {
        "total_categorias": len(CATEGORIAS_PRINCIPALES_VISTAS),
        "total_subcategorias_macro": len(SUBCATEGORIAS_MACROECONOMICAS),
        "total_vistas_analiticas": len(CATALOGO_VISTAS_MACRO),
        "total_vistas_macro": len(CLAVES_VISTAS_MACRO_INDIVIDUALES),
        "total_vistas_cotizaciones": len(CLAVES_VISTAS_COTIZACIONES),
        "total_vistas_proyecciones": len(CLAVES_VISTAS_PROYECCIONES),
        "total_vistas_modelacion": len(CLAVES_VISTAS_MODELACION),
        "total_vistas_calculadoras": len(CLAVES_VISTAS_CALCULADORAS),
    }
    _CACHE_HUELLA_CATALOGO_VISTAS["huella"] = (
        len(CATEGORIAS_PRINCIPALES_VISTAS),
        len(SUBCATEGORIAS_MACROECONOMICAS),
        len(CATALOGO_VISTAS_MACRO),
        tuple(str(s.get("titulo", "")) for s in SUBCATEGORIAS_MACROECONOMICAS),
        tuple(str(v.get("clave", "")) for v in CATALOGO_VISTAS_MACRO),
    )
    _CACHE_HUELLA_CATALOGO_VISTAS["resumen"] = resumen_out
    return resumen_out


def obtener_meta_vista(clave_vista: str) -> Dict[str, str]:
    """Devuelve los metadatos actualizados (número, código, título, categoría) de una vista."""
    if not MAPA_VISTAS_MACRO or "codigo" not in next(iter(MAPA_VISTAS_MACRO.values()), {}):
        sincronizar_catalogo_y_contadores_vistas()
    return MAPA_VISTAS_MACRO.get(clave_vista, {})


def obtener_etiqueta_vista(clave_vista: str, incluir_codigo: bool = True) -> str:
    """Devuelve 'Vista N [CÓDIGO]' calculado automáticamente para cualquier vista."""
    meta = obtener_meta_vista(clave_vista)
    num_s = str(meta.get("numero", "1"))
    cod_s = str(meta.get("codigo", ""))
    if incluir_codigo and cod_s:
        return f"Vista {num_s} [{cod_s}]"
    return f"Vista {num_s}"


def resolver_clave_vista_desde_codigo_o_numero(entrada: str) -> Optional[str]:
    """
    Resuelve un código de vista ('ACT-01', 'EMP-01', 'CAP-05', 'COT-01', 'PROY-01', 'MOD-01',
    'V-17', '2.4.1') o un número de vista ('1', '17', 'Vista 72') hacia su `clave` interna.
    """
    if not MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA:
        sincronizar_catalogo_y_contadores_vistas()
    q = _normalizar_texto_busqueda(entrada)
    if not q:
        return None
    if q in MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA:
        return MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA[q]
    q_sin_guion = q.replace("-", "").replace(" ", "")
    if q_sin_guion in MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA:
        return MAPA_CODIGOS_Y_NUMEROS_A_CLAVE_VISTA[q_sin_guion]
    return None


def buscar_vistas_en_catalogo(consulta: str) -> List[Dict[str, str]]:
    """
    Busca vistas en tiempo real por código ('ACT-01', 'EMP-01', 'PROY-01', 'MOD-01', 'V-17'),
    código jerárquico ('2.4.1', '3.1'), número ('17', 'Vista 17') o palabras clave del título,
    subcategoría, categoría o descripción. Si `consulta` está vacía, devuelve todas las vistas.
    """
    if not CATALOGO_BUSQUEDA_VISTAS:
        sincronizar_catalogo_y_contadores_vistas()
    q_norm = _normalizar_texto_busqueda(consulta)
    if not q_norm:
        return [v for v in CATALOGO_BUSQUEDA_VISTAS if v.get("clave") != "presentacion"]

    q_compact = q_norm.replace("-", "").replace(" ", "")
    tokens = [t for t in q_norm.split() if t]
    resultados_puntuados: List[Tuple[int, int, Dict[str, str]]] = []

    for item in CATALOGO_BUSQUEDA_VISTAS:
        cod_l = _normalizar_texto_busqueda(item.get("codigo", ""))
        cod_c = cod_l.replace("-", "")
        cod_g = _normalizar_texto_busqueda(item.get("codigo_global", ""))
        cod_gc = cod_g.replace("-", "")
        cod_j = _normalizar_texto_busqueda(item.get("codigo_jerarquico", ""))
        num_s = str(item.get("numero", "999"))
        num_int = int(num_s) if num_s.isdigit() else 999
        tit_l = _normalizar_texto_busqueda(item.get("titulo_base", ""))
        corto_l = _normalizar_texto_busqueda(item.get("corto_base", ""))
        sub_l = _normalizar_texto_busqueda(item.get("subcategoria_nombre", ""))
        cat_l = _normalizar_texto_busqueda(item.get("categoria_nombre", ""))
        full_l = str(item.get("_texto_busqueda", ""))

        puntaje = 0
        if q_norm in (cod_l, cod_g, cod_j, num_s, f"vista {num_s}") or q_compact in (cod_c, cod_gc, f"v{num_s}", f"vista{num_s}"):
            puntaje = 1000
        elif cod_l.startswith(q_norm) or cod_c.startswith(q_compact) or cod_j.startswith(q_norm):
            puntaje = 850
        elif num_s.startswith(q_norm) and q_norm.isdigit():
            puntaje = 780
        elif all(tk_q in full_l for tk_q in tokens):
            puntaje = 500
            if all(tk_q in tit_l or tk_q in corto_l or tk_q in cod_l for tk_q in tokens):
                puntaje += 200
            elif any(tk_q in sub_l or tk_q in cat_l for tk_q in tokens):
                puntaje += 100

        if puntaje > 0:
            resultados_puntuados.append((-puntaje, num_int if num_int > 0 else 9999, item))

    resultados_puntuados.sort(key=lambda x: (x[0], x[1]))
    return [r[2] for r in resultados_puntuados]


