def _construir_semilla_ahorro_deuda_csi_bcch() -> Dict[str, pd.DataFrame]:
    """
    Construye las series trimestrales y anuales desde 1996 hasta 2026 de:
      1. Stock de Ahorro (Privado, Público, Familias y Total) en % del PIB y en MM$ CLP.
      2. Stock de Endeudamiento (Privado, Público, Familias y Total) en % del PIB y en MM$ CLP.
      3. Neto de Stock Deuda − Ahorro (Privado + Familias), sus componentes brutos y el
         desglose Neto Privado vs. Neto Familias en % del PIB y en MM$ CLP.
    """
    fechas_h = pd.to_datetime([t[0] for t in DATOS_OFICIALES_BDE_AHORRO_DEUDA_CSI_HITOS])
    df_h = pd.DataFrame(
        [
            {
                "Stock de Ahorro Privado": float(t[1]),
                "Stock de Ahorro Público": float(t[2]),
                "Stock de Ahorro Familias": float(t[3]),
                "Stock de Endeudamiento Privado": float(t[4]),
                "Stock de Endeudamiento Público": float(t[5]),
                "Stock de Endeudamiento Familias": float(t[6]),
                "_PIB_Nom": float(t[7]),
            }
            for t in DATOS_OFICIALES_BDE_AHORRO_DEUDA_CSI_HITOS
        ],
        index=fechas_h,
    ).sort_index()

    idx_q = pd.date_range(start=df_h.index.min(), end=df_h.index.max(), freq="QS")
    df_q = df_h.reindex(df_h.index.union(idx_q)).sort_index().interpolate(method="time").reindex(idx_q)

    df_q["Stock de Ahorro Total"] = (
        df_q["Stock de Ahorro Privado"]
        + df_q["Stock de Ahorro Público"]
        + df_q["Stock de Ahorro Familias"]
    ).round(2)

    df_q["Stock de Endeudamiento Total"] = (
        df_q["Stock de Endeudamiento Privado"]
        + df_q["Stock de Endeudamiento Público"]
        + df_q["Stock de Endeudamiento Familias"]
    ).round(2)

    df_q["Stock Deuda (Privado + Familias)"] = (
        df_q["Stock de Endeudamiento Privado"] + df_q["Stock de Endeudamiento Familias"]
    ).round(2)
    df_q["Stock Ahorro (Privado + Familias)"] = (
        df_q["Stock de Ahorro Privado"] + df_q["Stock de Ahorro Familias"]
    ).round(2)
    df_q["Neto Stock Deuda - Ahorro (Privado + Familias)"] = (
        df_q["Stock Deuda (Privado + Familias)"] - df_q["Stock Ahorro (Privado + Familias)"]
    ).round(2)
    df_q["Neto Deuda - Ahorro Privado (Empresas)"] = (
        df_q["Stock de Endeudamiento Privado"] - df_q["Stock de Ahorro Privado"]
    ).round(2)
    df_q["Neto Deuda - Ahorro Familias (Hogares)"] = (
        df_q["Stock de Endeudamiento Familias"] - df_q["Stock de Ahorro Familias"]
    ).round(2)

    cols_series = [c for c in df_q.columns if c != "_PIB_Nom"]
    df_pct_pib = df_q[cols_series].round(2)

    # Conversión a Miles de Millones de Pesos (MM$ CLP) usando el PIB nominal anualizado
    df_mm_clp = df_pct_pib.multiply(df_q["_PIB_Nom"] / 100.0, axis=0).round(1)

    return {
        "csi_ahorro_deuda_pct_pib": df_pct_pib,
        "csi_ahorro_deuda_mm_clp": df_mm_clp,
    }


