# 3. MOTOR DE TOOLTIPS INTERACTIVOS (HOVER) PARA TODOS LOS GRÁFICOS
# =============================================================================

_REGISTRO_TOOLTIPS_FIGURAS: Dict[int, object] = {}


def _formatear_fecha_tooltip(x_num: float, todas_anuales: bool = False) -> str:
    """Convierte una coordenada numérica de fecha de Matplotlib en texto legible."""
    try:
        dt = mdates.num2date(x_num)
        if todas_anuales and dt.month == 1 and dt.day == 1:
            return dt.strftime("%Y")
        if dt.day == 1:
            return dt.strftime("%Y-%m")
        return dt.strftime("%Y-%m-%d")
    except Exception:
        return f"{x_num:,.2f}"


class GestorTooltipsInteractivos:
    """
    Habilita inspección interactiva ultra-rápida ('hover') al desplazar el mouse
    sobre cualquier gráfico (`Axes`) de una figura de Matplotlib:
      - Pre-indexa una sola vez las coordenadas (X, Y) de líneas y barras al crear
        el gráfico (cero extracción de datos durante el movimiento del mouse).
      - Sólo actualiza cuando el cursor cambia efectivamente de período/barra (`snap_key`)
        e incorpora throttling (~25 ms) para no saturar el hilo de interfaz.
      - Utiliza Fast Blitting (`copy_from_bbox` / `restore_region` / `draw_artist` / `blit`)
        para dibujar el tooltip en < 1 ms sin redibujar los 4 paneles ni las tablas.
    """

    def __init__(self, fig: plt.Figure, canvas=None):
        self.fig = fig
        self.canvas = canvas or fig.canvas
        self._cids: List[int] = []
        self._grupos_axes: List[List[plt.Axes]] = []
        self._annot_por_ax: Dict[plt.Axes, matplotlib.text.Annotation] = {}
        self._vline_por_ax: Dict[plt.Axes, plt.Line2D] = {}
        self._hline_por_ax: Dict[plt.Axes, plt.Line2D] = {}
        self._marker_por_ax: Dict[plt.Axes, plt.Line2D] = {}
        self._cache_grupo: Dict[plt.Axes, Dict[str, object]] = {}
        self._ultimo_ax_activo: Optional[plt.Axes] = None
        self._ultimo_snap_key: Optional[Tuple[int, int]] = None
        self._ultimo_t_evento: float = 0.0
        self._bg_blit = None
        self._en_draw_interno: bool = False
        self._construir_artistas()
        self._conectar_eventos()

    def desconectar(self) -> None:
        if self.canvas is not None:
            for cid in self._cids:
                try:
                    self.canvas.mpl_disconnect(cid)
                except Exception:
                    pass
        self._cids.clear()

    def _construir_artistas(self) -> None:
        """Agrupa los Axes que comparten posición (twinx), pre-indexa datos y crea artistas."""
        axes_validos = [
            ax for ax in self.fig.axes if ax.axison
        ]
        grupos_todos: List[List[plt.Axes]] = []
        for ax in axes_validos:
            pos = ax.get_position().bounds
            agregado = False
            for g in grupos_todos:
                pos_g = g[0].get_position().bounds
                if all(abs(a - b) < 1e-3 for a, b in zip(pos, pos_g)):
                    g.append(ax)
                    agregado = True
                    break
            if not agregado:
                grupos_todos.append([ax])
        grupos: List[List[plt.Axes]] = [
            g for g in grupos_todos if any((ax_m.lines or ax_m.patches) for ax_m in g)
        ]

        self._grupos_axes = grupos

        for grupo in self._grupos_axes:
            ax_host = grupo[-1]
            ax_base = grupo[0]

            limites_originales = {
                ax_m: (ax_m.get_xlim(), ax_m.get_ylim()) for ax_m in grupo
            }
            x0_init = limites_originales[ax_base][0][0]
            y0_init = limites_originales[ax_base][1][0]
            xh_init = limites_originales[ax_host][0][0]
            yh_init = limites_originales[ax_host][1][0]

            # Pre-indexa las series y barras del grupo una sola vez
            es_barh = self._es_barra_horizontal(ax_base) and not [
                ln
                for ln in ax_base.lines
                if not getattr(ln, "_es_tooltip_interno", False) and len(ln.get_xdata()) > 2
            ]
            info_cache: Dict[str, object] = {"es_barh": es_barh}

            if es_barh:
                rects_h = [
                    p
                    for p in ax_base.patches
                    if isinstance(p, mpatches.Rectangle) and p.get_height() > 0
                ]
                centros_y = np.asarray(
                    [r.get_y() + r.get_height() / 2.0 for r in rects_h], dtype=float
                )
                anchos_x = np.asarray([r.get_width() for r in rects_h], dtype=float)
                yticks = list(ax_base.get_yticks())
                ylabels = [t.get_text() for t in ax_base.get_yticklabels()]
                etiquetas_h: List[str] = []
                for idx_r, cy in enumerate(centros_y):
                    etq = f"Ítem {idx_r + 1}"
                    if yticks and ylabels:
                        idx_yt = int(np.argmin([abs(yt - cy) for yt in yticks]))
                        if idx_yt < len(ylabels) and ylabels[idx_yt].strip():
                            etq = ylabels[idx_yt].strip()
                    etiquetas_h.append(etq)
                info_cache["centros_y"] = centros_y
                info_cache["anchos_x"] = anchos_x
                info_cache["etiquetas_h"] = etiquetas_h
            else:
                candidatos_x: List[float] = []
                series_lineas: List[Tuple[plt.Axes, str, np.ndarray, np.ndarray]] = []
                series_barras: List[Tuple[plt.Axes, str, np.ndarray, np.ndarray, float]] = []

                for ax_m in grupo:
                    for ln in ax_m.lines:
                        if getattr(ln, "_es_tooltip_interno", False):
                            continue
                        xd = np.asarray(ln.get_xdata(orig=False), dtype=float)
                        yd = np.asarray(ln.get_ydata(orig=False), dtype=float)
                        if len(xd) < 2:
                            continue
                        if np.allclose(xd[0], xd[-1]) or (
                            xd[0] == 0.0 and xd[-1] == 1.0 and len(xd) == 2
                        ):
                            continue
                        candidatos_x.extend(xd.tolist())
                        lbl = ln.get_label()
                        if lbl and not lbl.startswith("_"):
                            nom_limpio = lbl.split("(")[0].split(":")[0].strip()
                            series_lineas.append((ax_m, nom_limpio, xd, yd))

                    rects_m = [
                        p
                        for p in ax_m.patches
                        if isinstance(p, mpatches.Rectangle)
                        and p.get_width() > 0
                        and p.get_height() != 0
                        and not (p.get_width() == 1.0 and p.get_x() == 0.0)
                    ]
                    if rects_m:
                        centros_b = np.asarray(
                            [p.get_x() + p.get_width() / 2.0 for p in rects_m], dtype=float
                        )
                        alturas_b = np.asarray(
                            [p.get_height() for p in rects_m], dtype=float
                        )
                        ancho_b = float(rects_m[0].get_width())
                        candidatos_x.extend(centros_b.tolist())
                        etiq_b = "Variación / Barra"
                        for cont in getattr(ax_m, "containers", []):
                            lbl_c = cont.get_label()
                            if lbl_c and not lbl_c.startswith("_"):
                                etiq_b = lbl_c.split("(")[0].split(":")[0].strip()
                                break
                        series_barras.append((ax_m, etiq_b, centros_b, alturas_b, ancho_b))

                arr_x = (
                    np.unique(np.asarray(candidatos_x, dtype=float))
                    if candidatos_x
                    else np.asarray([], dtype=float)
                )
                todas_anuales = bool(len(arr_x) >= 2 and np.all(np.diff(arr_x) >= 350))
                tol_x = (
                    max((float(arr_x.max()) - float(arr_x.min())) * 0.035, 1e-6)
                    if len(arr_x) > 1
                    else 1.0
                )
                info_cache["arr_x"] = arr_x
                info_cache["tol_x"] = tol_x
                info_cache["todas_anuales"] = todas_anuales
                info_cache["cache_etq_x"] = {}
                info_cache["series_lineas"] = series_lineas
                info_cache["series_barras"] = series_barras

            vline = ax_base.axvline(
                x=x0_init,
                color="#334155",
                linestyle=":",
                linewidth=1.1,
                alpha=0.75,
                visible=False,
                zorder=95,
            )
            vline._es_tooltip_interno = True  # type: ignore[attr-defined]

            hline = ax_base.axhline(
                y=y0_init,
                color="#334155",
                linestyle=":",
                linewidth=1.0,
                alpha=0.55,
                visible=False,
                zorder=95,
            )
            hline._es_tooltip_interno = True  # type: ignore[attr-defined]

            (marker,) = ax_host.plot(
                [xh_init],
                [yh_init],
                marker="o",
                markersize=6.5,
                markerfacecolor="#F59E0B",
                markeredgecolor="#0A2540",
                markeredgewidth=1.4,
                linestyle="None",
                visible=False,
                zorder=98,
            )
            marker._es_tooltip_interno = True  # type: ignore[attr-defined]

            annot = ax_host.annotate(
                "",
                xy=(xh_init, yh_init),
                xytext=(-16, 14),
                textcoords="offset points",
                ha="right",
                multialignment="left",
                fontsize=8.2,
                fontweight="bold",
                color="#F8FAFC",
                bbox=dict(
                    boxstyle="round,pad=0.45",
                    facecolor="#0A2540",
                    edgecolor="#F59E0B",
                    linewidth=1.2,
                    alpha=0.94,
                ),
                zorder=100,
                visible=False,
            )
            annot.set_clip_on(False)

            for ax_m, (xl, yl) in limites_originales.items():
                ax_m.set_xlim(xl)
                ax_m.set_ylim(yl)
                self._annot_por_ax[ax_m] = annot
                self._vline_por_ax[ax_m] = vline
                self._hline_por_ax[ax_m] = hline
                self._marker_por_ax[ax_m] = marker
                self._cache_grupo[ax_m] = info_cache

    def _conectar_eventos(self) -> None:
        self._drag_mf_activo: Optional[Dict[str, object]] = None
        self._ultimo_t_drag_mf: float = 0.0
        if self.canvas is None:
            return
        self._cids.append(
            self.canvas.mpl_connect("motion_notify_event", self._on_motion)
        )
        self._cids.append(
            self.canvas.mpl_connect("button_press_event", self._on_click)
        )
        self._cids.append(
            self.canvas.mpl_connect("button_release_event", self._on_release)
        )
        self._cids.append(
            self.canvas.mpl_connect("axes_leave_event", self._on_leave)
        )
        self._cids.append(
            self.canvas.mpl_connect("figure_leave_event", self._on_leave)
        )
        self._cids.append(
            self.canvas.mpl_connect("draw_event", self._on_draw)
        )

    def _on_click(self, event) -> None:
        """
        Detecta clics del usuario sobre la barra de botones de temporalidad de velas
        japonesas (`1H`, `4H`, `1D`, `1S`, `1M`, `1T`, `1A`) y de ventana/zoom (`30v`,
        `60v`, `90v`, `150v`, `Todo`) integrada directamente dentro de la pantalla del gráfico.
        """
        if event.inaxes is None or event.xdata is None or event.ydata is None:
            return
        panel_mf = getattr(event.inaxes, "_panel_mf_id", None)
        if panel_mf and getattr(self.fig, "_es_modelador_islm_mf", False):
            curva_det = self._detectar_curva_cercana_mf(event.inaxes, str(panel_mf), float(event.xdata), float(event.ydata))
            if curva_det:
                self._iniciar_drag_curva_mf(str(panel_mf), curva_det, float(event.xdata), float(event.ydata))
                return
        zonas_btn = getattr(event.inaxes, "_zonas_botones_yf", None)
        if not zonas_btn:
            return
        xc = float(event.xdata)
        yc = float(event.ydata)
        for x0, x1, y0, y1, tipo_accion, valor_accion in zonas_btn:
            if x0 <= xc <= x1 and y0 <= yc <= y1:
                if tipo_accion == "intervalo_vela":
                    ESTADO_FILTROS_COTIZACIONES_YF["intervalo_vela"] = str(valor_accion)
                elif tipo_accion == "num_velas":
                    ESTADO_FILTROS_COTIZACIONES_YF["num_velas"] = int(valor_accion)
                elif tipo_accion == "corte_proy":
                    ESTADO_FILTROS_PROYECCION_SARIMAX["corte_muestral"] = str(valor_accion)
                elif tipo_accion == "modelo_proy":
                    ESTADO_FILTROS_PROYECCION_SARIMAX["modelo_etiqueta"] = str(valor_accion)
                elif tipo_accion == "escala_proy":
                    ESTADO_FILTROS_PROYECCION_SARIMAX["escala_grafico"] = str(valor_accion)
                elif tipo_accion == "horizonte_proy":
                    ESTADO_FILTROS_PROYECCION_SARIMAX["horizonte"] = int(valor_accion)
                elif tipo_accion == "ventana_proy":
                    ESTADO_FILTROS_PROYECCION_SARIMAX["ventana_x"] = str(valor_accion)
                elif tipo_accion == "escala_pib_usd":
                    ESTADO_FILTROS_PROYECCION_SARIMAX["escala_pib_usd"] = str(valor_accion)
                elif tipo_accion == "descargar_pdf_proyecciones":
                    cb_pdf = getattr(self.fig, "_callback_descargar_pdf_proyecciones", None)
                    if callable(cb_pdf):
                        cb_pdf()
                    else:
                        datos_f = getattr(self.fig, "_datos_proyeccion_ref", {})
                        ruta_def = Path.cwd() / "Informe_Tecnico_Proyecciones_IMACEC_EcoPulse.pdf"
                        exportar_informe_tecnico_proyecciones_pdf(ruta_def, datos_f)
                    break
                elif tipo_accion == "descargar_pdf_perspectivas_macro":
                    cb_pdf_m = getattr(self.fig, "_callback_descargar_pdf_macro", None)
                    if callable(cb_pdf_m):
                        cb_pdf_m()
                    else:
                        datos_m = getattr(self.fig, "_datos_macro_ref", {})
                        ruta_def_m = Path.cwd() / "EcoPulse_Analytics_-_Informe_de_Perspectivas_Macroeconomicas.pdf"
                        exportar_informe_perspectivas_macroeconomicas_pdf(ruta_def_m, datos_m)
                    break
                elif tipo_accion == "cambiar_vista_proy":
                    cb_nav = getattr(self.fig, "_callback_navegar_vista", None)
                    if callable(cb_nav):
                        cb_nav(str(valor_accion))
                        break
                elif tipo_accion == "filtro_ene_dash":
                    val_str = str(valor_accion)
                    if ":" in val_str:
                        k_d, v_d = val_str.split(":", 1)
                        if k_d == "reset":
                            ESTADO_DASHBOARD_ENE_FILTROS.update({
                                "region": "TOTAL",
                                "tipo_empleo": "TODOS",
                                "genero": "AMBOS",
                                "educacion": "TODOS",
                                "edad": "TODAS",
                                "extranjero": "TOTAL",
                                "aplicacion": "TOTAL",
                            })
                        elif k_d in ESTADO_DASHBOARD_ENE_FILTROS:
                            ESTADO_DASHBOARD_ENE_FILTROS[k_d] = v_d
                    cb_m_f = getattr(self.fig, "_callback_filtro_boton_macro", None)
                    if callable(cb_m_f):
                        cb_m_f("filtro_ene_dash", valor_accion)
                        break
                elif tipo_accion in ("frec_macro", "modo_macro", "ventana_macro", "accion_baci", "accion_ptf"):
                    cb_m_f = getattr(self.fig, "_callback_filtro_boton_macro", None)
                    if callable(cb_m_f):
                        cb_m_f(tipo_accion, valor_accion)
                        break
                elif tipo_accion in ("regimen_mf", "movilidad_mf", "shock_mf", "intensidad_mf"):
                    if tipo_accion == "regimen_mf":
                        ESTADO_MODELADOR_ISLM_MF["regimen"] = str(valor_accion)
                    elif tipo_accion == "movilidad_mf":
                        ESTADO_MODELADOR_ISLM_MF["movilidad"] = str(valor_accion)
                    elif tipo_accion == "shock_mf":
                        ESTADO_MODELADOR_ISLM_MF["shock"] = str(valor_accion)
                        _sincronizar_preset_a_parametros_custom_mf(
                            str(valor_accion),
                            str(ESTADO_MODELADOR_ISLM_MF.get("intensidad", "moderado")),
                        )
                    elif tipo_accion == "intensidad_mf":
                        ESTADO_MODELADOR_ISLM_MF["intensidad"] = str(valor_accion)
                        _sincronizar_preset_a_parametros_custom_mf(
                            str(ESTADO_MODELADOR_ISLM_MF.get("shock", "fiscal_exp")),
                            str(valor_accion),
                        )
                cb_tk = getattr(self.fig, "_callback_cambio_filtro_yf", None)
                if callable(cb_tk):
                    cb_tk(tipo_accion, valor_accion)
                else:
                    fn_redraw = getattr(self.fig, "_redibujar_in_place_yf", None)
                    if callable(fn_redraw):
                        fn_redraw()
                        if self.canvas is not None:
                            self.canvas.draw_idle()
                break

    def _detectar_curva_cercana_mf(
        self, ax: plt.Axes, panel_id: str, x_val: float, y_val: float
    ) -> Optional[str]:
        """
        Determina qué curva del Modelador IS-LM-BP (Mundell-Fleming) se encuentra bajo el cursor
        en cualquiera de los 4 paneles (`panel_1_islm`, `panel_2_uip`, `panel_3_invsav`, `panel_4_open`).
        Calcula la distancia normalizada al rango de cada eje para que sea cómodo sujetar cualquier curva.
        """
        eq = getattr(self.fig, "_ultimo_eq_islm_mf", None)
        if not isinstance(eq, dict):
            return None

        Y0, r0, E0, I0, S_nac0 = (
            float(eq["Y0"]), float(eq["r0"]), float(eq["E0"]),
            float(eq["I0"]), float(eq["S_nac0"]),
        )
        Y1, r1, E1, I1, S_nac1 = (
            float(eq["Y1"]), float(eq["r1"]), float(eq["E1"]),
            float(eq["I1"]), float(eq["S_nac1"]),
        )
        b_IS = float(eq["b_IS"])
        gamma_IS = float(eq["gamma_IS"])
        pend_LM = float(eq["pend_LM"])
        pend_BP = float(eq["pend_BP"])
        phi_UIP = float(eq["phi_UIP"])
        b_I = float(eq["b_I"])
        s_r = float(eq["s_r"])
        m_imp = float(eq["m"])
        gamma_NX = float(eq["gamma_NX"])
        dY_IS_aut = float(eq["dY_IS_aut"])
        dr_star = float(eq["dr_star"])
        dI_aut = float(eq["dI_aut"])
        dX_aut = float(eq["dX_aut"])
        reg_sel = str(eq["regimen"])

        candidatos: List[Tuple[float, str]] = []

        if panel_id == "panel_1_islm":
            # Distancia vertical en unidades de r (rango total r = 7.6)
            r_is_at_x = r0 + (dY_IS_aut + gamma_IS * (E1 - E0) - (x_val - Y0)) / b_IS
            dr_lm_fin = (r1 - r0) - pend_LM * (Y1 - Y0)
            r_lm_at_x = r0 + dr_lm_fin + pend_LM * (x_val - Y0)
            r_bp_at_x = (r0 + dr_star - 0.12 * dX_aut) + pend_BP * (x_val - Y0) - 0.04 * (E1 - E0) * (1.0 if pend_BP > 0 else 0.0)
            candidatos.append((abs(y_val - r_is_at_x) / 7.6, "IS"))
            candidatos.append((abs(y_val - r_lm_at_x) / 7.6, "LM"))
            candidatos.append((abs(y_val - r_bp_at_x) / 7.6, "BP"))

        elif panel_id == "panel_2_uip":
            if reg_sel == "fijo":
                candidatos.append((abs(x_val - E1) / 40.0, "E_FIJO"))
            dE_shift_uip = (E1 - E0) + phi_UIP * (r1 - r0)
            e_uip_at_y = E0 + dE_shift_uip - phi_UIP * (y_val - r0)
            candidatos.append((abs(x_val - e_uip_at_y) / 40.0, "UIP"))

        elif panel_id == "panel_3_invsav":
            i_at_y = I0 + dI_aut - b_I * (y_val - r0)
            s_nac_at_y = S_nac1 + s_r * (y_val - r1)
            candidatos.append((abs(x_val - i_at_y) / 20.0, "INV"))
            candidatos.append((abs(x_val - s_nac_at_y) / 20.0, "S_NAC"))

        elif panel_id == "panel_4_open":
            e_is_star_at_x = E1 + (x_val - Y1) / gamma_IS
            e_nx_at_x = E0 + (m_imp * (x_val - Y0) - dX_aut) / gamma_NX
            candidatos.append((abs(y_val - e_is_star_at_x) / 44.0, "IS_STAR"))
            candidatos.append((abs(x_val - Y1) / 32.0, "LM_STAR"))
            candidatos.append((abs(y_val - e_nx_at_x) / 44.0, "NX"))

        if not candidatos:
            return None
        candidatos.sort(key=lambda t: t[0])
        dist_min, nom_c = candidatos[0]
        # Umbral amplio (0.14 del rango del eje) para que sea muy fácil tomar cualquier curva con el cursor
        return nom_c if dist_min <= 0.14 else None

    def _iniciar_drag_curva_mf(
        self, panel_id: str, nombre_curva: str, x0: float, y0: float
    ) -> None:
        """Inicia el arrastre continuo con el cursor de la curva seleccionada."""
        self._ocultar_todos()
        ESTADO_MODELADOR_ISLM_MF["usar_custom"] = True
        ESTADO_MODELADOR_ISLM_MF["shock"] = "custom_drag"
        mapa_etq_drag = {
            "IS": "Curva IS (Gasto / Demanda ΔG)",
            "LM": "Curva LM (Oferta Monetaria / TPM ΔM)",
            "BP": "Curva BP / FE (Tasa Externa / Riesgo Δr*)",
            "UIP": "Curva UIP (Paridad Cambiaria Δr*)",
            "E_FIJO": "Paridad Tipo de Cambio Fijo (Ē)",
            "INV": "Curva de Inversión I(r) (ΔI₀)",
            "S_NAC": "Curva de Ahorro Nacional S_Nac (ΔS_Púb)",
            "IS_STAR": "Curva IS* Abierta (Demanda ΔG)",
            "LM_STAR": "Curva LM* Abierta (Oferta Monetaria ΔM)",
            "NX": "Frontera Comercial NX(E, Y) = 0 (ΔNX₀)",
        }
        ESTADO_MODELADOR_ISLM_MF["curva_activa_drag"] = mapa_etq_drag.get(nombre_curva, nombre_curva)
        self._drag_mf_activo = {
            "panel_id": panel_id,
            "curva": nombre_curva,
            "x_ini": x0,
            "y_ini": y0,
            "dG_ini": float(ESTADO_MODELADOR_ISLM_MF.get("dG_custom", 0.0)),  # type: ignore[arg-type]
            "dM_ini": float(ESTADO_MODELADOR_ISLM_MF.get("dM_custom", 0.0)),  # type: ignore[arg-type]
            "dr_star_ini": float(ESTADO_MODELADOR_ISLM_MF.get("dr_star_custom", 0.0)),  # type: ignore[arg-type]
            "dI_ini": float(ESTADO_MODELADOR_ISLM_MF.get("dI_custom", 0.0)),  # type: ignore[arg-type]
            "dX_ini": float(ESTADO_MODELADOR_ISLM_MF.get("dX_custom", 0.0)),  # type: ignore[arg-type]
            "dE_fijo_ini": float(ESTADO_MODELADOR_ISLM_MF.get("dE_fijo_custom", 0.0)),  # type: ignore[arg-type]
        }
        try:
            if self.canvas is not None and hasattr(self.canvas, "get_tk_widget"):
                self.canvas.get_tk_widget().configure(cursor="fleur")
        except Exception:
            pass

    def _actualizar_drag_curva_mf(self, event) -> None:
        """
        Actualiza en tiempo real los parámetros estructurales al mover el cursor arrastrando
        una curva y redibuja de forma ultraligera los 4 paneles interrelacionados.
        """
        if not self._drag_mf_activo or event.xdata is None or event.ydata is None:
            return

        ahora = time.perf_counter()
        if (ahora - self._ultimo_t_drag_mf) < 0.028:
            return
        self._ultimo_t_drag_mf = ahora

        eq = getattr(self.fig, "_ultimo_eq_islm_mf", None)
        if not isinstance(eq, dict):
            return

        dx = float(event.xdata) - float(self._drag_mf_activo["x_ini"])  # type: ignore[arg-type]
        dy = float(event.ydata) - float(self._drag_mf_activo["y_ini"])  # type: ignore[arg-type]
        curva = str(self._drag_mf_activo["curva"])

        alpha_G = float(eq["alpha_G"])
        b_IS = float(eq["b_IS"])
        b_I = float(eq["b_I"])
        pend_LM = float(eq["pend_LM"])
        h_M = float(eq["h_M"])
        phi_UIP = float(eq["phi_UIP"])
        gamma_IS = float(eq["gamma_IS"])
        gamma_NX = float(eq["gamma_NX"])

        if curva == "IS":
            # Mover IS horizontalmente (dx en Y) o verticalmente (dy en r): dY_IS = dx + b_IS * dy
            dY_shift = dx + b_IS * dy
            nuevo_dG = float(self._drag_mf_activo["dG_ini"]) + (dY_shift / alpha_G)  # type: ignore[arg-type]
            ESTADO_MODELADOR_ISLM_MF["dG_custom"] = float(np.clip(nuevo_dG, -7.5, 7.5))

        elif curva == "LM":
            # Mover LM hacia la derecha/abajo equivale a expansión monetaria (dM > 0): dr_LM = dy - pend_LM * dx = -dM / h_M
            dr_shift = dy - pend_LM * dx
            nuevo_dM = float(self._drag_mf_activo["dM_ini"]) - h_M * dr_shift  # type: ignore[arg-type]
            ESTADO_MODELADOR_ISLM_MF["dM_custom"] = float(np.clip(nuevo_dM, -6.5, 6.5))

        elif curva == "BP":
            # Mover BP verticalmente (dy en r) cambia la tasa externa / prima por riesgo Δr*
            nuevo_drs = float(self._drag_mf_activo["dr_star_ini"]) + dy  # type: ignore[arg-type]
            ESTADO_MODELADOR_ISLM_MF["dr_star_custom"] = float(np.clip(nuevo_drs, -2.8, 2.8))

        elif curva == "UIP":
            # En Panel 2 (E, r): mover UIP hacia la derecha (dx > 0) o arriba (dy > 0) equivale a mayor r* / depreciación
            drs_uip = (dx / phi_UIP) + dy
            nuevo_drs = float(self._drag_mf_activo["dr_star_ini"]) + drs_uip  # type: ignore[arg-type]
            ESTADO_MODELADOR_ISLM_MF["dr_star_custom"] = float(np.clip(nuevo_drs, -2.8, 2.8))

        elif curva == "E_FIJO":
            nuevo_def = float(self._drag_mf_activo["dE_fijo_ini"]) + dx  # type: ignore[arg-type]
            ESTADO_MODELADOR_ISLM_MF["dE_fijo_custom"] = float(np.clip(nuevo_def, -16.0, 16.0))

        elif curva == "INV":
            # En Panel 3 (I, r): mover I(r) horizontalmente (dx en %PIB) o verticalmente (dy en r)
            dI_shift = dx + b_I * dy
            nuevo_dI = float(self._drag_mf_activo["dI_ini"]) + dI_shift  # type: ignore[arg-type]
            ESTADO_MODELADOR_ISLM_MF["dI_custom"] = float(np.clip(nuevo_dI, -7.5, 7.5))

        elif curva == "S_NAC":
            # En Panel 3 (S, r): mover S_Nac hacia la derecha (dx > 0) aumenta el Ahorro Público (menor gasto ΔG < 0)
            nuevo_dG = float(self._drag_mf_activo["dG_ini"]) - dx  # type: ignore[arg-type]
            ESTADO_MODELADOR_ISLM_MF["dG_custom"] = float(np.clip(nuevo_dG, -7.5, 7.5))

        elif curva == "IS_STAR":
            # En Panel 4 (Y, E): mover IS* hacia la derecha (dx > 0) o abajo (dy < 0) expande demanda IS
            dY_shift = dx - gamma_IS * dy
            nuevo_dG = float(self._drag_mf_activo["dG_ini"]) + (dY_shift / alpha_G)  # type: ignore[arg-type]
            ESTADO_MODELADOR_ISLM_MF["dG_custom"] = float(np.clip(nuevo_dG, -7.5, 7.5))

        elif curva == "LM_STAR":
            # En Panel 4 (Y, E): mover LM* horizontalmente (dx en Y) ajusta la oferta monetaria ΔM
            nuevo_dM = float(self._drag_mf_activo["dM_ini"]) + (dx * pend_LM * h_M)  # type: ignore[arg-type]
            ESTADO_MODELADOR_ISLM_MF["dM_custom"] = float(np.clip(nuevo_dM, -6.5, 6.5))

        elif curva == "NX":
            # En Panel 4 (Y, E): mover la frontera NX=0 hacia abajo (dy < 0) o derecha (dx > 0) equivale a boom exportador ΔX₀ > 0
            dX_shift = -gamma_NX * dy
            nuevo_dX = float(self._drag_mf_activo["dX_ini"]) + dX_shift  # type: ignore[arg-type]
            ESTADO_MODELADOR_ISLM_MF["dX_custom"] = float(np.clip(nuevo_dX, -7.0, 7.0))

        # Redibujar en modo rápido sin recrear GestorTooltipsInteractivos durante el movimiento
        self.fig._modo_drag_rapido_mf = True  # type: ignore[attr-defined]
        self.fig._modo_vista_individual_rapida = True  # type: ignore[attr-defined]
        try:
            fn_redraw = getattr(self.fig, "_redibujar_in_place_yf", None)
            if callable(fn_redraw):
                fn_redraw()
            if self.canvas is not None:
                self.canvas.draw_idle()
        finally:
            self.fig._modo_drag_rapido_mf = False  # type: ignore[attr-defined]
            self.fig._modo_vista_individual_rapida = False  # type: ignore[attr-defined]

    def _on_release(self, _event) -> None:
        """Finaliza el arrastre de la curva y restaura el renderizado completo con sombras 3D y tooltips."""
        if not getattr(self, "_drag_mf_activo", None):
            return
        self._drag_mf_activo = None
        ESTADO_MODELADOR_ISLM_MF["curva_activa_drag"] = ""
        try:
            if self.canvas is not None and hasattr(self.canvas, "get_tk_widget"):
                self.canvas.get_tk_widget().configure(cursor="")
        except Exception:
            pass
        cb_tk = getattr(self.fig, "_callback_cambio_filtro_yf", None)
        if callable(cb_tk):
            cb_tk("drag_fin_mf", None)
        else:
            fn_redraw = getattr(self.fig, "_redibujar_in_place_yf", None)
            if callable(fn_redraw):
                fn_redraw()
            if self.canvas is not None:
                self.canvas.draw_idle()

    def _on_draw(self, _event) -> None:
        """Captura el buffer de fondo estático (sin tooltips) para Fast Blitting."""
        if self._en_draw_interno or self.canvas is None:
            return
        try:
            if hasattr(self.canvas, "copy_from_bbox"):
                self._bg_blit = self.canvas.copy_from_bbox(self.fig.bbox)
        except Exception:
            self._bg_blit = None

    def _renderizar_rapido(self, ax_base: Optional[plt.Axes] = None, ax_host: Optional[plt.Axes] = None) -> None:
        """
        Actualiza el tooltip mediante Fast Blitting (< 1 ms) si el backend lo soporta,
        evitando redibujar los 4 gráficos y las tablas en cada movimiento del mouse.
        """
        if self.canvas is None:
            return
        try:
            if (
                hasattr(self.canvas, "restore_region")
                and hasattr(self.canvas, "blit")
            ):
                if self._bg_blit is None and hasattr(self.canvas, "copy_from_bbox"):
                    # Oculta temporalmente los artistas del tooltip para capturar el fondo limpio
                    vis_estados = []
                    for art in (
                        *set(self._annot_por_ax.values()),
                        *set(self._vline_por_ax.values()),
                        *set(self._hline_por_ax.values()),
                        *set(self._marker_por_ax.values()),
                    ):
                        vis_estados.append((art, art.get_visible()))
                        art.set_visible(False)
                    self._en_draw_interno = True
                    try:
                        self.canvas.draw()
                        self._bg_blit = self.canvas.copy_from_bbox(self.fig.bbox)
                    finally:
                        self._en_draw_interno = False
                    for art, v_est in vis_estados:
                        art.set_visible(v_est)

                if self._bg_blit is not None:
                    self.canvas.restore_region(self._bg_blit)
                    if ax_base is not None and ax_host is not None:
                        vl = self._vline_por_ax[ax_host]
                        hl = self._hline_por_ax[ax_host]
                        mk = self._marker_por_ax[ax_host]
                        an = self._annot_por_ax[ax_host]
                        if vl.get_visible():
                            ax_base.draw_artist(vl)
                        if hl.get_visible():
                            ax_base.draw_artist(hl)
                        if mk.get_visible():
                            ax_host.draw_artist(mk)
                        if an.get_visible():
                            ax_host.draw_artist(an)
                    self.canvas.blit(self.fig.bbox)
                    return
        except Exception:
            pass
        self.canvas.draw_idle()

    def _ocultar_todos(self) -> bool:
        cambio = False
        for annot in set(self._annot_por_ax.values()):
            if annot.get_visible():
                annot.set_visible(False)
                cambio = True
        for vl in set(self._vline_por_ax.values()):
            if vl.get_visible():
                vl.set_visible(False)
                cambio = True
        for hl in set(self._hline_por_ax.values()):
            if hl.get_visible():
                hl.set_visible(False)
                cambio = True
        for mk in set(self._marker_por_ax.values()):
            if mk.get_visible():
                mk.set_visible(False)
                cambio = True
        if cambio:
            self._ultimo_snap_key = None
        return cambio

    def _on_leave(self, _event) -> None:
        if self._ocultar_todos():
            self._renderizar_rapido()

    @staticmethod
    def _es_barra_horizontal(ax: plt.Axes) -> bool:
        """Detecta con exactitud si el subplot contiene contenedores barh horizontales."""
        for cont in getattr(ax, "containers", []):
            if getattr(cont, "orientation", None) == "horizontal":
                return True
        return False

    def _on_motion(self, event) -> None:
        if getattr(self, "_drag_mf_activo", None) is not None:
            self._actualizar_drag_curva_mf(event)
            return
        if event.inaxes is not None and getattr(self.fig, "_es_modelador_islm_mf", False):
            panel_mf = getattr(event.inaxes, "_panel_mf_id", None)
            if panel_mf and event.xdata is not None and event.ydata is not None:
                c_hover = self._detectar_curva_cercana_mf(event.inaxes, str(panel_mf), float(event.xdata), float(event.ydata))
                try:
                    if self.canvas is not None and hasattr(self.canvas, "get_tk_widget"):
                        self.canvas.get_tk_widget().configure(cursor="hand2" if c_hover else "")
                except Exception:
                    pass
        if event.inaxes is None or event.inaxes not in self._annot_por_ax:
            if self._ocultar_todos():
                self._renderizar_rapido()
            return

        # Throttling ligero (~25 ms) para movimientos continuos de alta frecuencia
        ahora = time.perf_counter()
        if (ahora - self._ultimo_t_evento) < 0.022 and self._ultimo_snap_key is not None:
            return

        ax_evento = event.inaxes
        grupo = next((g for g in self._grupos_axes if ax_evento in g), [ax_evento])
        ax_base = grupo[0]
        ax_host = grupo[-1]
        info = self._cache_grupo.get(ax_host, {})

        annot = self._annot_por_ax[ax_host]
        vline = self._vline_por_ax[ax_host]
        hline = self._hline_por_ax[ax_host]
        marker = self._marker_por_ax[ax_host]

        # Caso 1: Gráfico de barras horizontales (barh)
        if info.get("es_barh", False):
            centros_y: np.ndarray = info.get("centros_y", np.asarray([]))  # type: ignore[assignment]
            anchos_x: np.ndarray = info.get("anchos_x", np.asarray([]))  # type: ignore[assignment]
            etiquetas_h: List[str] = info.get("etiquetas_h", [])  # type: ignore[assignment]
            if len(centros_y) == 0 or event.ydata is None:
                return
            idx_cercano = int(np.argmin(np.abs(centros_y - float(event.ydata))))
            snap_key = (id(ax_host), idx_cercano)
            if snap_key == self._ultimo_snap_key and annot.get_visible():
                return

            if self._ultimo_ax_activo is not None and self._ultimo_ax_activo not in grupo:
                self._ocultar_todos()
            self._ultimo_ax_activo = ax_host
            self._ultimo_snap_key = snap_key
            self._ultimo_t_evento = ahora

            cy = float(centros_y[idx_cercano])
            val_x = float(anchos_x[idx_cercano])
            etiqueta_cat = etiquetas_h[idx_cercano]

            vline.set_visible(False)
            hline.set_ydata([cy, cy])
            hline.set_visible(True)
            marker.set_data([val_x], [cy])
            marker.set_visible(True)

            texto_bh = f"▸ {etiqueta_cat}\n• Valor: {val_x:+,.2f}"
            ancho_est_bh = max(len(lin) for lin in texto_bh.splitlines()) * 6.8 + 26.0
            pt_bh_x, pt_bh_y = ax_host.transData.transform((val_x, cy))
            # Siempre del lado izquierdo del dato, salvo que esté pegado al borde izquierdo de la ventana
            if (pt_bh_x - ancho_est_bh - 18.0) >= 8.0:
                annot.set_ha("right")
                off_x_bh = -14
            else:
                annot.set_ha("left")
                off_x_bh = 14
            off_y_bh = -26 if pt_bh_y > (self.fig.bbox.height * 0.72) else 10
            annot.xy = (val_x, cy)
            annot.xytext = (off_x_bh, off_y_bh)
            annot.set_text(texto_bh)
            annot.set_visible(True)
            self._renderizar_rapido(ax_base=ax_base, ax_host=ax_host)
            return

        # Caso 2: Series de tiempo o barras verticales (x = fecha o índice categórico)
        if event.xdata is None:
            return

        arr_x: np.ndarray = info.get("arr_x", np.asarray([]))  # type: ignore[assignment]
        if len(arr_x) == 0:
            return

        if ax_evento == ax_base:
            x_base_cursor = float(event.xdata)
        else:
            try:
                x_base_cursor, _ = ax_base.transData.inverted().transform((event.x, event.y))
            except Exception:
                x_base_cursor = float(event.xdata)

        idx_x = int(np.argmin(np.abs(arr_x - x_base_cursor)))
        snap_key = (id(ax_host), idx_x)

        # Si el cursor sigue sobre el mismo período/barra del mismo gráfico, no redibujar
        if snap_key == self._ultimo_snap_key and annot.get_visible():
            return

        if self._ultimo_ax_activo is not None and self._ultimo_ax_activo not in grupo:
            self._ocultar_todos()
        self._ultimo_ax_activo = ax_host
        self._ultimo_snap_key = snap_key
        self._ultimo_t_evento = ahora

        x_snap = float(arr_x[idx_x])
        tol_x = float(info.get("tol_x", 1.0))  # type: ignore[arg-type]
        cache_etq_x: Dict[int, str] = info.get("cache_etq_x", {})  # type: ignore[assignment]
        if idx_x in cache_etq_x:
            periodo_txt = cache_etq_x[idx_x]
        else:
            todas_anuales = bool(info.get("todas_anuales", False))
            if x_snap > 700000 or (1970 <= x_snap <= 30000):
                periodo_txt = _formatear_fecha_tooltip(x_snap, todas_anuales=todas_anuales)
            else:
                xticks = list(ax_base.get_xticks())
                xlabels = [t.get_text().strip() for t in ax_base.get_xticklabels()]
                if xticks and xlabels and any(xlabels):
                    idx_xt = int(np.argmin([abs(xt - x_snap) for xt in xticks]))
                    periodo_txt = xlabels[idx_xt] if idx_xt < len(xlabels) and xlabels[idx_xt] else f"{x_snap:,.0f}"
                else:
                    periodo_txt = _formatear_fecha_tooltip(x_snap, todas_anuales=todas_anuales)
            cache_etq_x[idx_x] = periodo_txt

        ohlc_meta = getattr(ax_base, "_ohlc_tooltip_data", None)
        lineas_texto: List[str] = [f"▸ Período: {periodo_txt}"]
        punto_destacado: Optional[Tuple[plt.Axes, float, float]] = None

        if isinstance(ohlc_meta, dict) and len(ohlc_meta.get("x_num", [])) > 0:
            arr_xo = np.asarray(ohlc_meta["x_num"], dtype=float)
            i_oh = int(np.argmin(np.abs(arr_xo - x_snap)))
            if abs(float(arr_xo[i_oh]) - x_snap) <= max(tol_x, 1.5):
                fechas_oh = ohlc_meta.get("fechas_str", [])
                etq_iv = str(ohlc_meta.get("intervalo_etq", "Vela"))
                f_str = fechas_oh[i_oh] if i_oh < len(fechas_oh) else periodo_txt
                dec_oh = int(ohlc_meta.get("dec", 2))
                pref_oh = str(ohlc_meta.get("pref", ""))
                suf_oh = str(ohlc_meta.get("suf", ""))
                o_v = float(ohlc_meta["opens"][i_oh])
                h_v = float(ohlc_meta["highs"][i_oh])
                l_v = float(ohlc_meta["lows"][i_oh])
                c_v = float(ohlc_meta["closes"][i_oh])
                var_v = ((c_v / o_v) - 1.0) * 100.0 if o_v > 0 else 0.0
                fl_v = "▲ Alcista" if c_v >= o_v else "▼ Bajista"
                lineas_texto = [
                    f"▸ {etq_iv}: {f_str} ({fl_v} {var_v:+.2f}%)",
                    f"• Apertura (Open): {pref_oh}{o_v:,.{dec_oh}f}{suf_oh}",
                    f"• Máximo (High):   {pref_oh}{h_v:,.{dec_oh}f}{suf_oh}",
                    f"• Mínimo (Low):    {pref_oh}{l_v:,.{dec_oh}f}{suf_oh}",
                    f"• Cierre (Close):  {pref_oh}{c_v:,.{dec_oh}f}{suf_oh}",
                ]
                punto_destacado = (ax_base, float(arr_xo[i_oh]), c_v)

        series_lineas: List[Tuple[plt.Axes, str, np.ndarray, np.ndarray]] = info.get(
            "series_lineas", []
        )  # type: ignore[assignment]
        for ax_m, nom_limpio, xd, yd in series_lineas:
            if ohlc_meta is not None and "Precio de Cotización" in nom_limpio:
                continue
            i_ln = int(np.argmin(np.abs(xd - x_snap)))
            if abs(float(xd[i_ln]) - x_snap) <= tol_x and np.isfinite(yd[i_ln]):
                val_y = float(yd[i_ln])
                lineas_texto.append(f"• {nom_limpio}: {val_y:,.2f}")
                if punto_destacado is None:
                    punto_destacado = (ax_m, float(xd[i_ln]), val_y)

        series_barras: List[Tuple[plt.Axes, str, np.ndarray, np.ndarray, float]] = info.get(
            "series_barras", []
        )  # type: ignore[assignment]
        for ax_m, etiq_b, centros_b, alturas_b, ancho_b in ([] if ohlc_meta is not None else series_barras):
            i_b = int(np.argmin(np.abs(centros_b - x_snap)))
            if abs(float(centros_b[i_b]) - x_snap) <= max(tol_x, ancho_b):
                val_b = float(alturas_b[i_b])
                if np.isfinite(val_b):
                    entry_b = f"• {etiq_b}: {val_b:,.2f}"
                    if entry_b not in lineas_texto:
                        lineas_texto.append(entry_b)
                    if punto_destacado is None:
                        punto_destacado = (ax_m, float(centros_b[i_b]), val_b)

        if len(lineas_texto) <= 1:
            if self._ocultar_todos():
                self._renderizar_rapido()
            return

        vline.set_xdata([x_snap, x_snap])
        vline.set_visible(True)
        hline.set_visible(False)

        if punto_destacado is not None:
            ax_p, xp, yp = punto_destacado
            if ax_p == ax_host:
                xh, yh = xp, yp
            else:
                pt_disp = ax_p.transData.transform((xp, yp))
                xh, yh = ax_host.transData.inverted().transform(pt_disp)
            marker.set_data([xh], [yh])
            marker.set_visible(True)
            annot.xy = (xh, yh)
        else:
            annot.xy = (event.xdata, event.ydata if event.ydata is not None else 0.0)
            marker.set_visible(False)

        lineas_mostrar = lineas_texto[:10]
        texto_final = "\n".join(lineas_mostrar)

        # Posiciona el recuadro (etiqueta) del LADO IZQUIERDO del cursor/dato (ha='right', offset_x=-16)
        # para que jamás se salga por el borde derecho de la aplicación. Sólo si el cursor está muy
        # cerca del borde izquierdo físico de la figura (donde no cabría a la izquierda), lo desplaza
        # suavemente hacia adentro para que siempre sea 100% visible dentro del cuadro.
        ancho_est_px = max(len(lin) for lin in lineas_mostrar) * 6.8 + 28.0
        alto_est_px = len(lineas_mostrar) * 14.5 + 18.0

        try:
            anchor_px_x, anchor_px_y = ax_host.transData.transform(annot.xy)
        except Exception:
            anchor_px_x = float(event.x) if event.x is not None else 400.0
            anchor_px_y = float(event.y) if event.y is not None else 300.0

        margen_izq_fig = 10.0
        if (anchor_px_x - ancho_est_px - 18.0) >= margen_izq_fig:
            annot.set_ha("right")
            offset_x = -16
        else:
            # Si está pegado al extremo izquierdo de los paneles izquierdos, desplaza el borde
            # derecho de la etiqueta justo lo necesario para no salir por la izquierda de la app
            annot.set_ha("left")
            offset_x = 14

        bbox_ax = ax_host.get_window_extent()
        rel_y = (
            ((event.y if event.y is not None else anchor_px_y) - bbox_ax.y0)
            / max(bbox_ax.height, 1.0)
        )
        if rel_y > 0.55 or (anchor_px_y + alto_est_px + 20.0) > (self.fig.bbox.height - 12.0):
            offset_y = -14 - int(len(lineas_mostrar) * 11.5)
        else:
            offset_y = 14

        annot.xytext = (offset_x, offset_y)
        annot.set_text(texto_final)
        annot.set_visible(True)
        self._renderizar_rapido(ax_base=ax_base, ax_host=ax_host)



