def _obtener_ficha_descriptiva_grafico(titulo_ax: str, fuente_texto: str) -> Tuple[str, str, str]:
    """
    Busca en `CATALOGO_DESCRIPCIONES_VARIABLES_GRAFICOS` y `MAPA_COMO_SE_MIDE_POR_CLAVE`:
      1. Variable y qué mide.
      2. Institución a cargo de la medición.
      3. ¿Cómo se mide? (metodología estadística o econométrica de medición).
    """
    t_low = f"{titulo_ax} || {fuente_texto}".lower()
    que_mide_res = ""
    inst_res = ""
    for claves_match, que_mide, quien_mide in CATALOGO_DESCRIPCIONES_VARIABLES_GRAFICOS:
        if any(k in t_low for k in claves_match):
            que_mide_res = que_mide
            inst_res = quien_mide
            break
    if not que_mide_res:
        t_limpio = titulo_ax.strip() or "Serie Macroeconómica / Financiera"
        f_limpia = fuente_texto.replace("Fuente:", "").strip()
        que_mide_res = (
            f"Variable: {t_limpio}. Qué mide: Cuantifica la evolución temporal, nivel y tasa de variación "
            "de la serie seleccionada para el análisis coyuntural y estructural de la economía chilena."
        )
        inst_res = f"Institución a cargo de la medición: {f_limpia}"

    como_res = (
        "¿Cómo se mide?: Se construye a partir de registros estadísticos oficiales armonizados (índices encadenados "
        "base 2018=100, encuestas nacionales o saldos monetarios/fiscales devengados) aplicando variaciones porcentuales "
        "respecto al período base o a igual período del año anterior (% a/a)."
    )
    for claves_c, txt_como in MAPA_COMO_SE_MIDE_POR_CLAVE:
        if any(k in t_low for k in claves_c):
            como_res = txt_como
            break

    return que_mide_res, inst_res, como_res


def _agregar_pie_fuente_ax(
    ax: plt.Axes,
    fuente_texto: str,
    y_offset: Optional[float] = None,
) -> None:
    if getattr(ax.figure, "_modo_vista_individual_rapida", False):
        return
    """
    Inserta al pie de cada gráfico individual (`ax`) un recuadro metodológico con:
      1. Variable y qué mide.
      2. Institución a cargo de la medición.
      3. ¿Cómo se mide?.
    Adapta automáticamente el ancho de línea y la posición vertical según el ancho del subplot en la figura.
    """
    titulo_ax = ax.get_title(loc="left") or ax.get_title() or ""
    que_mide, inst_mide, como_mide = _obtener_ficha_descriptiva_grafico(titulo_ax, fuente_texto)

    try:
        pos_w = float(ax.get_position().width)
    except Exception:
        pos_w = 0.42

    es_ancho_completo = pos_w >= 0.68
    ancho_wrap = 164 if es_ancho_completo else 122
    fs_box = 8.20 if es_ancho_completo else 5.50

    lin_que = textwrap.fill(f"● {que_mide}", width=ancho_wrap)
    lin_inst = textwrap.fill(f"▪ {inst_mide}", width=ancho_wrap)
    lin_como = textwrap.fill(f"• {como_mide}", width=ancho_wrap)
    texto_completo = lin_que + "\n" + lin_inst + "\n" + lin_como

    if y_offset is not None:
        y_pos = y_offset
    elif not ax.axison:
        y_pos = -0.025
    elif es_ancho_completo:
        y_pos = -0.105
    elif bool(ax.get_xlabel().strip()):
        y_pos = -0.128
    else:
        y_pos = -0.104

    ax.text(
        0.0,
        y_pos,
        texto_completo,
        transform=ax.transAxes,
        fontsize=fs_box,
        color="#1E293B",
        ha="left",
        va="top",
        linespacing=1.18,
        clip_on=False,
        bbox=dict(
            boxstyle="round,pad=0.22",
            fc="#F8FAFC",
            ec="#CBD5E1",
            lw=0.75,
            alpha=0.96,
        ),
    )


def _dibujar_recuadro_descripcion_ancho_completo_figura(
    fig: plt.Figure,
    titulo_ficha: str,
    fuente_texto: str,
    color_borde: str = "#1E40AF",
    rect_desc: Optional[List[float]] = None,
    texto_personalizado: Optional[Tuple[str, str, str]] = None,
    ancho_wrap: int = 218,
) -> plt.Axes:
    """
    Dibuja un recuadro metodológico de 3 niveles (● Variable y qué mide, ▪ Institución a cargo
    de la medición, • ¿Cómo se mide?) A TODO LO ANCHO DE LA PANTALLA (0.045 a 0.955),
    con el mismo diseño institucional de las Vistas Macroeconómicas.
    """
    if rect_desc is None:
        rect_desc = [0.045, 0.044, 0.910, 0.126]
    if texto_personalizado is not None:
        que_m, inst_m, como_m = texto_personalizado
    else:
        que_m, inst_m, como_m = _obtener_ficha_descriptiva_grafico(titulo_ficha, fuente_texto)

    nuevo_txt = (
        textwrap.fill(f"● {que_m}", width=ancho_wrap)
        + "\n"
        + textwrap.fill(f"▪ {inst_m}", width=ancho_wrap)
        + "\n"
        + textwrap.fill(f"• {como_m}", width=ancho_wrap)
    )
    n_lineas = nuevo_txt.count("\n") + 1
    fs_desc = 8.9 if n_lineas <= 5 else (8.4 if n_lineas == 6 else (7.9 if n_lineas == 7 else 7.4))

    ax_desc = fig.add_axes(rect_desc)
    ax_desc.set_axis_off()
    ax_desc.set_xlim(0.0, 1.0)
    ax_desc.set_ylim(0.0, 1.0)
    caja_desc = mpatches.FancyBboxPatch(
        (0.003, 0.05),
        0.994,
        0.90,
        boxstyle="round,pad=0.002,rounding_size=0.012",
        facecolor="#F8FAFC",
        edgecolor=color_borde,
        linewidth=1.20,
        transform=ax_desc.transAxes,
        zorder=1,
    )
    ax_desc.add_patch(caja_desc)
    ax_desc.text(
        0.010,
        0.50,
        nuevo_txt,
        transform=ax_desc.transAxes,
        fontsize=fs_desc,
        color="#0F172A",
        ha="left",
        va="center",
        linespacing=1.20,
        zorder=2,
    )
    return ax_desc


def _aplicar_efecto_3d_separacion_graficos(fig: plt.Figure) -> None:
    """
    Aplica un sutil efecto 3D de elevación y separación visual entre todos los
    gráficos y paneles de una figura de Matplotlib:
      1. Fondo exterior de la lámina en tono gris-azulado perla suave (`#FAFBFD`) para que
         cada gráfico blanco puro (`#FFFFFF`) resalte como una tarjeta elevada independiente.
      2. Sombra proyectada 3D (`SimplePatchShadow`) bajo el lienzo blanco de cada gráfico (`ax.patch`),
         generando profundidad física sin alterar las grillas ni los datos.
      3. Biselado 3D en los bordes (`spines`): bordes superior e izquierdo iluminados (`#CBD5E1`)
         y bordes inferior y derecho más profundos (`#64748B`), logrando separación nítida entre paneles.
    """
    try:
        import matplotlib.patheffects as patheffects
    except Exception:
        return

    # Mantener intacta la lámina de Presentación Profesional o diferir si estamos en fase intermedia rápida
    if getattr(fig, "_es_vista_presentacion", False) or getattr(fig, "_modo_vista_individual_rapida", False):
        return

    fig.patch.set_facecolor("#FAFBFD")

    for ax in fig.axes:
        # Si es un eje con marco visible (gráfico de líneas, barras, áreas o velas japonesas)
        if ax.get_frame_on() and ax.axison:
            ax.set_facecolor("#FFFFFF")
            ax.patch.set_facecolor("#FFFFFF")
            ax.patch.set_alpha(1.0)
            ax.patch.set_edgecolor("#94A3B8")
            ax.patch.set_linewidth(0.95)
            try:
                ax.patch.set_path_effects(
                    [
                        patheffects.SimplePatchShadow(
                            offset=(4.2, -4.2),
                            shadow_rgbFace="#64748B",
                            alpha=0.28,
                        ),
                        patheffects.Normal(),
                    ]
                )
            except Exception:
                pass

            # Biselado 3D sutil en los 4 bordes del gráfico
            if "top" in ax.spines:
                ax.spines["top"].set_visible(True)
                ax.spines["top"].set_color("#CBD5E1")
                ax.spines["top"].set_linewidth(0.95)
            if "left" in ax.spines:
                ax.spines["left"].set_visible(True)
                ax.spines["left"].set_color("#94A3B8")
                ax.spines["left"].set_linewidth(1.10)
            if "bottom" in ax.spines:
                ax.spines["bottom"].set_visible(True)
                ax.spines["bottom"].set_color("#475569")
                ax.spines["bottom"].set_linewidth(1.30)
            if "right" in ax.spines:
                ax.spines["right"].set_visible(True)
                ax.spines["right"].set_color("#64748B")
                ax.spines["right"].set_linewidth(1.15)
        else:
            # Para cintillos o tablas ejecutivas con bbox, añadir sombra suave a los cuadros contenedores
            for txt_obj in ax.texts:
                patch_bbox = txt_obj.get_bbox_patch()
                if patch_bbox is not None:
                    try:
                        patch_bbox.set_path_effects(
                            [
                                patheffects.SimplePatchShadow(
                                    offset=(3.2, -3.2),
                                    shadow_rgbFace="#64748B",
                                    alpha=0.24,
                                ),
                                patheffects.Normal(),
                            ]
                        )
                    except Exception:
                        pass


def activar_tooltips_interactivos(fig: plt.Figure, canvas=None) -> Optional[GestorTooltipsInteractivos]:
    """
    Aplica el efecto 3D de separación visual entre gráficos y activa (o actualiza)
    el gestor de tooltips interactivos sobre una figura `fig`.
    Si la figura ya construyó sus artistas en el pase actual y sólo se está adjuntando
    `canvas`, conecta los eventos en < 0.1 ms sin reconstruir artistas ni sombras 3D.
    """
    if fig is not None and (
        getattr(fig, "_modo_vista_individual_rapida", False)
        or getattr(fig, "_modo_impresion_pdf_sin_tooltips", False)
    ):
        return None
    fid = id(fig)
    gestor_prev = _REGISTRO_TOOLTIPS_FIGURAS.get(fid)
    firma_axes = tuple(id(ax) for ax in fig.axes)
    if (
        isinstance(gestor_prev, GestorTooltipsInteractivos)
        and getattr(fig, "_firma_axes_tooltips", None) == firma_axes
        and canvas is not None
    ):
        gestor_prev.desconectar()
        gestor_prev.canvas = canvas
        if "_aplicar_tema_figura_mpl" in globals():
            _aplicar_tema_figura_mpl(fig)
        gestor_prev._bg_blit = None
        gestor_prev._conectar_eventos()
        return gestor_prev

    _aplicar_efecto_3d_separacion_graficos(fig)
    if "_aplicar_tema_figura_mpl" in globals():
        _aplicar_tema_figura_mpl(fig)
    if isinstance(gestor_prev, GestorTooltipsInteractivos):
        gestor_prev.desconectar()
    nuevo_gestor = GestorTooltipsInteractivos(fig=fig, canvas=canvas)
    fig._firma_axes_tooltips = firma_axes  # type: ignore[attr-defined]
    _REGISTRO_TOOLTIPS_FIGURAS[fid] = nuevo_gestor
    return nuevo_gestor


