def clasificar_capitulo_hs_a_seccion(codigo_hs: object) -> str:
    """
    Traduce el código de producto `k` de BACI-CEPII (6 dígitos del Sistema Armonizado,
    donde los 2 primeros dígitos representan el capítulo / sección arancelaria, ej.
    260300 -> capítulo 26 -> Sección V Minerales) a su sección arancelaria analítica.
    """
    try:
        s_cod = str(int(float(str(codigo_hs).strip()))).zfill(6)
        cap = int(s_cod[:2])
    except Exception:
        return "Maquinaria, metales preciosos y resto (Otras Secc.)"

    if 25 <= cap <= 27:
        return "Minerales y concentrados (Secc. V, Cap. 25-27)"
    if 72 <= cap <= 83:
        return "Metales comunes y cobre refinado (Secc. XV, Cap. 72-83)"
    if 28 <= cap <= 38:
        return "Químicos, litio, yodo y nitratos (Secc. VI, Cap. 28-38)"
    if 6 <= cap <= 14:
        return "Reino vegetal y frutas frescas (Secc. II, Cap. 06-14)"
    if 1 <= cap <= 5:
        return "Reino animal, salmón y pesca (Secc. I, Cap. 01-05)"
    if 44 <= cap <= 49:
        return "Madera, celulosa y papel (Secc. IX-X, Cap. 44-49)"
    if 15 <= cap <= 24:
        return "Alimentos, vinos y bebidas (Secc. III-IV, Cap. 15-24)"
    return "Maquinaria, metales preciosos y resto (Otras Secc.)"


def descargar_y_filtrar_baci(
    url_descarga: str,
    archivo_salida: str = "exportaciones_chile_baci.csv",
    codigo_pais: int = 152,
    cookies: Optional[Dict[str, str]] = None,
    chunksize: int = 1_000_000,
) -> pd.DataFrame:
    """
    Descarga un archivo ZIP masivo de BACI-CEPII (o lee una ruta local .zip/.csv),
    lo descomprime y lee el CSV en bloques (`chunksize=1_000_000`) para no saturar
    la memoria RAM, filtrando únicamente las filas donde Chile es el exportador (`i == 152`).

    Nomenclatura BACI-CEPII:
      - `t`: Año (Year)
      - `i`: Exportador (152 = Chile)
      - `j`: Importador / Destino (ej. 156 = China, 840 = EE.UU., 392 = Japón)
      - `k`: Código del producto HS6 (los 2 primeros dígitos corresponden al capítulo/sección arancelaria)
      - `v`: Valor de la exportación en miles de dólares FOB
      - `q`: Cantidad en toneladas métricas
    """
    import requests

    ruta_local = Path(url_descarga)
    chunks_filtrados: List[pd.DataFrame] = []

    if ruta_local.is_file():
        print(f"1. Leyendo archivo BACI local: {ruta_local}...")
        if ruta_local.suffix.lower() == ".zip":
            with zipfile.ZipFile(ruta_local, "r") as z:
                archivos_csv = [f for f in z.namelist() if f.lower().endswith(".csv") and "country" not in f.lower() and "product" not in f.lower()]
                if not archivos_csv:
                    raise ValueError("No se encontró ningún archivo CSV de flujos BACI en el ZIP.")
                archivo_baci = archivos_csv[0]
                with z.open(archivo_baci) as f:
                    for idx_c, chunk in enumerate(pd.read_csv(f, chunksize=chunksize)):
                        col_exp = "i" if "i" in chunk.columns else chunk.columns[1]
                        chunk_chile = chunk[chunk[col_exp] == codigo_pais]
                        if not chunk_chile.empty:
                            chunks_filtrados.append(chunk_chile)
                        print(f"   - Procesado bloque {idx_c + 1} ({(idx_c + 1)}M filas revisadas...)")
        else:
            for idx_c, chunk in enumerate(pd.read_csv(ruta_local, chunksize=chunksize)):
                col_exp = "i" if "i" in chunk.columns else chunk.columns[1]
                chunk_chile = chunk[chunk[col_exp] == codigo_pais]
                if not chunk_chile.empty:
                    chunks_filtrados.append(chunk_chile)
    else:
        print("1. Iniciando descarga del archivo ZIP desde CEPII...")
        response = requests.get(url_descarga, cookies=cookies, stream=True, timeout=180)
        response.raise_for_status()

        print("2. Descarga completada. Descomprimiendo y filtrando por chunks en memoria...")
        with zipfile.ZipFile(BytesIO(response.content)) as z:
            archivos_csv = [f for f in z.namelist() if f.lower().endswith(".csv") and "country" not in f.lower() and "product" not in f.lower()]
            if not archivos_csv:
                raise ValueError("No se encontró ningún archivo CSV en el ZIP de BACI.")
            archivo_baci = archivos_csv[0]
            print(f"3. Archivo detectado: {archivo_baci}. Iniciando filtrado por chunks (i == {codigo_pais})...")
            with z.open(archivo_baci) as f:
                for idx_c, chunk in enumerate(pd.read_csv(f, chunksize=chunksize)):
                    col_exp = "i" if "i" in chunk.columns else chunk.columns[1]
                    chunk_chile = chunk[chunk[col_exp] == codigo_pais]
                    if not chunk_chile.empty:
                        chunks_filtrados.append(chunk_chile)
                    print(f"   - Procesado bloque {idx_c + 1} ({(idx_c + 1)}M filas revisadas...)")

    print("4. Consolidando datos de Chile...")
    df_final = (
        pd.concat(chunks_filtrados, ignore_index=True)
        if chunks_filtrados
        else pd.DataFrame(columns=["t", "i", "j", "k", "v", "q"])
    )
    if archivo_salida:
        Path(archivo_salida).parent.mkdir(parents=True, exist_ok=True)
        df_final.to_csv(archivo_salida, index=False)
        print(f"¡Éxito! Datos guardados en {archivo_salida} con {len(df_final)} registros.")
    return df_final


def procesar_dataframe_baci_chile(
    df_baci: pd.DataFrame,
) -> Tuple[pd.DataFrame, pd.DataFrame]:
    """
    A partir de un DataFrame filtrado de BACI para Chile (`i == 152`, columnas `t`, `j`, `k`, `v`),
    calcula para cada año `t`:
      1. Participación (%) de cada destino principal en el valor total exportado (`v`).
      2. Participación (%) de cada sección arancelaria (según los 2 primeros dígitos de `k`)
         en el valor total exportado (`v`).
    """
    if df_baci is None or df_baci.empty:
        return pd.DataFrame(), pd.DataFrame()

    df = df_baci.copy()
    df.columns = [str(c).strip().lower() for c in df.columns]
    if "i" in df.columns:
        df = df[df["i"] == 152]
    if df.empty or not {"t", "j", "k", "v"}.issubset(df.columns):
        return pd.DataFrame(), pd.DataFrame()

    df["v"] = pd.to_numeric(df["v"], errors="coerce").fillna(0.0)
    df["t"] = pd.to_numeric(df["t"], errors="coerce").astype(int)
    df["j_num"] = pd.to_numeric(df["j"], errors="coerce").fillna(-1).astype(int)

    df["destino"] = df["j_num"].map(
        lambda cod: MAPA_PAISES_ONU_BACI_DESTINOS.get(cod, "Resto del Mundo")
    )
    df["seccion"] = df["k"].map(clasificar_capitulo_hs_a_seccion)

    piv_dest = df.pivot_table(index="t", columns="destino", values="v", aggfunc="sum", fill_value=0.0)
    for col_d in DESTINOS_EXPORTACION_METADATA.keys():
        if col_d not in piv_dest.columns:
            piv_dest[col_d] = 0.0
    piv_dest = piv_dest[list(DESTINOS_EXPORTACION_METADATA.keys())]
    tot_dest = piv_dest.sum(axis=1).replace(0.0, np.nan)
    pct_dest = piv_dest.div(tot_dest, axis=0) * 100.0
    pct_dest.index = pd.to_datetime([pd.Timestamp(year=int(y), month=1, day=1) for y in pct_dest.index])

    piv_secc = df.pivot_table(index="t", columns="seccion", values="v", aggfunc="sum", fill_value=0.0)
    for col_s in SECCIONES_ARANCELARIAS_METADATA.keys():
        if col_s not in piv_secc.columns:
            piv_secc[col_s] = 0.0
    piv_secc = piv_secc[list(SECCIONES_ARANCELARIAS_METADATA.keys())]
    tot_secc = piv_secc.sum(axis=1).replace(0.0, np.nan)
    pct_secc = piv_secc.div(tot_secc, axis=0) * 100.0
    pct_secc.index = pd.to_datetime([pd.Timestamp(year=int(y), month=1, day=1) for y in pct_secc.index])

    return pct_dest.round(2), pct_secc.round(2)


def descargar_baci_cepii_ultimo_disponible(
    anio_min: int = 2024,
    cookies: Optional[Dict[str, str]] = None,
    carpeta_destino: Optional[Path] = None,
) -> pd.DataFrame:
    """
    Automatiza la búsqueda y descarga del último archivo disponible de BACI-CEPII
    (año 2024 o superior, probando desde el año en curso hacia atrás en las versiones
    HS22, HS17, HS12 y HS92) o procesa automáticamente cualquier archivo `.zip` / `.csv`
    de BACI depositado en `~/EcoPulse_Analytics/baci/` o en la carpeta de Descargas.
    """
    import requests

    dest_dir = carpeta_destino or RUTA_CARPETA_BACI
    dest_dir.mkdir(parents=True, exist_ok=True)

    # 1. Revisa primero si existen archivos ZIP o CSV de BACI en carpetas locales (incluyendo Downloads)
    carpetas_busqueda = [
        dest_dir,
        RUTA_DIRECTORIO_APP,
        Path.cwd(),
        Path.home() / "Downloads",
        Path.home() / "Descargas",
    ]
    for carp in carpetas_busqueda:
        if not carp.is_dir():
            continue
        for patron in ("BACI_*.zip", "baci_*.zip", "exportaciones_chile*.csv"):
            for archivo_cand in sorted(carp.glob(patron), reverse=True):
                try:
                    salida_csv = dest_dir / f"exportaciones_chile_{archivo_cand.stem}.csv"
                    if archivo_cand.suffix.lower() == ".zip" and not salida_csv.is_file():
                        return descargar_y_filtrar_baci(
                            url_descarga=str(archivo_cand),
                            archivo_salida=str(salida_csv),
                            codigo_pais=152,
                        )
                    elif archivo_cand.suffix.lower() == ".csv":
                        return pd.read_csv(archivo_cand)
                except Exception:
                    continue

    # 2. Intenta descargar automáticamente desde CEPII el último año disponible (>= anio_min)
    anio_actual = max(date.today().year, anio_min)
    versiones_cepii = ["V202601", "V202501", "V202401b", "V202401"]
    revisiones_hs = ["HS22", "HS17", "HS12", "HS92"]

    for anio in range(anio_actual, anio_min - 1, -1):
        urls_candidatas = [
            f"http://www.cepii.fr/DATA_DOWNLOAD/baci/data/BACI_HS92_Y{anio}.zip",
            f"https://www.cepii.fr/DATA_DOWNLOAD/baci/data/BACI_HS92_Y{anio}.zip",
        ]
        for rev in revisiones_hs:
            for ver in versiones_cepii:
                urls_candidatas.append(
                    f"https://www.cepii.fr/DATA_DOWNLOAD/baci/data/BACI_{rev}_Y{anio}_{ver}.zip"
                )
        for url_c in urls_candidatas:
            try:
                resp_head = requests.head(url_c, cookies=cookies, timeout=6, allow_redirects=True)
                ctype = str(resp_head.headers.get("Content-Type", "")).lower()
                if resp_head.status_code == 200 and ("zip" in ctype or "octet-stream" in ctype):
                    salida_auto = dest_dir / f"exportaciones_chile_{anio}.csv"
                    return descargar_y_filtrar_baci(
                        url_descarga=url_c,
                        archivo_salida=str(salida_auto),
                        codigo_pais=152,
                        cookies=cookies,
                    )
            except Exception:
                continue

    return pd.DataFrame()


# Catálogo de series BDE (Banco Central de Chile) para actualizar automáticamente
# el Destino de las exportaciones chilenas y la Composición de bienes exportados
# con los últimos datos disponibles (2024, 2025, 2026+)
