def importar_anexo_ptf_excel_csv(
    ruta_archivo: str,
) -> Dict[str, pd.DataFrame]:
    """
    Importa automáticamente anexos estadísticos en formato Excel (.xlsx / .xls) o CSV
    descargados desde:
      - CNEP (`cnep.cl` -> Publicaciones -> Informe Anual de Productividad -> Anexo Estadístico Excel)
      - Clapes UC (`clapesuc.cl` -> Productividad Total de Factores -> Base de datos Excel/CSV)
    Detecta de manera inteligente las columnas de PTF-A, PTF-B, PTF-C, PTF-D (trimestrales)
    o PTF Agregada / PTF Sin Minería / Servicios de Capital (anuales) y retorna los DataFrames
    normalizados listos para fusionarse en memoria y en `~/EcoPulse_Analytics/ptf/`.
    """
    ruta_p = Path(ruta_archivo)
    if not ruta_p.is_file():
        return {}

    tablas_leidas: List[pd.DataFrame] = []
    try:
        if ruta_p.suffix.lower() in (".xlsx", ".xls"):
            xls = pd.ExcelFile(ruta_p)
            for hoja in xls.sheet_names:
                try:
                    df_h = pd.read_excel(ruta_p, sheet_name=hoja)
                    if not df_h.empty:
                        tablas_leidas.append(df_h)
                except Exception:
                    pass
        else:
            df_c = pd.read_csv(ruta_p)
            if not df_c.empty:
                tablas_leidas.append(df_c)
    except Exception:
        return {}

    out: Dict[str, pd.DataFrame] = {}
    for df_raw in tablas_leidas:
        df = df_raw.copy()
        cols_lower = {str(c).strip().lower(): c for c in df.columns}
        col_fecha = None
        for cand_f in ("fecha", "date", "periodo", "período", "año", "anio", "year", "trimestre", "quarter"):
            for k_low, orig_c in cols_lower.items():
                if cand_f in k_low:
                    col_fecha = orig_c
                    break
            if col_fecha is not None:
                break
        if col_fecha is None:
            col_fecha = df.columns[0]

        # Caso 1: Archivo de Clapes UC (contiene PTF-A, PTF-B, PTF-C o PTF-D)
        mapa_clapes = {}
        for k_low, orig_c in cols_lower.items():
            if "ptf-a" in k_low or "ptf_a" in k_low or "ptfa" in k_low:
                mapa_clapes["PTF-A (Solow Tradicional)"] = orig_c
            elif "ptf-b" in k_low or "ptf_b" in k_low or "ptfb" in k_low:
                mapa_clapes["PTF-B (Ajustada por Empleo: Horas y Salarios)"] = orig_c
            elif "ptf-c" in k_low or "ptf_c" in k_low or "ptfc" in k_low:
                mapa_clapes["PTF-C (Ajustada por Uso del Capital)"] = orig_c
            elif "ptf-d" in k_low or "ptf_d" in k_low or "ptfd" in k_low:
                mapa_clapes["PTF-D (Ajustada por Empleo y Capital)"] = orig_c

        if len(mapa_clapes) >= 2:
            try:
                idx_dt = pd.to_datetime(df[col_fecha], errors="coerce")
                df_cl = pd.DataFrame(
                    {dest_col: pd.to_numeric(df[src_col], errors="coerce") for dest_col, src_col in mapa_clapes.items()},
                    index=idx_dt,
                )
                df_cl = df_cl[df_cl.index.notna()].dropna(how="all").sort_index()
                if not df_cl.empty:
                    out["ptf_clapes_importado"] = df_cl
            except Exception:
                pass

        # Caso 2: Archivo de CNEP (contiene PTF sin minería / no minera / PTF agregada / total)
        mapa_cnep = {}
        for k_low, orig_c in cols_lower.items():
            if ("sin miner" in k_low or "no miner" in k_low) and "ptf" in k_low:
                mapa_cnep["PTF Sin Minería / No Minera (CNEP)"] = orig_c
            elif ("total" in k_low or "agregada" in k_low) and "ptf" in k_low:
                mapa_cnep["PTF Total Agregada (CNEP)"] = orig_c
            elif "miner" in k_low and "ptf" in k_low and "sin" not in k_low and "no" not in k_low:
                mapa_cnep["PTF Minería (CNEP)"] = orig_c
            elif "servicio" in k_low and "capital" in k_low:
                mapa_cnep["Servicios de Capital (BDE BCCh)"] = orig_c

        if len(mapa_cnep) >= 1:
            try:
                s_f = df[col_fecha]
                if pd.api.types.is_numeric_dtype(s_f):
                    idx_a = pd.to_datetime(
                        [pd.Timestamp(year=int(y), month=1, day=1) for y in s_f if pd.notna(y) and 1980 <= int(y) <= 2100]
                    )
                    df_sub = df[s_f.notna() & (s_f >= 1980) & (s_f <= 2100)]
                else:
                    idx_a = pd.to_datetime(s_f, errors="coerce")
                    df_sub = df
                df_cn = pd.DataFrame(
                    {dest_col: pd.to_numeric(df_sub[src_col].values, errors="coerce") for dest_col, src_col in mapa_cnep.items()},
                    index=idx_a,
                )
                df_cn = df_cn[df_cn.index.notna()].dropna(how="all").sort_index()
                if not df_cn.empty:
                    out["ptf_cnep_importado"] = df_cn
            except Exception:
                pass

    return out



