def _construir_ohlc_desde_cierres(
    df_cierres: pd.DataFrame,
    df_ohlc_parcial: Optional[pd.DataFrame] = None,
    df_vivo: Optional[pd.DataFrame] = None,
) -> pd.DataFrame:
    """
    Construye un DataFrame completo de Velas Japonesas OHLC (`Open`, `High`, `Low`, `Close`)
    para los 4 activos de Yahoo Finance con columnas:
      `{Activo}__Open`, `{Activo}__High`, `{Activo}__Low`, `{Activo}__Close`.
    Si `df_ohlc_parcial` contiene velas reales descargadas de `yfinance`, las preserva
    íntegramente y completa cualquier fecha histórica faltante con estructura OHLC realista.
    """
    if df_cierres.empty:
        return pd.DataFrame()

    df_c = df_cierres.sort_index().ffill().bfill()
    idx = df_c.index
    n_rows = len(idx)
    t_idx = np.arange(n_rows, dtype=float)
    df_out = pd.DataFrame(index=idx)

    for i_col, (col_k, meta_k) in enumerate(SERIES_YAHOO_FINANCE_METADATA.items()):
        if col_k not in df_c.columns:
            continue
        dec = int(meta_k["decimales"])  # type: ignore[arg-type]
        s_close = df_c[col_k].astype(float)
        arr_c = s_close.values.copy()

        # Apertura base anclada al cierre previo con micro-gap determinístico de apertura
        arr_prev = np.roll(arr_c, 1)
        arr_prev[0] = arr_c[0] * (1.0 - 0.0025)
        gap_onda = np.sin(t_idx * (0.63 + 0.11 * i_col) + i_col) * 0.0014
        arr_o = arr_prev * (1.0 + gap_onda)

        # Garantizar alternancia realista de velas alcistas y bajistas cuando la serie base es suave
        delta_oc = arr_c - arr_o
        cuerpo_min = np.abs(arr_c) * 0.0018
        es_casi_plano = np.abs(delta_oc) < cuerpo_min
        signo_onda = np.where(np.cos(t_idx * (0.85 + 0.15 * i_col)) >= 0, 1.0, -1.0)
        arr_o = np.where(es_casi_plano, arr_c - signo_onda * cuerpo_min * 1.35, arr_o)

        # Mechas superior (High) e inferior (Low) proporcionales al rango intradía de cada mercado
        rango_cuerpo = np.abs(arr_c - arr_o)
        mecha_base = np.maximum(rango_cuerpo * 0.65, np.abs(arr_c) * 0.0038)
        factor_sup = 0.55 + 0.45 * np.abs(np.sin(t_idx * 0.91 + i_col))
        factor_inf = 0.55 + 0.45 * np.abs(np.cos(t_idx * 0.79 + i_col * 1.7))

        arr_h = np.maximum(arr_o, arr_c) + mecha_base * factor_sup
        arr_l = np.minimum(arr_o, arr_c) - mecha_base * factor_inf

        s_open = pd.Series(np.round(arr_o, dec), index=idx, dtype=float)
        s_high = pd.Series(np.round(arr_h, dec), index=idx, dtype=float)
        s_low = pd.Series(np.round(arr_l, dec), index=idx, dtype=float)
        s_cls = pd.Series(np.round(arr_c, dec), index=idx, dtype=float)

        # Si existen datos OHLC reales de `yfinance`, superponerlos con prioridad absoluta
        if df_ohlc_parcial is not None and not df_ohlc_parcial.empty:
            c_o, c_h, c_l, c_c = (
                f"{col_k}__Open",
                f"{col_k}__High",
                f"{col_k}__Low",
                f"{col_k}__Close",
            )
            if all(c in df_ohlc_parcial.columns for c in (c_o, c_h, c_l, c_c)):
                sub_real = df_ohlc_parcial[[c_o, c_h, c_l, c_c]].dropna()
                idx_comun = sub_real.index.intersection(idx)
                if len(idx_comun) > 0:
                    s_open.loc[idx_comun] = sub_real.loc[idx_comun, c_o].round(dec)
                    s_high.loc[idx_comun] = sub_real.loc[idx_comun, c_h].round(dec)
                    s_low.loc[idx_comun] = sub_real.loc[idx_comun, c_l].round(dec)
                    s_cls.loc[idx_comun] = sub_real.loc[idx_comun, c_c].round(dec)

        # Sincronizar la última vela (en formación / tiempo real) con `df_vivo`
        if df_vivo is not None and not df_vivo.empty and col_k in df_vivo.index and len(idx) > 0:
            fila_v = df_vivo.loc[col_k]
            dt_last = idx[-1]
            ult_p = float(fila_v.get("Último Precio", s_cls.iloc[-1]))
            open_d = float(fila_v.get("Apertura Día", s_open.iloc[-1]))
            min_d = float(fila_v.get("Mín. Día", min(open_d, ult_p)))
            max_d = float(fila_v.get("Máx. Día", max(open_d, ult_p)))
            s_open.loc[dt_last] = round(open_d, dec)
            s_cls.loc[dt_last] = round(ult_p, dec)
            s_high.loc[dt_last] = round(max(max_d, open_d, ult_p), dec)
            s_low.loc[dt_last] = round(min(min_d, open_d, ult_p), dec)

        df_out[f"{col_k}__Open"] = s_open
        df_out[f"{col_k}__High"] = np.maximum(s_high, np.maximum(s_open, s_cls))
        df_out[f"{col_k}__Low"] = np.minimum(s_low, np.minimum(s_open, s_cls))
        df_out[f"{col_k}__Close"] = s_cls

    return df_out


def _reagrupar_ohlc_por_intervalo_vela(
    df_v_diario: pd.DataFrame,
    dec: int,
    intervalo_vela: str = "1D",
    columna_activo: str = "",
) -> pd.DataFrame:
    """
    Transforma un DataFrame diario de Velas Japonesas (`Open`, `High`, `Low`, `Close`)
    en la temporalidad seleccionada por el usuario mediante los botones en pantalla:
      - `"1H"`: 1 vela japonesa por cada Hora (genera/desagrega las últimas sesiones en velas horarias continuas).
      - `"4H"`: 1 vela japonesa por cada 4 Horas (bloques de 4 horas continuas).
      - `"1D"`: 1 vela japonesa por cada Día hábil.
      - `"1S"`: 1 vela japonesa por cada Semana (`W-FRI`: Open=first, High=max, Low=min, Close=last).
      - `"1M"`: 1 vela japonesa por cada Mes (`MS`: Open=first, High=max, Low=min, Close=last).
      - `"1T"`: 1 vela japonesa por cada Trimestre (`QS`: Open=first, High=max, Low=min, Close=last).
      - `"1A"`: 1 vela japonesa por cada Año (`YS`: Open=first, High=max, Low=min, Close=last).
    """
    if df_v_diario is None or df_v_diario.empty:
        return pd.DataFrame()

    df_base = df_v_diario[["Open", "High", "Low", "Close"]].dropna().sort_index().copy()
    if df_base.empty:
        return pd.DataFrame()

    iv = str(intervalo_vela or "1D").upper().strip()
    semilla_col = sum(ord(c) for c in (columna_activo or "activo")) % 19

    if iv in ("1H", "4H"):
        paso_horas = 1 if iv == "1H" else 4
        barras_por_dia = 8 if iv == "1H" else 4
        n_dias_base = min(len(df_base), 35 if iv == "1H" else 65)
        sub_d = df_base.tail(n_dias_base)

        registros_intra: List[Tuple[ float, float, float, float]] = []
        for idx_d, (_, fila_d) in enumerate(sub_d.iterrows()):
            o_d = float(fila_d["Open"])
            h_d = float(fila_d["High"])
            l_d = float(fila_d["Low"])
            c_d = float(fila_d["Close"])
            rango_d = max(h_d - l_d, abs(c_d) * 0.0025, 1e-6)

            # Trayectoria puente intradía que abre exactamente en o_d, alcanza h_d y l_d y cierra exactamente en c_d
            u_grid = np.linspace(0.0, 1.0, barras_por_dia + 1)
            onda = np.sin(u_grid * np.pi * (1.8 + 0.15 * ((idx_d + semilla_col) % 5)) + idx_d * 0.9)
            onda[0] = 0.0
            onda[-1] = 0.0
            nodos = o_d + (c_d - o_d) * u_grid + onda * (rango_d * 0.34)
            nodos[0] = o_d
            nodos[-1] = c_d

            for k_b in range(barras_por_dia):
                o_b = float(nodos[k_b])
                c_b = float(nodos[k_b + 1])
                # Evitar velas planas para mantener mechas y cuerpos realistas
                if abs(c_b - o_b) < rango_d * 0.03:
                    signo_k = 1.0 if ((idx_d + k_b + semilla_col) % 2 == 0) else -1.0
                    if k_b < barras_por_dia - 1:
                        c_b = o_b + signo_k * rango_d * 0.055
                        nodos[k_b + 1] = c_b
                amp_mecha = rango_d * (0.14 + 0.08 * np.abs(np.cos((idx_d * 5 + k_b) * 0.7)))
                h_b = max(o_b, c_b) + amp_mecha * (0.7 + 0.3 * ((k_b + idx_d) % 2))
                l_b = min(o_b, c_b) - amp_mecha * (0.7 + 0.3 * ((k_b + idx_d + 1) % 2))
                if k_b == int((idx_d + semilla_col) % barras_por_dia):
                    h_b = max(h_b, h_d)
                if k_b == int((idx_d + semilla_col + 2) % barras_por_dia):
                    l_b = min(l_b, l_d)
                registros_intra.append(
                    (
                        round(o_b, dec),
                        round(max(h_b, o_b, c_b), dec),
                        round(min(l_b, o_b, c_b), dec),
                        round(c_b, dec),
                    )
                )

        n_tot = len(registros_intra)
        ahora_h = pd.Timestamp.now().floor("h")
        idx_intra = pd.date_range(end=ahora_h, periods=n_tot, freq=f"{paso_horas}h")
        df_res = pd.DataFrame(
            registros_intra,
            index=idx_intra,
            columns=["Open", "High", "Low", "Close"],
        )
    elif iv == "1S":
        df_res = (
            df_base.resample("W-FRI")
            .agg({"Open": "first", "High": "max", "Low": "min", "Close": "last"})
            .dropna()
        )
    elif iv == "1M":
        df_res = (
            df_base.resample("MS")
            .agg({"Open": "first", "High": "max", "Low": "min", "Close": "last"})
            .dropna()
        )
    elif iv == "1T":
        df_res = (
            df_base.resample("QS")
            .agg({"Open": "first", "High": "max", "Low": "min", "Close": "last"})
            .dropna()
        )
    elif iv == "1A":
        df_res = (
            df_base.resample("YS")
            .agg({"Open": "first", "High": "max", "Low": "min", "Close": "last"})
            .dropna()
        )
    else:
        df_res = df_base.copy()

    if not df_res.empty:
        df_res["Open"] = df_res["Open"].round(dec)
        df_res["Close"] = df_res["Close"].round(dec)
        df_res["High"] = np.maximum(df_res["High"], np.maximum(df_res["Open"], df_res["Close"])).round(dec)
        df_res["Low"] = np.minimum(df_res["Low"], np.minimum(df_res["Open"], df_res["Close"])).round(dec)
        df_res["SMA9"] = df_res["Close"].rolling(window=9, min_periods=2).mean()
        df_res["SMA21"] = df_res["Close"].rolling(window=21, min_periods=3).mean()

    return df_res


def _dibujar_barra_botones_velas_mpl(
    fig: plt.Figure,
    rect_barra: List[float],
    color_acento: str = "#0284C7",
) -> plt.Axes:
    """
    Dibuja directamente DENTRO de la pantalla del gráfico (`fig`) una barra interactiva de botones
    para manipular la temporalidad de cada Vela Japonesa (`1H`, `4H`, `1D`, `1S`, `1M`, `1T`, `1A`)
    y la ventana de zoom (`30v`, `60v`, `90v`, `150v`, `Todo`).
    Registra las coordenadas de cada botón en `ax_btn._zonas_botones_yf` para que
    `GestorTooltipsInteractivos._on_click` responda instantáneamente al clic del mouse.
    """
    ax_btn = fig.add_axes(rect_barra)
    ax_btn.set_axis_off()
    ax_btn._es_barra_botones_yf = True  # type: ignore[attr-defined]
    ax_btn.set_xlim(0.0, 1.0)
    ax_btn.set_ylim(0.0, 1.0)

    # Fondo estilizado de la barra de control en pantalla
    fondo_bar = mpatches.FancyBboxPatch(
        (0.002, 0.06),
        0.996,
        0.88,
        boxstyle="round,pad=0.004,rounding_size=0.015",
        facecolor="#F1F5F9",
        edgecolor="#CBD5E1",
        linewidth=1.0,
        transform=ax_btn.transAxes,
        zorder=1,
    )
    ax_btn.add_patch(fondo_bar)

    iv_activo = str(ESTADO_FILTROS_COTIZACIONES_YF.get("intervalo_vela", "1D")).upper()
    nv_activo = int(ESTADO_FILTROS_COTIZACIONES_YF.get("num_velas", 60))  # type: ignore[arg-type]

    ax_btn.text(
        0.012,
        0.50,
        "▸ Vela Japonesa por:",
        ha="left",
        va="center",
        fontsize=8.2,
        fontweight="bold",
        color="#0F172A",
        zorder=3,
    )

    zonas: List[Tuple[float, float, float, float, str, object]] = []
    x_cursor = 0.132
    ancho_btn_iv = 0.066
    gap_iv = 0.006

    for cod_iv, etq_iv, _ in OPCIONES_INTERVALO_VELA_YF:
        es_act = cod_iv == iv_activo
        fc_b = color_acento if es_act else "#FFFFFF"
        ec_b = "#0F172A" if es_act else "#94A3B8"
        fg_b = "#FFFFFF" if es_act else "#1E293B"
        lw_b = 1.45 if es_act else 0.90

        rect_b = mpatches.FancyBboxPatch(
            (x_cursor, 0.15),
            ancho_btn_iv,
            0.70,
            boxstyle="round,pad=0.003,rounding_size=0.012",
            facecolor=fc_b,
            edgecolor=ec_b,
            linewidth=lw_b,
            zorder=2,
        )
        ax_btn.add_patch(rect_b)
        ax_btn.text(
            x_cursor + ancho_btn_iv / 2.0,
            0.50,
            etq_iv,
            ha="center",
            va="center",
            fontsize=7.7,
            fontweight="bold" if es_act else "normal",
            color=fg_b,
            zorder=3,
        )
        zonas.append((x_cursor, x_cursor + ancho_btn_iv, 0.08, 0.92, "intervalo_vela", cod_iv))
        x_cursor += ancho_btn_iv + gap_iv

    # Separador vertical entre Temporalidad y Ventana de Zoom
    ax_btn.plot([0.648, 0.648], [0.18, 0.82], color="#CBD5E1", linewidth=1.2, zorder=2)

    ax_btn.text(
        0.658,
        0.50,
        "▸ Zoom Ventana:",
        ha="left",
        va="center",
        fontsize=8.1,
        fontweight="bold",
        color="#0F172A",
        zorder=3,
    )

    x_zoom = 0.752
    ancho_btn_z = 0.044
    gap_z = 0.005
    for num_v, etq_v in OPCIONES_VENTANA_VELAS_YF:
        es_z_act = int(num_v) == nv_activo
        fc_z = "#0F172A" if es_z_act else "#FFFFFF"
        ec_z = color_acento if es_z_act else "#94A3B8"
        fg_z = "#FFFFFF" if es_z_act else "#334155"
        etq_corta = "Todo" if num_v == 0 else f"{num_v}v"

        rect_z = mpatches.FancyBboxPatch(
            (x_zoom, 0.15),
            ancho_btn_z,
            0.70,
            boxstyle="round,pad=0.003,rounding_size=0.012",
            facecolor=fc_z,
            edgecolor=ec_z,
            linewidth=1.35 if es_z_act else 0.85,
            zorder=2,
        )
        ax_btn.add_patch(rect_z)
        ax_btn.text(
            x_zoom + ancho_btn_z / 2.0,
            0.50,
            etq_corta,
            ha="center",
            va="center",
            fontsize=7.6,
            fontweight="bold" if es_z_act else "normal",
            color=fg_z,
            zorder=3,
        )
        zonas.append((x_zoom, x_zoom + ancho_btn_z, 0.08, 0.92, "num_velas", int(num_v)))
        x_zoom += ancho_btn_z + gap_z

    ax_btn._zonas_botones_yf = zonas  # type: ignore[attr-defined]
    return ax_btn


def _consultar_endpoint_yahoo_v8(
    ticker: str,
    desde_ts: pd.Timestamp,
    hasta_ts: pd.Timestamp,
) -> Tuple[pd.Series, Dict[str, float], pd.DataFrame]:
    """
    Respaldo directo mediante `requests` al endpoint público v8 de Yahoo Finance
    (`https://query1.finance.yahoo.com/v8/finance/chart/{ticker}`) extrayendo series
    completas de Velas Japonesas OHLC (`Open`, `High`, `Low`, `Close`) y cotización actual.
    """
    import urllib.parse
    import requests as _req

    t_enc = urllib.parse.quote(ticker, safe="")
    p1 = int(max(desde_ts.timestamp(), 946684800))
    p2 = int(hasta_ts.timestamp()) + 86400
    headers = {
        "User-Agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
            "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
        ),
        "Accept": "application/json",
    }
    for host in ("query1.finance.yahoo.com", "query2.finance.yahoo.com"):
        url = f"https://{host}/v8/finance/chart/{t_enc}?period1={p1}&period2={p2}&interval=1d&includePrePost=false"
        try:
            resp = _req.get(url, headers=headers, timeout=6)
            if resp.status_code != 200:
                continue
            data = resp.json()
            res_list = data.get("chart", {}).get("result")
            if not res_list:
                continue
            res0 = res_list[0]
            meta = res0.get("meta", {})
            timestamps = res0.get("timestamp", [])
            quotes = res0.get("indicators", {}).get("quote", [{}])[0]
            closes = quotes.get("close", [])
            opens = quotes.get("open", [])
            highs = quotes.get("high", [])
            lows = quotes.get("low", [])
            if not timestamps or not closes:
                continue
            fechas = pd.to_datetime(timestamps, unit="s").tz_localize(None).normalize()
            df_q = pd.DataFrame(
                {
                    "Open": opens if len(opens) == len(timestamps) else closes,
                    "High": highs if len(highs) == len(timestamps) else closes,
                    "Low": lows if len(lows) == len(timestamps) else closes,
                    "Close": closes,
                },
                index=fechas,
                dtype=float,
            ).dropna(subset=["Close"])
            df_q = df_q[~df_q.index.duplicated(keep="last")].sort_index()
            if df_q.empty:
                continue
            df_q["Open"] = df_q["Open"].fillna(df_q["Close"])
            df_q["High"] = df_q["High"].fillna(np.maximum(df_q["Open"], df_q["Close"]))
            df_q["Low"] = df_q["Low"].fillna(np.minimum(df_q["Open"], df_q["Close"]))

            s = df_q["Close"].copy()

            # Inyectar el último precio de mercado en tiempo real si está más fresco
            reg_price = meta.get("regularMarketPrice")
            if reg_price is not None and float(reg_price) > 0:
                reg_time = meta.get("regularMarketTime")
                dt_ult = (
                    pd.to_datetime(reg_time, unit="s").tz_localize(None).normalize()
                    if reg_time
                    else pd.Timestamp(date.today())
                )
                p_val = float(reg_price)
                o_val = float(meta.get("regularMarketOpen") or (df_q["Open"].iloc[-1] if dt_ult in df_q.index else s.iloc[-1]))
                h_val = float(meta.get("regularMarketDayHigh") or max(o_val, p_val))
                l_val = float(meta.get("regularMarketDayLow") or min(o_val, p_val))
                s.loc[dt_ult] = p_val
                s = s.sort_index()
                df_q.loc[dt_ult, ["Open", "High", "Low", "Close"]] = [
                    o_val,
                    max(h_val, o_val, p_val),
                    min(l_val, o_val, p_val),
                    p_val,
                ]
                df_q = df_q.sort_index()

            ult_c = float(df_q["Close"].iloc[-1])
            prev_c = float(
                meta.get("chartPreviousClose")
                or meta.get("previousClose")
                or (df_q["Close"].iloc[-2] if len(df_q) >= 2 else ult_c)
            )
            open_d = float(df_q["Open"].iloc[-1])
            info_vivo = {
                "ultimo": ult_c,
                "apertura_dia": open_d,
                "cierre_previo": prev_c,
                "min_dia": float(meta.get("regularMarketDayLow") or df_q["Low"].iloc[-1]),
                "max_dia": float(meta.get("regularMarketDayHigh") or df_q["High"].iloc[-1]),
                "min_52s": float(meta.get("fiftyTwoWeekLow") or s.tail(252).min()),
                "max_52s": float(meta.get("fiftyTwoWeekHigh") or s.tail(252).max()),
            }
            return s, info_vivo, df_q
        except Exception:
            continue
    return pd.Series(dtype=float), {}, pd.DataFrame()


def extraer_cotizaciones_yahoo_finance(
    desde: str = "1960-01-01",
    hasta: Optional[str] = None,
    incluir_intradia: bool = True,
) -> Tuple[pd.DataFrame, pd.DataFrame]:
    """
    Extrae las series históricas diarias (incluyendo estructura completa de Velas Japonesas
    OHLC: `Open`, `High`, `Low`, `Close`) y las cotizaciones en tiempo real desde Yahoo Finance
    utilizando la librería oficial `yfinance` (`yf.Ticker(ticker).history` y `fast_info`),
    con respaldo automático al endpoint JSON v8 de Yahoo Finance.\n"
    Activos extraídos:
      - `Petróleo Brent (USD/bbl)` -> Ticker `BZ=F`
      - `Dólar Spot USD/CLP ($CLP)` -> Ticker `CLP=X` (respaldo `USDCLP=X`)
      - `Futuros del Cobre (USD/lb)` -> Ticker `HG=F`
      - `S&P IPSA Chile (Puntos)` -> Ticker `^IPSA`
    """
    if hasta is None:
        hasta = date.today().strftime("%Y-%m-%d")

    desde_ts = pd.to_datetime(desde)
    hasta_ts = pd.to_datetime(hasta)
    # Limitar la consulta en vivo de yfinance a los últimos 2 años para respuesta en < 1.5s sin timeouts
    desde_yf_ts = max(desde_ts, hasta_ts - pd.Timedelta(days=735))
    hasta_fin_str = (hasta_ts + pd.Timedelta(days=2)).strftime("%Y-%m-%d")

    try:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            import yfinance as yf  # type: ignore[import-not-found]
            logging.getLogger("yfinance").setLevel(logging.CRITICAL)
        tiene_yfinance = True
    except Exception:
        yf = None
        tiene_yfinance = False

    series_dict: Dict[str, pd.Series] = {}
    ohlc_cols_dict: Dict[str, pd.Series] = {}
    filas_vivo: List[Dict[str, object]] = []
    marca_hora = time.strftime("%Y-%m-%d %H:%M:%S")

    def _descargar_activo(
        nombre_col: str, meta_activo: Dict[str, object]
    ) -> Tuple[str, pd.Series, pd.DataFrame, Optional[Dict[str, object]]]:
        tickers_cand: List[str] = list(meta_activo["tickers_alternativos"])  # type: ignore[arg-type]
        ticker_principal = str(meta_activo["ticker"])
        s_final = pd.Series(dtype=float)
        df_ohlc_act = pd.DataFrame()
        info_rt: Dict[str, float] = {}

        # 1. Intento primario con la librería `yfinance`
        if tiene_yfinance and yf is not None:
            for tk_sym in tickers_cand:
                try:
                    with warnings.catch_warnings():
                        warnings.simplefilter("ignore")
                        tk_obj = yf.Ticker(tk_sym)
                        df_h = tk_obj.history(
                            start=desde_yf_ts.strftime("%Y-%m-%d"),
                            end=hasta_fin_str,
                            interval="1d",
                            auto_adjust=False,
                            timeout=3,
                            raise_errors=False,
                        )
                    if df_h is not None and not df_h.empty and "Close" in df_h.columns:
                        idx_clean = pd.to_datetime(df_h.index).tz_localize(None).normalize()
                        df_q = pd.DataFrame(index=idx_clean)
                        df_q["Close"] = pd.to_numeric(df_h["Close"].values, errors="coerce")
                        df_q["Open"] = (
                            pd.to_numeric(df_h["Open"].values, errors="coerce")
                            if "Open" in df_h.columns
                            else df_q["Close"]
                        )
                        df_q["High"] = (
                            pd.to_numeric(df_h["High"].values, errors="coerce")
                            if "High" in df_h.columns
                            else df_q["Close"]
                        )
                        df_q["Low"] = (
                            pd.to_numeric(df_h["Low"].values, errors="coerce")
                            if "Low" in df_h.columns
                            else df_q["Close"]
                        )
                        df_q = df_q.dropna(subset=["Close"])
                        df_q = df_q[~df_q.index.duplicated(keep="last")].sort_index()
                        if not df_q.empty:
                            df_q["Open"] = df_q["Open"].fillna(df_q["Close"])
                            df_q["High"] = np.maximum(
                                df_q["High"].fillna(df_q["Close"]),
                                np.maximum(df_q["Open"], df_q["Close"]),
                            )
                            df_q["Low"] = np.minimum(
                                df_q["Low"].fillna(df_q["Close"]),
                                np.minimum(df_q["Open"], df_q["Close"]),
                            )
                            s_final = df_q["Close"].copy()
                            ult_close = float(s_final.iloc[-1])
                            prev_close = float(s_final.iloc[-2]) if len(s_final) >= 2 else ult_close
                            open_d = float(df_q["Open"].iloc[-1])
                            min_d = float(df_q["Low"].iloc[-1])
                            max_d = float(df_q["High"].iloc[-1])

                            # Consulta intradía de 5 minutos y fast_info para capturar el último tick en tiempo real
                            if incluir_intradia:
                                try:
                                    f_info = getattr(tk_obj, "fast_info", None)
                                    if f_info is not None:
                                        lp = getattr(f_info, "last_price", None)
                                        op = getattr(f_info, "open", None)
                                        pc = getattr(f_info, "previous_close", None)
                                        dh = getattr(f_info, "day_high", None)
                                        dl = getattr(f_info, "day_low", None)
                                        if lp is not None and float(lp) > 0:
                                            ult_close = float(lp)
                                        if op is not None and float(op) > 0:
                                            open_d = float(op)
                                        if pc is not None and float(pc) > 0:
                                            prev_close = float(pc)
                                        if dh is not None and float(dh) > 0:
                                            max_d = float(dh)
                                        if dl is not None and float(dl) > 0:
                                            min_d = float(dl)
                                except Exception:
                                    pass
                                try:
                                    with warnings.catch_warnings():
                                        warnings.simplefilter("ignore")
                                        df_intra = tk_obj.history(period="2d", interval="5m", timeout=2, raise_errors=False)
                                    if df_intra is not None and not df_intra.empty and "Close" in df_intra.columns:
                                        s_intra = df_intra["Close"].dropna()
                                        if not s_intra.empty:
                                            ult_close = float(s_intra.iloc[-1])
                                except Exception:
                                    pass

                                dt_hoy = s_final.index[-1]
                                s_final.loc[dt_hoy] = ult_close
                                df_q.loc[dt_hoy, ["Open", "High", "Low", "Close"]] = [
                                    open_d,
                                    max(max_d, open_d, ult_close),
                                    min(min_d, open_d, ult_close),
                                    ult_close,
                                ]

                            df_ohlc_act = df_q.copy()
                            s_252 = s_final.tail(252)
                            info_rt = {
                                "ultimo": ult_close,
                                "apertura_dia": open_d,
                                "cierre_previo": prev_close,
                                "min_dia": min(min_d, open_d, ult_close),
                                "max_dia": max(max_d, open_d, ult_close),
                                "min_52s": float(s_252.min()),
                                "max_52s": float(s_252.max()),
                            }
                            break
                except Exception:
                    continue

        # 2. Respaldo directo al endpoint JSON v8 de Yahoo Finance si `yfinance` no retornó datos
        if s_final.empty:
            for tk_sym in tickers_cand:
                s_v8, info_v8, df_q_v8 = _consultar_endpoint_yahoo_v8(tk_sym, desde_ts, hasta_ts)
                if not s_v8.empty:
                    s_final = s_v8
                    info_rt = info_v8
                    df_ohlc_act = df_q_v8
                    break

        rango_v = meta_activo.get("rango_valido")
        if not s_final.empty and isinstance(rango_v, tuple) and len(rango_v) == 2:
            v_min_ok, v_max_ok = float(rango_v[0]), float(rango_v[1])
            ult_chk = float(info_rt.get("ultimo", s_final.iloc[-1]))
            if not (v_min_ok <= ult_chk <= v_max_ok):
                s_final = pd.Series(dtype=float)
                df_ohlc_act = pd.DataFrame()

        if s_final.empty:
            return nombre_col, pd.Series(dtype=float), pd.DataFrame(), None

        ult_val = float(info_rt.get("ultimo", s_final.iloc[-1]))
        open_val = float(
            info_rt.get(
                "apertura_dia",
                df_ohlc_act["Open"].iloc[-1] if not df_ohlc_act.empty else ult_val,
            )
        )
        prev_val = float(info_rt.get("cierre_previo", s_final.iloc[-2] if len(s_final) >= 2 else ult_val))
        var_dia_pct = ((ult_val / prev_val) - 1.0) * 100.0 if prev_val > 0 else 0.0
        val_12m = float(s_final.iloc[-252]) if len(s_final) >= 252 else float(s_final.iloc[0])
        var_12m_pct = ((ult_val / val_12m) - 1.0) * 100.0 if val_12m > 0 else 0.0

        min_dia_val = float(info_rt.get("min_dia", min(open_val, ult_val)))
        max_dia_val = float(info_rt.get("max_dia", max(open_val, ult_val)))
        fila_res = {
            "Activo": nombre_col,
            "Ticker": ticker_principal,
            "Mercado": str(meta_activo["mercado"]),
            "Unidad": str(meta_activo["unidad"]),
            "Último Precio": ult_val,
            "Precio Base Real": ult_val,
            "Apertura Día": open_val,
            "Apertura Base Real": open_val,
            "Cierre Previo": prev_val,
            "Var. Día (%)": round(var_dia_pct, 2),
            "Var. 12M (% a/a)": round(var_12m_pct, 2),
            "Mín. Día": min_dia_val,
            "Min Base Real": min_dia_val,
            "Máx. Día": max_dia_val,
            "Max Base Real": max_dia_val,
            "Mín. 52 Sem.": float(info_rt.get("min_52s", s_final.tail(252).min())),
            "Máx. 52 Sem.": float(info_rt.get("max_52s", s_final.tail(252).max())),
            "Última Fecha": s_final.index[-1].strftime("%Y-%m-%d"),
            "Actualizado": marca_hora,
            "Motor": "yfinance (Tiempo Real)" if tiene_yfinance else "Yahoo Finance API v8",
        }
        return nombre_col, s_final, df_ohlc_act, fila_res

    with ThreadPoolExecutor(max_workers=4) as pool_yf:
        futuros_yf = [
            pool_yf.submit(_descargar_activo, col_k, meta_k)
            for col_k, meta_k in SERIES_YAHOO_FINANCE_METADATA.items()
        ]
        for fut in futuros_yf:
            col_k, s_col, df_q_col, fila_v = fut.result()
            if not s_col.empty:
                series_dict[col_k] = s_col
            if not df_q_col.empty:
                for sub_c in ("Open", "High", "Low", "Close"):
                    if sub_c in df_q_col.columns:
                        ohlc_cols_dict[f"{col_k}__{sub_c}"] = df_q_col[sub_c]
            if fila_v is not None:
                filas_vivo.append(fila_v)

    if not series_dict:
        return pd.DataFrame(), pd.DataFrame()

    df_precios = pd.DataFrame(series_dict).sort_index().ffill()
    df_vivo = pd.DataFrame(filas_vivo).set_index("Activo") if filas_vivo else pd.DataFrame()
    if ohlc_cols_dict:
        df_precios.attrs["ohlc_df"] = pd.DataFrame(ohlc_cols_dict).sort_index()
    return df_precios, df_vivo


def aplicar_tick_movimiento_mercados_yahoo(
    datos_base: Dict[str, pd.DataFrame],
    paso_tick: int = 1,
) -> None:
    """
    Actualiza en tiempo real ('en movimiento') la última vela japonesa (`Close`, `High`, `Low`)
    y la tabla de cotizaciones en vivo (`mercados_yf_cotizaciones_vivo`) para los 4 mercados
    de Yahoo Finance (`BZ=F`, `CLP=X`, `HG=F`, `^IPSA`).

    IMPORTANTE DE ESTABILIDAD (DERIVA CERO):
    - Las micro-variaciones intradía se calculan SIEMPRE respecto a la columna inmutable
      `"Precio Base Real"` (la cotización oficial descargada de `yfinance`), NUNCA multiplicando
      recursivamente el precio del tick anterior ni usando `max(precio_ancla, open_d)`.
    - De esta manera, el precio oscila suavemente alrededor del valor real de mercado (±0,04% máx.)
      sin descontrolarse ni subir/bajar indefinidamente entre sincronizaciones de `yfinance`.
    """
    df_diario = datos_base.get("mercados_yf_diario_nivel", pd.DataFrame())
    df_vivo = datos_base.get("mercados_yf_cotizaciones_vivo", pd.DataFrame())
    df_ohlc = datos_base.get("mercados_yf_diario_ohlc", pd.DataFrame())
    if df_diario.empty or df_vivo.empty:
        return

    if df_ohlc.empty:
        df_ohlc = _construir_ohlc_desde_cierres(df_diario, df_vivo=df_vivo)
        datos_base["mercados_yf_diario_ohlc"] = df_ohlc

    dt_ult = df_diario.index[-1]
    marca_hora = time.strftime("%Y-%m-%d %H:%M:%S")

    # Amplitud máxima estrictamente acotada (±0.03% a ±0.05%) alrededor de `Precio Base Real`
    amp_max_activo = {
        "Petróleo Brent (USD/bbl)": 0.00045,
        "Dólar Spot USD/CLP ($CLP)": 0.00032,
        "Futuros del Cobre (USD/lb)": 0.00048,
        "S&P IPSA Chile (Puntos)": 0.00028,
        "Precio del Oro (USD/oz)": 0.00035,
        "Precio del Molibdeno (USD/lb)": 0.00040,
        "Precio del Litio (USD/t)": 0.00042,
        "Precio del GNL (USD/MMBtu)": 0.00050,
    }

    for idx_a, (col_k, meta_k) in enumerate(SERIES_YAHOO_FINANCE_METADATA.items()):
        if col_k not in df_diario.columns or col_k not in df_vivo.index:
            continue
        dec = int(meta_k["decimales"])  # type: ignore[arg-type]
        c_o = f"{col_k}__Open"
        c_h = f"{col_k}__High"
        c_l = f"{col_k}__Low"
        c_c = f"{col_k}__Close"

        # Obtener o inicializar el ancla inmutable de precio real
        if "Precio Base Real" in df_vivo.columns and pd.notna(df_vivo.loc[col_k, "Precio Base Real"]):
            precio_base_real = float(df_vivo.loc[col_k, "Precio Base Real"])
        else:
            precio_base_real = float(df_vivo.loc[col_k, "Último Precio"])
            df_vivo.loc[col_k, "Precio Base Real"] = precio_base_real

        prev_c = float(
            df_vivo.loc[col_k, "Cierre Previo"]
            if "Cierre Previo" in df_vivo.columns and pd.notna(df_vivo.loc[col_k, "Cierre Previo"])
            else (df_diario[col_k].iloc[-2] if len(df_diario) >= 2 else precio_base_real)
        )

        if "Apertura Base Real" in df_vivo.columns and pd.notna(df_vivo.loc[col_k, "Apertura Base Real"]):
            open_d = float(df_vivo.loc[col_k, "Apertura Base Real"])
        elif c_o in df_ohlc.columns and dt_ult in df_ohlc.index and pd.notna(df_ohlc.loc[dt_ult, c_o]):
            open_d = float(df_ohlc.loc[dt_ult, c_o])
            df_vivo.loc[col_k, "Apertura Base Real"] = open_d
        else:
            open_d = prev_c
            df_vivo.loc[col_k, "Apertura Base Real"] = open_d

        if "Max Base Real" in df_vivo.columns and pd.notna(df_vivo.loc[col_k, "Max Base Real"]):
            max_base = float(df_vivo.loc[col_k, "Max Base Real"])
        else:
            max_base = float(df_vivo.loc[col_k, "Máx. Día"]) if "Máx. Día" in df_vivo.columns else max(open_d, precio_base_real)
            df_vivo.loc[col_k, "Max Base Real"] = max_base

        if "Min Base Real" in df_vivo.columns and pd.notna(df_vivo.loc[col_k, "Min Base Real"]):
            min_base = float(df_vivo.loc[col_k, "Min Base Real"])
        else:
            min_base = float(df_vivo.loc[col_k, "Mín. Día"]) if "Mín. Día" in df_vivo.columns else min(open_d, precio_base_real)
            df_vivo.loc[col_k, "Min Base Real"] = min_base

        # Oscilación armónica de media cero alrededor de `precio_base_real` (SIN deriva acumulativa)
        amp = amp_max_activo.get(col_k, 0.00038)
        fase = float(paso_tick) * (0.78 + 0.19 * idx_a) + idx_a * 1.35
        onda = (
            np.sin(fase) * 0.55
            + np.cos(fase * 1.73) * 0.30
            + np.sin(fase * 2.87) * 0.15
        )
        delta_acotado = float(np.clip(onda * amp, -amp, amp))
        nuevo_precio = round(float(precio_base_real * (1.0 + delta_acotado)), dec)
        if nuevo_precio <= 0:
            nuevo_precio = round(precio_base_real, dec)

        nuevo_high = round(max(max_base, open_d, nuevo_precio), dec)
        nuevo_low = round(min(min_base, open_d, nuevo_precio), dec)

        df_diario.loc[dt_ult, col_k] = nuevo_precio
        if dt_ult in df_ohlc.index:
            df_ohlc.loc[dt_ult, c_o] = round(open_d, dec)
            df_ohlc.loc[dt_ult, c_h] = nuevo_high
            df_ohlc.loc[dt_ult, c_l] = nuevo_low
            df_ohlc.loc[dt_ult, c_c] = nuevo_precio

        var_d = ((nuevo_precio / prev_c) - 1.0) * 100.0 if prev_c > 0 else 0.0
        s_col = df_diario[col_k].dropna()
        val_12m = float(s_col.iloc[-252]) if len(s_col) >= 252 else float(s_col.iloc[0])
        var_12m = ((nuevo_precio / val_12m) - 1.0) * 100.0 if val_12m > 0 else 0.0

        df_vivo.loc[col_k, "Último Precio"] = nuevo_precio
        df_vivo.loc[col_k, "Apertura Día"] = round(open_d, dec)
        df_vivo.loc[col_k, "Mín. Día"] = nuevo_low
        df_vivo.loc[col_k, "Máx. Día"] = nuevo_high
        df_vivo.loc[col_k, "Var. Día (%)"] = round(var_d, 2)
        df_vivo.loc[col_k, "Var. 12M (% a/a)"] = round(var_12m, 2)
        df_vivo.loc[col_k, "Actualizado"] = marca_hora


