# 4. MOTOR DE FILTRADO UNIVERSAL DE FECHAS Y CONVERSIÓN DE FRECUENCIAS
# =============================================================================

def calcular_variacion_acumulada_anual(df_indices: pd.DataFrame) -> pd.DataFrame:
    """
    Calcula de forma vectorizada para cada serie la variación porcentual acumulada
    en el año respecto al cierre del año inmediatamente anterior (diciembre o T4).
    """
    if df_indices.empty:
        return df_indices.copy()

    cierres_anuales = df_indices.groupby(df_indices.index.year).last()
    bases_previas = cierres_anuales.reindex(df_indices.index.year - 1)
    bases_previas.index = df_indices.index
    return ((df_indices / bases_previas) - 1.0) * 100.0


def _recortar_rango_fechas(
    df: pd.DataFrame,
    desde_ts: Optional[pd.Timestamp],
    hasta_ts: Optional[pd.Timestamp],
) -> pd.DataFrame:
    """Filtra un DataFrame con DatetimeIndex al intervalo [desde_ts, hasta_ts] mediante búsqueda binaria."""
    if df is None or df.empty:
        return pd.DataFrame() if df is None else df
    out = df if df.index.is_monotonic_increasing else df.sort_index()
    if desde_ts is not None and hasta_ts is not None:
        return out.loc[desde_ts:hasta_ts]
    if desde_ts is not None:
        return out.loc[desde_ts:]
    if hasta_ts is not None:
        return out.loc[:hasta_ts]
    return out


def _configurar_eje_fechas_dinamico(ax, index_fechas: Optional[pd.DatetimeIndex] = None) -> None:
    """
    Ajusta automáticamente el formato del eje X según la amplitud del rango de fechas
    filtrado por el usuario (soportando desde velas intradía por hora/4 horas y días
    hasta semanas, meses, trimestres y años sin superposición).
    """
    if index_fechas is not None and len(index_fechas) >= 2:
        delta_total = index_fechas.max() - index_fechas.min()
        horas_tot = delta_total.total_seconds() / 3600.0
        dias = delta_total.days
        if horas_tot <= 96:
            paso_h = max(2, int(horas_tot // 7))
            ax.xaxis.set_major_formatter(mdates.DateFormatter("%d-%b %H:%M"))
            ax.xaxis.set_major_locator(mdates.HourLocator(interval=paso_h))
            return
        elif dias <= 18:
            paso_d = max(1, int(max(dias, 1) // 6))
            ax.xaxis.set_major_formatter(mdates.DateFormatter("%d-%b %Hh"))
            ax.xaxis.set_major_locator(mdates.DayLocator(interval=paso_d))
            return
        elif dias <= 135:
            paso_d = max(4, int(dias // 7))
            ax.xaxis.set_major_formatter(mdates.DateFormatter("%Y-%m-%d"))
            ax.xaxis.set_major_locator(mdates.DayLocator(interval=paso_d))
            return
        elif dias <= 550:
            ax.xaxis.set_major_formatter(mdates.DateFormatter("%Y-%m"))
            ax.xaxis.set_major_locator(mdates.MonthLocator(interval=2))
            return
        elif dias <= 1460:
            ax.xaxis.set_major_formatter(mdates.DateFormatter("%Y-%m"))
            ax.xaxis.set_major_locator(mdates.MonthLocator(interval=6))
            return
        elif dias <= 3650:
            ax.xaxis.set_major_formatter(mdates.DateFormatter("%Y"))
            ax.xaxis.set_major_locator(mdates.YearLocator(1))
            return
        elif dias > 9000:
            ax.xaxis.set_major_formatter(mdates.DateFormatter("%Y"))
            ax.xaxis.set_major_locator(mdates.YearLocator(4))
            return

    ax.xaxis.set_major_formatter(mdates.DateFormatter("%Y"))
    ax.xaxis.set_major_locator(mdates.YearLocator(2))




