    ax3.set_ylabel("Contribución a Var. % a/a (pp)", fontsize=8.3, fontweight="bold")
    ax3.legend(
        loc="upper left",
        frameon=True,
        facecolor="white",
        framealpha=0.92,
        fontsize=6.5,
    )
    _agregar_pie_fuente_ax(
        ax3,
        "Fuente: Descomposición exacta Δ₁₂ln(IMACEC_{T+h}) = Δ₁₂z_{T+h} (ciclo SARIMA) + Δ₁₂X_{T+h}'β (días hábiles, feriados, Semana Santa, 18 Sep, bisiesto).",
        y_offset=-0.088,
    )

    # =========================================================================
    # PANEL 4 (Abajo-Derecha): Cuadro Cronológico Mensual del Pulso de Actividad Proyectado
    # =========================================================================
    ax4 = fig.add_subplot(gs[1, 1])
    ax4.set_axis_off()

    niv_pred_arr = np.asarray(proy["nivel_pred"], dtype=float)
    lineas_p4 = [
        f"CUADRO CRONOLÓGICO MENSUAL — PULSO DE ACTIVIDAD PROYECTADO ({mod_sel}):",
        f"{'Mes Proy.':<9} {'Base 12M':>8} {'Índ.Proy':>8} {'Pulso a/a':>9} {'IC 80% (% a/a)':>17} {'IC 95% (% a/a)':>17} {'Δ12TD':>6} {'Ef.Cal':>7} {'Subyac.':>8}",
        "-" * 96,
    ]
    n_mostrar = min(12, horiz_sel)
    for h_i in range(n_mostrar):
        f_str = fechas_fut[h_i].strftime("%Y-%m")
        ic80_str = f"[{yoy_ic80_inf[h_i]:+5.1f}%,{yoy_ic80_sup[h_i]:+5.1f}%]"
