def obtener_ruta_escritorio() -> Path:
    """Detecta la carpeta Escritorio real del usuario (incluyendo OneDrive en Windows)."""
    sistema = platform.system()
    if sistema == "Windows":
        try:
            creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
            salida = subprocess.check_output(
                [
                    "powershell",
                    "-NoProfile",
                    "-Command",
                    "[Environment]::GetFolderPath('Desktop')",
                ],
                text=True,
                stderr=subprocess.DEVNULL,
                creationflags=creationflags,
            ).strip()
            if salida and Path(salida).exists():
                return Path(salida)
        except Exception:
            pass

    for candidato in [
        Path.home() / "Desktop",
        Path.home() / "Escritorio",
        Path.home() / "OneDrive" / "Desktop",
        Path.home() / "OneDrive" / "Escritorio",
    ]:
        if candidato.exists():
            return candidato
    return Path.home()


def generar_icono_app(ruta_ico: Path) -> Optional[Path]:
    """Genera un ícono `.ico` institucional para el ejecutable `.exe` y el Escritorio."""
    try:
        from PIL import Image, ImageDraw
    except ImportError:
        return None

    img = Image.new("RGBA", (256, 256), (15, 61, 110, 255))
    draw = ImageDraw.Draw(img)

    draw.rounded_rectangle(
        [(10, 10), (246, 246)],
        radius=36,
        outline=(217, 119, 6, 255),
        width=8,
    )
    barras_coords = [
        (42, 165, 76, 212, (148, 163, 184, 255)),
        (90, 130, 124, 212, (43, 123, 186, 255)),
        (138, 95, 172, 212, (27, 120, 55, 255)),
        (186, 56, 220, 212, (217, 119, 6, 255)),
    ]
    for x1, y1, x2, y2, col in barras_coords:
        draw.rounded_rectangle([(x1, y1), (x2, y2)], radius=6, fill=col)

    draw.line(
        [(58, 148), (107, 112), (155, 78), (203, 42)],
        fill=(255, 255, 255, 255),
        width=7,
    )

    ruta_ico.parent.mkdir(parents=True, exist_ok=True)
    img.save(
        str(ruta_ico),
        format="ICO",
        sizes=[(256, 256), (128, 128), (64, 64), (48, 48), (32, 32), (16, 16)],
    )
    return ruta_ico


def _escapar_csharp_unicode(texto: str) -> str:
    r"""Convierte cualquier cadena en un literal C# ASCII puro con secuencias \uXXXX."""
    partes: List[str] = []
    bs = chr(92)
    qt = chr(34)
    for ch in str(texto):
        code = ord(ch)
        if ch == bs:
            partes.append(bs + bs)
        elif ch == qt:
            partes.append(bs + qt)
        elif ch == "\r":
            partes.append(bs + "r")
        elif ch == "\n":
            partes.append(bs + "n")
        elif ch == "\t":
            partes.append(bs + "t")
        elif 32 <= code <= 126:
            partes.append(ch)
        else:
            partes.append(f"{bs}u{code:04X}")
    return "".join(partes)


def _obtener_interpretes_python() -> Tuple[Path, Path]:
    """
    Retorna `(python_consola, pythonw_gui)` resolviendo siempre `python.exe` para
    subprocesos CLI y `pythonw.exe` para ejecución gráfica sin consola en Windows.
    """
    actual = Path(sys.executable).resolve()
    if platform.system() != "Windows":
        return actual, actual

    carpeta_py = actual.parent
    py_con = carpeta_py / "python.exe"
    py_gui = carpeta_py / "pythonw.exe"

    if not py_con.is_file():
        local_app = os.environ.get("LOCALAPPDATA", "")
        base_py = (
            Path(local_app) / "Programs" / "Python"
            if local_app
            else Path.home() / "AppData" / "Local" / "Programs" / "Python"
        )
        if base_py.is_dir():
            for sub in sorted(base_py.glob("Python3*"), reverse=True):
                cand_c = sub / "python.exe"
                cand_w = sub / "pythonw.exe"
                if cand_c.is_file():
                    py_con = cand_c
                    py_gui = cand_w if cand_w.is_file() else cand_c
                    break

    python_consola = py_con if py_con.is_file() else actual
    pythonw_gui = py_gui if py_gui.is_file() else python_consola
    return python_consola, pythonw_gui


def sincronizar_copias_locales_script() -> Path:
    """
    Sincroniza automáticamente el código fuente más reciente entre la carpeta de trabajo
    del usuario (`OneDrive/Escritorio/Análisis/app Análisis/EcoPulse_Analytics.py`) y el
    directorio de instalación (`~/EcoPulse_Analytics/EcoPulse_Analytics.py`), garantizando
    que tanto el ejecutable `.exe` como el instalador empaqueten siempre la última versión.
    """
    carpeta_instalacion = RUTA_DIRECTORIO_APP
    carpeta_instalacion.mkdir(parents=True, exist_ok=True)
    script_destino = carpeta_instalacion / "EcoPulse_Analytics.py"

    if getattr(sys, "frozen", False):
        return script_destino

    home = Path.home()
    script_actual = Path(__file__).resolve()
    candidatos = [
        script_actual,
        home / "OneDrive" / "Escritorio" / "Análisis" / "app Análisis" / "EcoPulse_Analytics.py",
        home / "OneDrive" / "Escritorio" / "Análisis" / "app Análisis" / "ecopulse_analytics.py",
        home / "Escritorio" / "Análisis" / "app Análisis" / "EcoPulse_Analytics.py",
        home / "Escritorio" / "Análisis" / "app Análisis" / "ecopulse_analytics.py",
        home / "Desktop" / "Análisis" / "app Análisis" / "EcoPulse_Analytics.py",
        home / "OneDrive" / "Escritorio" / "EcoPulse_Analytics.py",
        home / "Escritorio" / "EcoPulse_Analytics.py",
        script_destino,
    ]

    mejor_script = script_actual
    try:
        if script_actual.resolve() == script_destino.resolve():
            mejor_mtime = script_actual.stat().st_mtime if script_actual.is_file() else 0.0
            for cand in candidatos:
                try:
                    if cand.is_file():
                        mt = cand.stat().st_mtime
                        if mt > mejor_mtime + 0.5:
                            mejor_mtime = mt
                            mejor_script = cand.resolve()
                except Exception:
                    pass
    except Exception:
        pass

    try:
        if mejor_script.is_file() and mejor_script.resolve() != script_destino.resolve():
            shutil.copy2(mejor_script, script_destino)
    except Exception:
        pass

    script_compat = carpeta_instalacion / "cuentas_nacionales_bcch.py"
    try:
        if script_destino.is_file():
            shutil.copy2(script_destino, script_compat)
    except Exception:
        pass

    # Sincronizar también instalar_escritorio.py hacia ~/EcoPulse_Analytics si existe junto al script
    for carpeta_cand in (mejor_script.parent, script_actual.parent, Path.cwd()):
        inst_cand = carpeta_cand / "instalar_escritorio.py"
        if inst_cand.is_file():
            try:
                inst_dest = carpeta_instalacion / "instalar_escritorio.py"
                if inst_cand.resolve() != inst_dest.resolve():
                    shutil.copy2(inst_cand, inst_dest)
            except Exception:
                pass
            break

    return script_destino if script_destino.is_file() else script_actual


