    def _poblar_tabla_ipc_anio(*_args) -> None:
        for item in tree_ipc.get_children():
            tree_ipc.delete(item)
        y_sel = int(var_anio_tabla_ipc.get() or 2026)
        for m_i in range(1, 13):
            nom_m = NOMBRES_MESES_ES[m_i - 1]
            d_m = serie_ipc_ine.get((y_sel, m_i), {})
            utm_v = d_m.get("utm", np.nan)
            uta_v = d_m.get("uta", np.nan)
            ipc_v = d_m.get("ipc", np.nan)
            mom_v = d_m.get("mom", np.nan)
            ac_v = d_m.get("acum", np.nan)
            yoy_v = d_m.get("yoy", np.nan)
            tree_ipc.insert(
                "",
                tk.END,
                values=(
                    nom_m,
                    f"${utm_v:,.0f}".replace(",", ".") if np.isfinite(utm_v) else "—",
                    f"${uta_v:,.0f}".replace(",", ".") if np.isfinite(uta_v) else "—",
                    f"{ipc_v:.2f}".replace(".", ",") if np.isfinite(ipc_v) else "Pendiente INE",
                    f"{mom_v:+.1f}%".replace(".", ",") if np.isfinite(mom_v) else "—",
                    f"{ac_v:+.1f}%".replace(".", ",") if np.isfinite(ac_v) else "—",
                    f"{yoy_v:+.1f}%".replace(".", ",") if np.isfinite(yoy_v) else "—",
                ),
            )

    cb_anio_tbl_ipc.bind("<<ComboboxSelected>>", _poblar_tabla_ipc_anio)
    _poblar_tabla_ipc_anio()

    def _ejecutar_calculo_ipc(*_args) -> None:
        m_ini_nom = var_ipc_mes_ini.get()
        a_ini = int(var_ipc_anio_ini.get() or 2025)
        m_fin_nom = var_ipc_mes_fin.get()
        a_fin = int(var_ipc_anio_fin.get() or 2026)
        m_ini = NOMBRES_MESES_ES.index(m_ini_nom) + 1 if m_ini_nom in NOMBRES_MESES_ES else 9
        m_fin = NOMBRES_MESES_ES.index(m_fin_nom) + 1 if m_fin_nom in NOMBRES_MESES_ES else 9

        # Si el usuario selecciona Octubre/Noviembre/Diciembre 2026 (cuyo IPC aún no ha publicado el INE), usar Septiembre 2026
        if (a_fin, m_fin) not in serie_ipc_ine or not np.isfinite(serie_ipc_ine[(a_fin, m_fin)].get("ipc", np.nan)):
            a_fin, m_fin = 2026, 9
            m_fin_nom = NOMBRES_MESES_ES[m_fin - 1]
            var_ipc_mes_fin.set(m_fin_nom)
        if (a_ini, m_ini) not in serie_ipc_ine or not np.isfinite(serie_ipc_ine[(a_ini, m_ini)].get("ipc", np.nan)):
            a_ini, m_ini = 2025, 9
            m_ini_nom = NOMBRES_MESES_ES[m_ini - 1]
            var_ipc_mes_ini.set(m_ini_nom)

        raw_val = var_ipc_valor_ajustar.get().strip().replace("$", "").replace("CLP", "").replace(" ", "").replace(".", "").replace(",", ".")
        try:
            monto_ini = max(0.0, float(raw_val))
        except Exception:
            monto_ini = 1000000.0

        ipc_0 = float(serie_ipc_ine[(a_ini, m_ini)]["ipc"])
        ipc_1 = float(serie_ipc_ine[(a_fin, m_fin)]["ipc"])

        # Cálculo interno con 12 decimales según nota metodológica de calculadoraipc.ine.cl
        factor_12d = round(ipc_1 / ipc_0, 12) if ipc_0 > 0 else 1.0
        var_exacta_pct = (factor_12d - 1.0) * 100.0
        var_oficial_1d = round(var_exacta_pct, 1)
        monto_ajustado = round(monto_ini * factor_12d)
        dif_pesos = monto_ajustado - round(monto_ini)

        var_res_ipc_titulo.set(f"REAJUSTE OFICIAL INE: {m_ini_nom.upper()} {a_ini}  ➔  {m_fin_nom.upper()} {a_fin}")
        var_res_ipc_monto_final.set(f"$ {monto_ajustado:,.0f} CLP".replace(",", "."))
        if abs(var_oficial_1d) < 1e-9:
            var_res_ipc_variacion_1d.set("Sin variación (0,0 %)")
        else:
            s_v = "+" if var_oficial_1d > 0 else ""
            var_res_ipc_variacion_1d.set(f"{s_v}{var_oficial_1d:.1f} %".replace(".", ","))
        s_d = "+" if dif_pesos >= 0 else "-"
        var_res_ipc_dif_pesos.set(f"{s_d}$ {abs(dif_pesos):,.0f} CLP".replace(",", "."))
        var_res_ipc_detalle.set(
            f"IPC {m_ini_nom[:3]} {a_ini}: {ipc_0:.2f} pts  •  IPC {m_fin_nom[:3]} {a_fin}: {ipc_1:.2f} pts  •  "
            f"Factor (12 dec.): {factor_12d:.12f}  •  Var. exacta: {var_exacta_pct:+.2f}%".replace(".", ",")
        )

    btn_calc_ipc.configure(command=_ejecutar_calculo_ipc)
    cb_ipc_m_ini.bind("<<ComboboxSelected>>", _ejecutar_calculo_ipc)
    cb_ipc_a_ini.bind("<<ComboboxSelected>>", _ejecutar_calculo_ipc)
