    def _fmt_clp_dec(val_f: float, dec: int = 2) -> str:
        s = f"{val_f:,.{dec}f}"
        return s.replace(",", "X").replace(".", ",").replace("X", ".")

    def _poblar_tabla_sii_uf(*_args) -> None:
        for it in tree_uf_sii.get_children():
            tree_uf_sii.delete(it)
        for it in tree_uf_eq.get_children():
            tree_uf_eq.delete(it)

        y_u = int(var_uf_anio.get() or 2026)
        m_nom = var_mes_tabla_sii.get()
        m_u = NOMBRES_MESES_ES.index(m_nom) + 1 if m_nom in NOMBRES_MESES_ES else 10
        tbl_u = obtener_tabla_uf_diaria_oficial_sii(y_u)

        for fila_i in range(1, 12):
            d_a = fila_i if fila_i <= 10 else None
            d_b = (fila_i + 10) if fila_i <= 10 else None
            d_c = (fila_i + 20) if (fila_i + 20) <= 31 else None

            v_a = tbl_u.get((m_u, d_a)) if d_a else None
            v_b = tbl_u.get((m_u, d_b)) if d_b else None
            v_c = tbl_u.get((m_u, d_c)) if d_c else None

            tree_uf_sii.insert(
                "",
                tk.END,
                values=(
                    str(d_a) if d_a else "",
                    f"${_fmt_clp_dec(v_a, 2)}" if v_a is not None else "—",
                    str(d_b) if d_b else "",
                    f"${_fmt_clp_dec(v_b, 2)}" if v_b is not None else "—",
                    str(d_c) if d_c else "",
                    f"${_fmt_clp_dec(v_c, 2)}" if v_c is not None else "—",
                ),
            )

        raw_m = var_uf_monto_in.get().strip().replace("$", "").replace(" ", "").replace(".", "").replace(",", ".")
        try:
            m_val = max(0.0, float(raw_m))
        except Exception:
            m_val = 100.0
        modo_act = var_uf_modo_conv.get()

        dias_disp = sorted([d for (mm, d) in tbl_u.keys() if mm == m_u])
        for d_k in dias_disp:
            v_k = tbl_u[(m_u, d_k)]
            v_prev = tbl_u.get((m_u, d_k - 1), v_k)
            dif_d = v_k - v_prev
            if modo_act == "UF_A_CLP":
                eq_str = f"$ {_fmt_clp_dec(m_val * v_k, 0)} CLP"
            else:
                eq_str = f"{_fmt_clp_dec(m_val / v_k, 4)} UF"
            tree_uf_eq.insert(
                "",
                tk.END,
                values=(
                    f"{d_k:02d}/{m_u:02d}/{y_u}",
                    f"$ {_fmt_clp_dec(v_k, 2)}",
                    f"{'+' if dif_d >= 0 else ''}${_fmt_clp_dec(dif_d, 2)}",
                    eq_str,
                ),
            )

    def _on_select_fila_uf_eq(_ev=None) -> None:
        sel = tree_uf_eq.selection()
        if not sel:
            return
        vals = tree_uf_eq.item(sel[0], "values")
        if vals and "/" in str(vals[0]):
            partes = str(vals[0]).split("/")
            var_uf_dia.set(str(int(partes[0])))
            var_uf_mes.set(NOMBRES_MESES_ES[int(partes[1]) - 1])
            var_uf_anio.set(partes[2])
            _ejecutar_calculo_uf()

    tree_uf_eq.bind("<<TreeviewSelect>>", _on_select_fila_uf_eq)
    cb_mes_tabla_sii.bind("<<ComboboxSelected>>", _poblar_tabla_sii_uf)

    def _ejecutar_calculo_uf(*_args) -> None:
        import calendar
        y_u = int(var_uf_anio.get() or 2026)
        m_nom = var_uf_mes.get()
        m_u = NOMBRES_MESES_ES.index(m_nom) + 1 if m_nom in NOMBRES_MESES_ES else 11
        max_d = calendar.monthrange(y_u, m_u)[1]
        d_u = min(max_d, max(1, int(var_uf_dia.get() or 4)))

        tbl_u = obtener_tabla_uf_diaria_oficial_sii(y_u)
        # Si en noviembre/diciembre 2026 el usuario elige un día posterior al 9 de noviembre (aún no publicado por el SII), usar 9 de noviembre
        if (m_u, d_u) not in tbl_u:
            if y_u == 2026 and m_u >= 11:
                m_u, d_u = 11, min(d_u, 9)
                m_nom = NOMBRES_MESES_ES[m_u - 1]
                var_uf_mes.set(m_nom)
                var_uf_dia.set(str(d_u))

        uf_val = tbl_u.get((m_u, d_u), 41268.88)

        # Comparación con 1 día antes, 30 días antes y 365 días antes
        dt_curr = pd.Timestamp(year=y_u, month=m_u, day=d_u)
        dt_30d = dt_curr - pd.Timedelta(days=30)
        dt_1y = dt_curr - pd.Timedelta(days=365)
        uf_30d = obtener_tabla_uf_diaria_oficial_sii(dt_30d.year).get((dt_30d.month, dt_30d.day), uf_val * 0.996)
        uf_1y = obtener_tabla_uf_diaria_oficial_sii(dt_1y.year).get((dt_1y.month, dt_1y.day), uf_val / 1.0417)

        raw_m = var_uf_monto_in.get().strip().replace("$", "").replace("UF", "").replace("CLP", "").replace(" ", "").replace(".", "").replace(",", ".")
        try:
            monto_in = max(0.0, float(raw_m))
        except Exception:
            monto_in = 100.0

        var_uf_valor_dia_lbl.set(f"1 UF Oficial SII ({d_u:02d} de {m_nom} de {y_u})  =  $ {_fmt_clp_dec(uf_val, 2)} CLP")
        dif_1y_uf = uf_val - uf_1y
        pct_1y_uf = ((uf_val / uf_1y) - 1.0) * 100.0 if uf_1y > 0 else 0.0
        var_uf_tramo_lbl.set(
            f"Fuente: sii.cl/valores_y_fechas/uf/uf{y_u}.htm  •  Hace 30 días: ${_fmt_clp_dec(uf_30d, 2)}  •  "
            f"Hace 1 año: ${_fmt_clp_dec(uf_1y, 2)} ({'+' if dif_1y_uf >= 0 else ''}${_fmt_clp_dec(dif_1y_uf, 2)} | {pct_1y_uf:+.2f}%)"
        )

        if var_uf_modo_conv.get() == "UF_A_CLP":
            pesos_exacto = monto_in * uf_val
            pesos_red = round(pesos_exacto)
            dif_30d_p = round(monto_in * (uf_val - uf_30d))
            dif_1y_p = round(monto_in * (uf_val - uf_1y))
            var_res_uf_principal.set(f"$ {_fmt_clp_dec(pesos_exacto, 2)} CLP")
            var_res_uf_redondeado.set(
                f"Monto redondeado al peso: $ {_fmt_clp_dec(pesos_red, 0)} CLP   │   Cantidad: {_fmt_clp_dec(monto_in, 2)} UF × $ {_fmt_clp_dec(uf_val, 2)}"
            )
            var_res_uf_comparativa.set(
                f"Variación del monto ({_fmt_clp_dec(monto_in, 2)} UF):  vs. hace 30 días: {'+' if dif_30d_p >= 0 else ''}${_fmt_clp_dec(dif_30d_p, 0)} CLP   │   "
                f"vs. hace 1 año: {'+' if dif_1y_p >= 0 else ''}${_fmt_clp_dec(dif_1y_p, 0)} CLP"
            )
        else:
            uf_eq_6d = monto_in / uf_val if uf_val > 0 else 0.0
            uf_30d_eq = monto_in / uf_30d if uf_30d > 0 else 0.0
            uf_1y_eq = monto_in / uf_1y if uf_1y > 0 else 0.0
            var_res_uf_principal.set(f"{_fmt_clp_dec(uf_eq_6d, 2)} UF   ({_fmt_clp_dec(uf_eq_6d, 6)} UF)")
            var_res_uf_redondeado.set(
                f"Monto ingresado: $ {_fmt_clp_dec(monto_in, 0)} CLP   ÷   UF del día ($ {_fmt_clp_dec(uf_val, 2)} CLP)"
            )
            var_res_uf_comparativa.set(
                f"El mismo monto en pesos equivalía a:  {_fmt_clp_dec(uf_30d_eq, 2)} UF hace 30 días   │   {_fmt_clp_dec(uf_1y_eq, 2)} UF hace 1 año"
            )

        var_mes_tabla_sii.set(m_nom if m_u <= 11 else "Noviembre")
        _poblar_tabla_sii_uf()

    btn_calc_uf_go.configure(command=_ejecutar_calculo_uf)
