    controlador_menu = {"mostrar_subpantalla": None}

    def navegar_a_vista(clave_destino: str) -> None:
        """
        Cambia de vista en < 1 ms usando únicamente `tkraise()` sin `pack_forget()`
        ni recálculo de geometría de las figuras de Matplotlib.
         Soporta:
          - `"menu"`: Abre el Menú Principal mostrando SOLO las 3 Categorías Principales.
          - `"menu_macro"`: Abre el Menú Principal en la pantalla de Subcategorías de Vistas Macroeconómicas (13 vistas).
          - `"menu_cotizaciones"`: Abre el Menú Principal en la pantalla de Subcategoría de Cotizaciones de Precio (1 vista).
          - `"presentacion"`: Abre directo la Vista de Presentación Profesional.
          - Cualquier clave de `ORDEN_CLAVES_VISTAS`: Abre la vista analítica correspondiente.
        """
        clave_norm = clave_destino.lower().strip()
        fn_sub = controlador_menu.get("mostrar_subpantalla")

        if clave_norm in ("menu", "categorias"):
            vista_activa["clave"] = "menu"
            if callable(fn_sub):
                fn_sub("categorias")
            vistas_frames["menu"].tkraise()
            return

        if clave_norm in ("menu_macro", "macroeconomicas"):
            vista_activa["clave"] = "menu"
            if callable(fn_sub):
                fn_sub("macroeconomicas")
            vistas_frames["menu"].tkraise()
            return

        if clave_norm in ("menu_cotizaciones", "cotizaciones"):
            vista_activa["clave"] = "menu"
            if callable(fn_sub):
                fn_sub("cotizaciones")
            vistas_frames["menu"].tkraise()
            return

        if clave_norm in ("menu_proyecciones", "proyecciones"):
            vista_activa["clave"] = "menu"
            if callable(fn_sub):
                fn_sub("proyecciones")
            vistas_frames["menu"].tkraise()
            return

        if clave_norm in ("menu_modelacion", "modelacion"):
            vista_activa["clave"] = "menu"
            if callable(fn_sub):
                fn_sub("modelacion")
            vistas_frames["menu"].tkraise()
            return

        if clave_norm in ("menu_calculadoras", "calculadoras"):
            vista_activa["clave"] = "menu"
            if callable(fn_sub):
                fn_sub("calculadoras")
            vistas_frames["menu"].tkraise()
            return

        if clave_norm in ("calc_ipc", "calc_uf", "calc_tipo_cambio", "calc-01", "calc-02", "calc-03", "calc01", "calc02", "calc03"):
            mapa_c_dest = {
                "calc-01": "calc_ipc", "calc01": "calc_ipc",
                "calc-02": "calc_uf", "calc02": "calc_uf",
                "calc-03": "calc_tipo_cambio", "calc03": "calc_tipo_cambio",
            }
            cl_inst = mapa_c_dest.get(clave_norm, clave_norm)
            vista_activa["clave"] = cl_inst
            fn_sel_calc = controlador_menu.get("seleccionar_calculadora")
            if callable(fn_sel_calc):
                fn_sel_calc(cl_inst)
            vistas_frames["calculadoras"].tkraise()
            return

        if clave_norm in MAPA_SUBCATEGORIAS_MACRO:
            vista_activa["clave"] = "menu"
            if callable(fn_sub):
                fn_sub(clave_norm)
            vistas_frames["menu"].tkraise()
            return

        if clave_norm in ("menu_busqueda", "busqueda", "buscar_foco"):
            vista_activa["clave"] = "menu"
            if callable(fn_sub):
                fn_sub("buscar_foco" if clave_norm == "buscar_foco" else "busqueda")
            vistas_frames["menu"].tkraise()
            return

        clave_resuelta = resolver_clave_vista_desde_codigo_o_numero(clave_norm)
        if clave_resuelta:
            clave_norm = clave_resuelta

        if clave_norm in MAPA_ALIAS_CLAVES_MACRO_BASE:
            clave_norm = MAPA_ALIAS_CLAVES_MACRO_BASE[clave_norm]

        # Alias de retrocompatibilidad: 'mercados_yf' redirige a la primera vista individual de cotización ('cot_brent')
        if clave_norm == "mercados_yf":
            clave_norm = "cot_brent" 

        if clave_norm != "presentacion" and clave_norm in ORDEN_CLAVES_VISTAS:
            _obtener_o_crear_frame_vista(clave_norm)
        if clave_norm not in vistas_frames:
            vista_activa["clave"] = "menu"
            if callable(fn_sub):
                fn_sub("categorias")
            vistas_frames["menu"].tkraise()
            return

        vista_activa["clave"] = clave_norm

        if clave_norm == "presentacion":
            vistas_frames["presentacion"].tkraise()
            return

        _actualizar_barra_ruta_navegacion_tk(clave_norm)
        _actualizar_visibilidad_filtros_vista(clave_norm)
        frame_macro_contenedor.tkraise()
        vistas_frames[clave_norm].tkraise()
        renderizar_pestana_si_necesario(clave_norm)

    def recalcular_y_redibujar_filtros(*_args) -> None:
        """
        Aplica en memoria (de forma instantánea) los filtros de `Desde`, `Hasta`,
        `Frecuencia` y `Modo` a todas las series. Si el usuario ingresó una fecha `Desde`
        anterior a la descargada en memoria, dispara automáticamente la descarga en BDE.
        """
        nonlocal datos_filtrados_actuales
        if not datos_base_descargados:
            return

        desde_str = var_desde.get().strip() or "1960-01-01"
        hasta_str = var_hasta.get().strip() or date.today().strftime("%Y-%m-%d")
        frec_sel = var_frecuencia_global.get().strip().lower()

        if desde_str < desde_minimo_descargado["fecha"]:
            actualizar_todo()
            return

        datos_filtrados_actuales = aplicar_filtros_universales(
            datos_base=datos_base_descargados,
            desde=desde_str,
            hasta=hasta_str,
            frecuencia=frec_sel,
        )
        pestanas_renderizadas.clear()
        renderizar_pestana_si_necesario(vista_activa["clave"])
        estado_var.set(
            f"✓ Filtros aplicados: {desde_str} a {hasta_str} | Frecuencia: {frec_sel.upper()}"
        )

    combo_frec_global.bind("<<ComboboxSelected>>", recalcular_y_redibujar_filtros)
    combo_modo.bind("<<ComboboxSelected>>", recalcular_y_redibujar_filtros)
    entry_desde.bind("<Return>", recalcular_y_redibujar_filtros)
    entry_hasta.bind("<Return>", recalcular_y_redibujar_filtros)

    def _aplicar_nuevos_datos_en_gui(
        nuevos_datos_base: Dict[str, pd.DataFrame],
        desde_descargado: str,
        etiqueta_estado: str,
        imprimir_consola: bool = False,
    ) -> None:
        nonlocal datos_base_descargados, datos_filtrados_actuales
        datos_base_descargados = nuevos_datos_base
        desde_minimo_descargado["fecha"] = min(
            desde_minimo_descargado["fecha"], desde_descargado
        )
        desde_str = var_desde.get().strip() or "1960-01-01"
        hasta_str = var_hasta.get().strip() or date.today().strftime("%Y-%m-%d")
        frec_sel = var_frecuencia_global.get().strip().lower()

        datos_filtrados_actuales = aplicar_filtros_universales(
            datos_base=datos_base_descargados,
            desde=desde_str,
            hasta=hasta_str,
            frecuencia=frec_sel,
        )
        pestanas_renderizadas.clear()
        renderizar_pestana_si_necesario(vista_activa["clave"])
        estado_var.set(etiqueta_estado)
        if imprimir_consola:
            imprimir_resumen_ejecutivo(datos_filtrados_actuales)

    def actualizar_todo() -> None:
        """
        Sincroniza y actualiza en paralelo (`ThreadPoolExecutor` en un hilo en segundo plano)
        TODAS las fuentes de datos de la aplicación:
          1. BDE Banco Central de Chile (`bcchapi` — Cuentas Nacionales, IMACEC, TCR, Finanzas Públicas,
             Capital e Inversión, Política Monetaria, Sector Externo, Deuda Pública e IPI).
          2. INE / DIPRES (Boletín IPC 13 divisiones, Empleo ENE y Ejecución Presupuestaria).
          3. BACI-CEPII (Comercio bilateral HS6 de Chile `i=152`, último año disponible y carpeta local).
          4. Clapes UC y CNEP (4 índices PTF trimestrales Clapes UC, PTF anual CNEP con/sin minería
             y anexos Excel/CSV locales).
          5. Yahoo Finance en Tiempo Real (`yfinance` — Velas Japonesas OHLC y precios spot de
             Petróleo Brent `BZ=F`, Dólar `USD/CLP`, Futuros del Cobre `HG=F` e `IPSA`).
        """
        nonlocal descarga_en_curso
        if descarga_en_curso:
            return
        descarga_en_curso = True

        desde_str = "1960-01-01"
        hasta_str = var_hasta.get().strip() or None
        estado_var.set(
            "🔄 Actualizando todas las fuentes (BDE BCCh, INE, DIPRES, BACI-CEPII, Clapes UC, CNEP y Yahoo Finance)..."
        )

        def _worker_descarga() -> None:
            nonlocal descarga_en_curso
            t0 = time.perf_counter()
            try:
                nuevos = monitor.descargar_paquete_cuentas_nacionales(
                    desde=desde_str, hasta=hasta_str
                )
                dt = time.perf_counter() - t0
                frec_sel = var_frecuencia_global.get().strip().upper()
                msg = (
                    f"✓ Todas las fuentes al día (BDE, INE, DIPRES, BACI-CEPII, Clapes UC, CNEP y Yahoo Finance | "
                    f"Frec.: {frec_sel}) — {dt:.1f}s"
                )
                root.after(
                    0,
                    lambda: _aplicar_nuevos_datos_en_gui(nuevos, desde_str, msg, True),
                )
            except Exception as exc:
                err_txt = str(exc)

                def _mostrar_error() -> None:
                    estado_var.set("⚠ Usando caché local (sin conexión o error en API).")
                    if not datos_base_descargados:
                        messagebox.showerror(
                            "Error al actualizar fuentes de datos",
                            f"No fue posible sincronizar las fuentes en línea:\n{err_txt}",
                        )

                root.after(0, _mostrar_error)
            finally:
                descarga_en_curso = False

        threading.Thread(target=_worker_descarga, daemon=True).start()

    def carga_inicial_instantanea() -> None:
        desde_str = "1960-01-01"
        cache, es_vigente = monitor.cargar_cache_disco(
            desde=desde_str, retornar_vigencia=True
        )
        if cache is not None:
            if es_vigente:
                _aplicar_nuevos_datos_en_gui(
                    cache,
                    desde_str,
                    "⚡ Carga instantánea desde caché local al día (usa '🔄 Actualizar Datos' para actualizar todas las fuentes)",
                    imprimir_consola=False,
                )
                return
            _aplicar_nuevos_datos_en_gui(
                cache,
                desde_str,
                "⚡ Caché cargado — actualizando series nuevas en segundo plano...",
                imprimir_consola=False,
            )
        else:
            # Primera ejecución sin caché en disco: poblar instantáneamente desde la semilla completa (< 5 ms)
            # para que todas las 86 vistas estén operativas de inmediato mientras descarga en segundo plano
            sem_ini: Dict[str, pd.DataFrame] = {}
            _asegurar_respaldo_offline_completo_macro(sem_ini)
            sem_yf = MonitorCuentasNacionales._semilla_mercados_yahoo_instantanea()
            sem_ini.update(sem_yf)
            _aplicar_nuevos_datos_en_gui(
                sem_ini,
                desde_str,
                "⚡ Plataforma lista instantáneamente — sincronizando fuentes oficiales en segundo plano...",
                imprimir_consola=False,
            )
        actualizar_todo()

