            df_ptf_cn_n = datos_filtrados_actuales["ptf_cnep_nivel"].add_suffix(" (PTF_CNEP_2018=100)")  # type: ignore[union-attr]
            df_ptf_cn_y = datos_filtrados_actuales["ptf_cnep_yoy"].add_suffix(" (PTF_CNEP_Var_a/a_%)")  # type: ignore[union-attr]
            df_yf_n = datos_filtrados_actuales["mercados_yf_nivel"].add_suffix(" (Yahoo_Nivel)")  # type: ignore[union-attr]
            df_yf_y = datos_filtrados_actuales["mercados_yf_yoy"].add_suffix(" (Yahoo_Var_12M_%)")  # type: ignore[union-attr]
            combinado = pib_df.join(
                [
                    df_niv,
                    df_yoy,
                    df_tcr_n,
                    df_tcr_y,
                    df_ipc_n,
                    df_ipc_m,
                    df_ipc_y,
                    df_emp_n,
                    df_emp_y,
                    df_fp_t,
                    df_fp_a,
                    df_cap_s,
                    df_cap_i,
                    df_cap_f,
                    df_mon_t,
                    df_mon_b,
                    df_mon_a,
                    df_ext_cc,
                    df_ext_cf,
                    df_ext_bc,
                    df_ext_bp,
                    df_deu_p,
                    df_bal_f,
                    df_exp_d,
                    df_exp_s,
                    df_ipi_n,
                    df_ipi_y,
                    df_ptf_cl_n,
                    df_ptf_cl_y,
                    df_ptf_cn_n,
                    df_ptf_cn_y,
                    df_yf_n,
                    df_yf_y,
                ],
                how="outer",
            )
            combinado.to_csv(ruta, index_label="Fecha")
            messagebox.showinfo("Exportación exitosa", f"Datos filtrados guardados en:\n{ruta}")

