    def compilar_exe_gui() -> None:
        estado_var.set("📦 Compilando archivo único EcoPulse_Analytics.exe en el Escritorio...")
        root.update_idletasks()

        def _tarea_compilar() -> None:
            try:
                ruta_exe = compilar_ejecutable_standalone_escritorio()
                tam_kb = ruta_exe.stat().st_size / 1024.0 if ruta_exe.is_file() else 0.0
                def _ok() -> None:
                    os.environ["ECOPULSE_LAUNCHED_FROM_EXE"] = "1"
                    for b_w in list(_REGISTRO_BOTONES_COMPILAR_EXE):
                        try:
                            b_w.pack_forget()  # type: ignore[union-attr]
                        except Exception:
                            pass
                    estado_var.set(f"✓ Único archivo EcoPulse_Analytics.exe compilado ({tam_kb:,.0f} KB)")
                    messagebox.showinfo(
                        "Archivo Único EcoPulse_Analytics.exe Compilado",
                        f"Se ha compilado UN SOLO archivo ejecutable autónomo (con el código, ícono y base de datos incrustados dentro del .exe):\n\n"
                        f"• Ruta del ejecutable:\n  {ruta_exe}\n\n"
                        "Este único archivo sirve tanto para abrir la plataforma directamente en tu PC como para copiarlo a cualquier otro PC (donde instalará automáticamente las dependencias si no están presentes).",
                    )
                root.after(0, _ok)
            except Exception as exc:
                err_msg = str(exc)
                def _err() -> None:
                    estado_var.set("Error al compilar .EXE")
                    messagebox.showerror(
                        "Error al compilar .EXE",
                        f"No fue posible compilar el archivo .exe:\n{err_msg}",
                    )
                root.after(0, _err)

        threading.Thread(target=_tarea_compilar, daemon=True).start()

    def abrir_buscador_series() -> None:
        ventana_busq = tk.Toplevel(root)
        ventana_busq.title("Buscador de Series en el Catálogo BDE (siete.buscar)")
        ventana_busq.geometry("880x440")

        top_f = ttk.Frame(ventana_busq, padding=10)
        top_f.pack(fill=tk.X)
        ttk.Label(
            top_f,
            text="Palabra clave (ej. 'Tasa de política monetaria', 'Base monetaria', 'Stock de capital'):",
        ).pack(side=tk.LEFT, padx=(0, 6))
        var_query = tk.StringVar(value="Tasa de política monetaria")
        ttk.Entry(top_f, textvariable=var_query, width=32).pack(side=tk.LEFT, padx=(0, 8))

        cols = ("seriesId", "frequencyCode", "spanishTitle", "lastObservation")
        tree = ttk.Treeview(ventana_busq, columns=cols, show="headings", height=15)
        tree.heading("seriesId", text="Código Serie (seriesId)")
        tree.heading("frequencyCode", text="Frecuencia")
        tree.heading("spanishTitle", text="Título en Español")
        tree.heading("lastObservation", text="Última Obs.")
        tree.column("seriesId", width=240)
        tree.column("frequencyCode", width=95)
        tree.column("spanishTitle", width=420)
        tree.column("lastObservation", width=95)
        tree.pack(fill=tk.BOTH, expand=True, padx=10, pady=(0, 10))

        def ejecutar_busqueda() -> None:
            for item in tree.get_children():
                tree.delete(item)
            df_res = monitor.buscar_series(var_query.get().strip(), limite=40)
            for _, fila in df_res.iterrows():
                tree.insert(
                    "",
                    tk.END,
                    values=(
                        fila.get("seriesId", ""),
                        fila.get("frequencyCode", ""),
                        fila.get("spanishTitle", ""),
                        fila.get("lastObservation", ""),
                    ),
                )

        ttk.Button(top_f, text="Buscar en BDE", command=ejecutar_busqueda).pack(side=tk.LEFT)
        ejecutar_busqueda()

