    def _aplicar_filtro_vela_cotizacion(tipo_f: str, valor_f: object) -> None:
        if tipo_f == "intervalo_vela":
            ESTADO_FILTROS_COTIZACIONES_YF["intervalo_vela"] = str(valor_f)
        elif tipo_f == "num_velas":
            ESTADO_FILTROS_COTIZACIONES_YF["num_velas"] = int(valor_f)  # type: ignore[arg-type]
        _refrescar_estilo_botones_cotizaciones_tk()
        for k_c in CLAVES_VISTAS_COTIZACIONES:
            pestanas_renderizadas.discard(k_c)
        clave_act = vista_activa.get("clave", "")
        if clave_act in MAPA_CLAVE_VISTA_A_ACTIVO_YF:
            col_act = MAPA_CLAVE_VISTA_A_ACTIVO_YF[clave_act]
            num_v = str(mapa_meta_vistas.get(clave_act, {}).get("numero", "14"))
            fig_v, canvas_v = _obtener_o_crear_lienzo_vista(clave_act)
            dibujar_vista_cotizacion_individual_yf(
                datos_filtrados_actuales,
                columna_activo=col_act,
                numero_vista=num_v,
                modo=var_modo_imacec.get(),
                fig=fig_v,
            )
            fig_v._callback_cambio_filtro_yf = controlador_menu.get("aplicar_filtro_vela_cotizacion")  # type: ignore[attr-defined]
            activar_tooltips_interactivos(fig_v, canvas_v)
            canvas_v.draw_idle()
            pestanas_renderizadas.add(clave_act)
            iv_s = str(ESTADO_FILTROS_COTIZACIONES_YF.get("intervalo_vela", "1D"))
            nv_s = int(ESTADO_FILTROS_COTIZACIONES_YF.get("num_velas", 60))  # type: ignore[arg-type]
            txt_nv = "Todas las velas" if nv_s == 0 else f"{nv_s} velas"
            estado_var.set(f"🕯️ Cotización ({col_act}): Vela japonesa [{iv_s}] | Ventana [{txt_nv}]")

