    # Soporte universal de rueda del mouse para canvases con scroll en el Menú Principal
    def _resolver_canvas_scrollable_bajo_cursor(widget_ev) -> Optional[tk.Canvas]:
        w_curr = widget_ev
        while w_curr is not None:
            if isinstance(w_curr, tk.Canvas) and str(w_curr.cget("yscrollcommand")):
                return w_curr
            try:
                w_curr = w_curr.master
            except Exception:
                break
        return None

    def _on_mousewheel_global(event) -> None:
        try:
            cv_target = _resolver_canvas_scrollable_bajo_cursor(event.widget)
            if cv_target is None:
                return
            if getattr(event, "num", None) == 4:
                cv_target.yview_scroll(-3, "units")
            elif getattr(event, "num", None) == 5:
                cv_target.yview_scroll(3, "units")
            else:
                delta_v = int(getattr(event, "delta", 0))
                if delta_v != 0:
                    pasos = -1 if delta_v > 0 else 1
                    cv_target.yview_scroll(pasos * 3, "units")
        except Exception:
            pass

    root.bind_all("<MouseWheel>", _on_mousewheel_global, add="+")
    root.bind_all("<Button-4>", _on_mousewheel_global, add="+")
    root.bind_all("<Button-5>", _on_mousewheel_global, add="+")

